@section('content')
    <h2 class="text-center text-blue-900 font-normal italic text-2xl sm:text-2xl md:text-2xl mt-6 mb-6">Āryanāgārjunapādaviracitaṃ Piṇḍīkṛtasādhanam</h2>
    <h3 class="font-bold text-md text-center mt-6 mb-3">Предисловие переводчика</h3>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p>Настоящая работа представляет собой первый полный русский перевод «Пиндикрита-садханы» (<em>Piṇḍīkṛtasādhana</em>) ачарьи Арья Нагарджуны.</p>
        <p><em>Piṇḍīkṛtasādhana</em> представляет собой краткое изложение последовательности этапов созерцания в соответствии с системой Гухьясамаджа тантры — от предварительных защитных действий и построения основы мандалы до порождения божеств, работы с мантрами и семенными слогами, очищения элементов, скандх и аятан, практик, связанных с супругой-мудрой, внутреннего подношения и последующего растворения мандалы.</p>
        <p>Перевод выполнен с санскритского текста с параллельной сверкой с тибетской канонической версией. Санскритская версия сверялась по цифровой публикации текста в проекте Digital Sanskrit Buddhist Canon. Согласно тибетскому колофону, перевод на тибетский язык был выполнен индийским наставником Шраддхакаравармой и тибетским переводчиком Ринченом Зангпо, а позднее перепроверен Чаг Лоцавой Чойджэпалом в присутствии махаваджрадхары Реванты по магадхской рукописи.</p>
        <p>Деление строф было принято на основании работы Ronit S. Sayer, <em>The Guhyasamāja Piṇḍīkṛta-sādhana and its Context</em>, где автором было предложено параллельное сопоставление санскритского оригинала, тибетского перевода и английского перевода. Для дополнительной сверки привлекалась работа <em>The Five Stages (Pañcakrama) and Condensed Stage (Piṇḍikrama) of Nāgārjunapāda with the Gloss Pañcakramaṭippaṇī of Parahitarakṣita</em>, подготовленная по санскритскому оригиналу с привлечением тибетских версий.</p>
        <p>Стихотворная часть текста преимущественно написана в размере <em>anuṣṭubh</em>, в отдельных разделах используются другие метрические формы, в частности, песни богинь в шлоках 206–209 и заключительные строфы.</p>
        <p>Для облегчения работы с переводом настоящее издание включает дополнительные материалы:<br>— полный санскритский текст в транслитерации IAST, помещённый в конце книги с той же разбивкой по шлокам, что и русский перевод;<br>— примечания к отдельным терминам, выражениям и спорным местам;<br>— комментарии, поясняющие отдельные элементы практики и их место в системе Гухьясамаджи;<br>— таблицы, систематизирующие положение, цвет, лики, атрибуты, очищаемые аспекты и другие характеристики божеств мандалы;<br>— дополнительные схемы и материалы, облегчающие чтение структуры мандалы и последовательности визуализации.</p>
        <p>Задача этого издания состоит не только в том, чтобы сделать санскритский текст доступным на русском языке, но и в том, чтобы сохранить возможность его текстологического и доктринального чтения. Поэтому в спорных местах предпочтение отдаётся прозрачности, а санскритский оригинал по возможности приводится в скобках.</p>
        <p>Труд посвящается моему коренному Учителю. Я выражаю глубокую благодарность всем, кто участвовал в обсуждении трудных мест текста, помогал в его чтении и сверке, и особенно моей жене Ольге — за неизменную поддержку, понимание и безграничное терпение. Пусть эта работа послужит на благо всех живых существ.</p>
        <p class="text-right italic">Перевод, составление примечаний, вёрстка, таблицы и схемы: О. Л. Волошановский. Август 2026 г., Киев.</p>
    </div>

