        <h3 class="font-bold text-md text-center mt-6 mb-3">(1. Поклонение)</h3>
        <div>
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>1.</strong> Воздаю почтение Телу (<em>kāya</em>) Победоносных —</li>
                <li>единому проявлению,<a href="#citation-1" id="ref-1" class="citation-mark"><sup>1</sup></a></li>
                <li>свободному от умопостроений (<em>nirvikalpaikamūrti</em>),<a href="#citation-2" id="ref-2" class="citation-mark"><sup>2</sup></a></li>
                <li>обладающему несравненным и равным блаженством (<em>sukhamasamasama</em>);<a href="#citation-3" id="ref-3" class="citation-mark"><sup>3</sup></a></li>
                <li>вышедшему за пределы деятельности трёх миров,<a href="#citation-4" id="ref-4" class="citation-mark"><sup>4</sup></a></li>
                <li>ставшему равным пространству,<a href="#citation-5" id="ref-5" class="citation-mark"><sup>5</sup></a></li>
                <li>чья природа есть собственная природа всех явлений (<em>sarvabhāvasvabhāva</em>);<a href="#citation-6" id="ref-6" class="citation-mark"><sup>6</sup></a></li>
                <li>чистому,<a href="#citation-7" id="ref-7" class="citation-mark"><sup>7</sup></a></li>
                <li>умиротворённому,<a href="#citation-8" id="ref-8" class="citation-mark"><sup>8</sup></a></li>
                <li>свободному от всего постороннего (<em>vivikta</em>),<a href="#citation-9" id="ref-9" class="citation-mark"><sup>9</sup></a></li>
                <li>пронизанному высшим благим покоем (<em>paramaśivamaya</em>)<a href="#citation-10" id="ref-10" class="citation-mark"><sup>10</sup></a></li>
                <li>и постижимому лишь практикующими йогу;<a href="#citation-11" id="ref-11" class="citation-mark"><sup>11</sup></a></li>
                <li>труднопостижимому,<a href="#citation-12" id="ref-12" class="citation-mark"><sup>12</sup></a></li>
                <li>сложному для рассудочного анализа,<a href="#citation-13" id="ref-13" class="citation-mark"><sup>13</sup></a></li>
                <li>приносящему величайшее благо себе и другим,<a href="#citation-14" id="ref-14" class="citation-mark"><sup>14</sup></a></li>
                <li>всепроникающему<a href="#citation-15" id="ref-15" class="citation-mark"><sup>15</sup></a></li>
                <li>и пребывающему вне образов (<em>nirnimitta</em>).<a href="#citation-16" id="ref-16" class="citation-mark"><sup>16</sup></a></li>
            </ul>
        </div>
        <h3 class="font-bold text-md text-center mt-6 mb-3">(2. Побуждение и цель практики)</h3>
        <div>
            <!-- Шлока 2 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>2.</strong> Опираясь на постижение</li>
                <li>шести пределов смысла (<em>ṣaṭkoṭyarthāvabodhataḥ</em>)<a href="#citation-17" id="ref-17" class="citation-mark"><sup>17</sup></a></li>
                <li>славной «Тантры собрания» (<em>śrīmatsamājatantrasya</em>)</li>
                <li>я изложу этот сжатый метод (<em>piṇḍīkrama</em>),<a href="#citation-18" id="ref-18" class="citation-mark"><sup>18</sup></a></li>
                <li>несущий благо всем живым существам (<em>sarvasattvahitodayam</em>.<a href="#citation-19" id="ref-19" class="citation-mark"><sup>19</sup></a></li>
            </ul>
            <!-- Шлока 3 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>3.</strong> Мудрый, полностью распознав изъяны</li>
                <li>в виде отпечатков умозрительных построений (<em>vikalpavāsanādoṣa</em>),<a href="#citation-20" id="ref-20" class="citation-mark"><sup>20</sup></a></li>
                <li>вводящих в заблуждение существ трёх миров,<a href="#citation-21" id="ref-21" class="citation-mark"><sup>21</sup></a></li>
                <li>должен очистить их посредством Йога-тантры (<em>yogatantreṇa</em>).<a href="#citation-22" id="ref-22" class="citation-mark"><sup>22</sup></a></li>
            </ul>
            <!-- Шлока 4 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>4.</strong> Полностью оставив пять объектов желаний (<em>pañca kāmān</em>),<a href="#citation-23" id="ref-23" class="citation-mark"><sup>23</sup></a></li>
                <li>не следует истязать себя аскезой (<em>tapas</em>).<a href="#citation-24" id="ref-24" class="citation-mark"><sup>24</sup></a></li>
                <li>Следуя учению Йога-тантры (<em>yogatantrānusārataḥ</em>),<a href="#citation-25" id="ref-25" class="citation-mark"><sup>25</sup></a></li>
                <li>практикующему следует поддерживать Пробуждение (<em>bodhi</em>)</li>
                <li>посредством блаженства (<em>sukhena</em>).<a href="#citation-26" id="ref-26" class="citation-mark"><sup>26</sup></a></li>
            </ul>
            <!-- Шлока 5 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>5.</strong> Поэтому этот практикующий,</li>
                <li>пребывающий в <strong>самваре</strong> (<em>saṃvarasthaḥ</em>),<a href="#citation-27" id="ref-27" class="citation-mark"><sup>27</sup></a></li>
                <li>всегда непоколебимо соблюдающий свои обеты,<a href="#citation-28" id="ref-28" class="citation-mark"><sup>28</sup></a></li>
                <li>должен приступить к практике Ваджра Тела, Речи и Ума.<a href="#citation-29" id="ref-29" class="citation-mark"><sup>29</sup></a></li>
            </ul>
        </div>
        <h3 class="font-bold text-md text-center mt-6 mb-3">(3. Место и подготовка к практике)</h3>
        <div>
            <!-- Шлока 6 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>6.</strong> В глухих лесных местностях,</li>
                <li>украшенных плодами, цветами и прочим,</li>
                <li>либо на безлюдной горе<a href="#citation-30" id="ref-30" class="citation-mark"><sup>30</sup></a></li>
                <li>следует осуществлять совокупность всех сиддхи (<em>sarvasiddhisamuccaya</em>).<a href="#citation-31" id="ref-31" class="citation-mark"><sup>31</sup></a></li>
            </ul>
            <!-- Шлока 7 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>7.</strong> Усевшись на мягкое сиденье (<em>mṛdvāsana</em>),<a href="#citation-32" id="ref-32" class="citation-mark"><sup>32</sup></a></li>
                <li>приняв позу бодхисаттвы (<em>sattvaparyaṅka</em>),<a href="#citation-33" id="ref-33" class="citation-mark"><sup>33</sup></a></li>
                <li>пребывая в самадхи Ваджра Гнева (<em>dveṣavajra</em>),<a href="#citation-34" id="ref-34" class="citation-mark"><sup>34</sup></a></li>
                <li>пусть практикующий созерцает защиту места практики (<em>sthānarakṣā</em>).<a href="#citation-35" id="ref-35" class="citation-mark"><sup>35</sup></a></li>
            </ul>
        </div>
