                    ВАДЖРАКИИЛА ВАДЖРАДХАРА ААДЖНЯАПАЯТИ САРВАВИГХНААН<br>
                    КААЯВААКЧИТТАВАДЖРАМ КИИЛАЯ ХУМ ХУМ ХУМ ПХАТ)</li>
                <li>(«Ом! ГХА! ГХА! Порази, порази всех вредоносных! ПХАТ! ПХАТ!<br>
                    Пригвозди, пригвозди всё неблагое! ПХАТ! ПХАТ! ХУМ! ХУМ! ХУМ!<br>
                    О Ваджракила! Ваджрадхара повелевает: пригвозди всех препятствующих<br>
                    Ваджром Тела, Речи и Ума! ХУМ! ХУМ! ХУМ! ПХАТ!»)</li>
            </ul>
            <!-- Шлока 14 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>14.</strong> Затем следует созерцать Сумбхараджу (<em>Sumbharāja</em>),</li>
                <li>держащего в руке ваджрный молот (<em>vajramudgara</em>).<a href="#citation-53" id="ref-53" class="citation-mark"><sup>53</sup></a></li>
            </ul>
            <!-- Шлока 15 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>15.</strong> Созерцая ваджрный огонь (<em>vajravahni</em>),</li>
                <li>распространяющийся во всех направлениях (<em>vispharantaṃ samantāt</em>),</li>
                <li>пусть практикующий представляет злобных существ (<em>duṣṭān</em>),</li>
                <li>которые, испуская вопли (<em>pralapitān</em>),</li>
                <li>сгорают (<em>dahyamānān</em>), мечась во все стороны (<em>itastataḥ</em>).<a href="#citation-54" id="ref-54" class="citation-mark"><sup>54</sup></a></li>
            </ul>
            <!-- Шлока 16 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>16.</strong> Пригвоздив килой десять направлений и благословив верх и низ,</li>
                <li>пусть практикующий в свете высшей истины созерцает три мира</li>
                <li>как не имеющие [неизменной] собственной природы (<em>niḥsvabhāva</em>).<a href="#citation-55" id="ref-55" class="citation-mark"><sup>55</sup></a></li>
            </ul>
        </div>
        <h3 class="font-bold text-md text-center mt-6 mb-3">(5. Растворение и Шуньята)</h3>
        <div>
            <!-- Шлока 17 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>17.</strong> В отсутствии (<em>abhāva</em>) [явления]</li>
                <li>отсутствует и [его] созерцание (<em>bhāvanā</em>);</li>
                <li>созерцание вовсе не является созерцанием [само по себе].</li>
                <li>Так и явление (<em>bhāva</em>) не является явлением;</li>
                <li>и само созерцание не обнаруживается (<em>nopalabhyate</em>).<a href="#citation-56" id="ref-56" class="citation-mark"><sup>56</sup></a></li>
            </ul>
            <!-- Шлока 18 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>18.</strong> Посредством этой строфы, созерцая шунью (<em>śūnya</em>) всего подвижного и неподвижного,<a href="#citation-57" id="ref-57" class="citation-mark"><sup>57</sup></a></li>
                <li>посредством данного метода<a href="#citation-58" id="ref-58" class="citation-mark"><sup>58</sup></a></li>
                <li>утверждается Основа Мудрости (<em>jñānabhūmi</em>).<a href="#citation-57" id="ref-57" class="citation-mark"><sup>57</sup></a></li>
            </ul>
        </div>
        <h3 class="font-bold text-md text-center mt-6 mb-3">(6. Мандала четырёх махабхути)</h3>
        <div>
            <!-- Шлока 19 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>19.</strong> В центре пространства (<em>ākāśadhātu</em>) пусть практикующий созерцает мандалу ветра (<em>vāyumaṇḍala</em>),</li>
                <li>возникшую из двух слогов <span class="font-bold italic text-red-700">HŪṀ</span> и семенного слога <span class="font-bold italic text-red-700">YAṀ</span> и украшенную двумя ваджрами (<em>vajradvayasamāyuta</em>).<a href="#citation-59" id="ref-59" class="citation-mark"><sup>59</sup></a></li>
            </ul>
            <!-- Шлока 20 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>20.</strong> Над ней пусть практикующий созерцает мандалу огня (<em>agnimaṇḍala</em>),</li>
                <li>возникшую из двух слогов <span class="font-bold italic text-red-700">HŪṀ</span> и семенного слога <span class="font-bold italic text-red-700">RAṀ</span> (<em>dvihūṃraṃbījaniṣpanna</em>),</li>
                <li>отмеченную двумя ваджрами (<em>vajradvayasamāṅkita</em>).<a href="#citation-60" id="ref-60" class="citation-mark"><sup>60</sup></a></li>
            </ul>
            <!-- Шлока 21 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>21.</strong> Над ней пусть он созерцает мандалу воды (<em>vārimaṇḍala</em>),</li>
                <li>возникшую из двух слогов <span class="font-bold italic text-red-700">HŪṀ</span> и семенного слога <span class="font-bold italic text-red-700">VAṀ</span> (<em>dvihūṃvaṃbījaniṣpanna</em>),</li>
                <li>отмеченную двумя ваджрами (<em>vajradvayasamāyuta</em>).<a href="#citation-61" id="ref-61" class="citation-mark"><sup>61</sup></a></li>
            </ul>
            <!-- Шлока 22 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>22.</strong> Над ней пусть созерцает мандалу земли (<em>pṛthivīmaṇḍala</em>),</li>
                <li>возникшую из двух слогов <span class="font-bold italic text-red-700">HŪṀ</span> и семенного слога <span class="font-bold italic text-red-700">LAṀ</span> (<em>dvihūṃlaṃbījaniṣpanna</em>),</li>
                <li>отмеченную двумя ваджрами (<em>vajradvayasamanvita</em>).<a href="#citation-62" id="ref-62" class="citation-mark"><sup>62</sup></a></li>
            </ul>
        </div>
        <h3 class="font-bold text-md text-center mt-6 mb-3">(7. Дворец)</h3>
        <div>
            <!-- Шлока 23 -->
            <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
                <li><strong>23.</strong> Поверх четырёх объединённых мандал элементов (<em>caturmaṇḍalasaṃhāra</em>) следует созерцать мандалу ваджрного основания (<em>vajrabhūbhāgamaṇḍala</em>).</li>
                <li>На ней пусть практикующий визуализирует дворец (<em>kūṭāgāra</em>), возникший из слога <span class="font-bold italic text-red-700">BHRŪṀ</span> (<em>bhrūṃkāraniṣpanna</em>).<a href="#citation-63" id="ref-63" class="citation-mark"><sup>63</sup></a></li>
            </ul>
            <!-- Шлока 24 -->
            <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
                <li><strong>24.</strong> Этот дворец квадратной формы, с четырьмя вратами,<a href="#citation-64" id="ref-64" class="citation-mark"><sup>64</sup></a> украшенный четырьмя арками, с четырьмя осевыми линиями и восемью колоннами.</li>
            </ul>
            <!-- Шлока 25 -->
            <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
                <li><strong>25.</strong> Он украшен гирляндами и полугирляндами, драгоценными камнями, ваджрами и полумесяцами;</li>
                <li>в местах соединения ворот и выступающих надвратных частей он инкрустирован ваджрными самоцветами.</li>
            </ul>
            <!-- Шлока 26 -->
            <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
                <li><strong>26.</strong> Он украшен великими ваджрными колоннами с кувшинными основаниями (<em>kumbhastambhamahāvajra</em>), фризом из птиц на венчающем карнизе (<em>kramaśīrṣas tu pakṣiṇī</em>),</li>
                <li>а также колокольчиками, знамёнами, чамарами и другими ритуальными украшениями (<em>ghaṇṭāpatākasaṃśobhaṃ cāmarādivibhūṣitam</em>).<a href="#citation-65" id="ref-65" class="citation-mark"><sup>65</sup></a></li>
            </ul>
        </div>
        <h3 class="font-bold text-md text-center mt-6 mb-3">(8. Размещение во Дворце 32-х божеств)</h3>
        <div>
            <!-- Шлока 27 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>27.</strong> В центре мандалы пусть практикующий созерцает самого себя, соединённого с супругой-мудрой (<em>mudrā</em>), имеющего три лика и шесть рук и сияющего подобно драгоценному синему сапфиру индранила (<em>indranīla</em>).</li>
            </ul>
            <!-- Шлока 28 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>28.</strong> Славного Вайрочану, Ратнасамбхаву, Амитабху и Амогхасиддхи следует созерцать по сторонам света, начиная с востока; все они неизменно предстают трёхликими и шестирукими.</li>
            </ul>
            <!-- Шлока 29 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>29.</strong> Богинь, начиная с Мохарати и остальных, также трёхликих и шестируких, следует разместить в установленной последовательности, начиная с юго-восточного направления.</li>
            </ul>
            <!-- Шлока 30 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>30.</strong> Подобным же образом Рупаваджру и других [богинь] следует разместить по четырём внешним углам, тогда как Спаршаваджра пребывает в единении с Ваджрасаттвой (<em>vajrasattvasamāyutā</em>).</li>
            </ul>
            <!-- Шлока 31 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>31.</strong> Соблюдающий обет [йогин] (<em>vratī</em>) должен разместить на востоке, на выступе стены (<em>paṇḍikāyām</em>), Майтрею и Кшитигарбху, а на юге — Ваджрапани и Акашагарбху (<em>khagarbham</em>).</li>
            </ul>
            <!-- Шлока 32 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>32.</strong> Затем на западе следует поместить Локешвару и Манджугхошу, а на севере — Сарваниваранавишкамбхина и Самантабхадру.</li>
            </ul>
            <!-- Шлока 33 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>33.</strong> У восточных ворот — Ямантаку, у южных — Апараджиту, у западных — Хаягриву, у северных — Амритакундали.</li>
            </ul>
            <!-- Шлока 34 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>34.</strong> Ачалу, Таккираджу, Ниладанду и Махабалу следует созерцать в установленной последовательности, начиная с юго-восточного угла мандалы.</li>
            </ul>
            <!-- Шлока 35 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>35.</strong> Внизу следует визуализировать великого гневного Сумбхараджу (<em>Sumbharāja Mahākrodha</em>), а наверху — Ушнишачакравартина (<em>Uṣṇīṣacakravartin</em>).<a href="#citation-66" id="ref-66" class="citation-mark"><sup>66</sup></a></li>
            </ul>
            <div class="not-prose flex justify-center my-4">
                <figure class="rounded-lg shadow-md max-w-[600px] text-center">
                    <img src="\images\dharma\tantra\guhyasamaja\Mandala_Guhyasamadja_shema_color_new_edit.svg"
                        alt="Схема расположения божеств в мандале Гухьясамаджа"
                        class="rounded-lg w-full h-auto mx-auto object-contain transition-all duration-300 ease-in-out">
                    <figcaption class="mt-2 mb-4 px-4 italic text-gray-800 text-sm">
                        Схема расположения божеств в мандале Гухьясамаджа
                    </figcaption>
                </figure>
            </div>
        </div>
        <h3 class="font-bold text-md text-center mt-6 mb-3">(9. Растворение божеств в теле)</h3>
        <div>
            <!-- Шлока 36 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>36.</strong> Представляя всё таким образом и пребывая в состоянии полной устремлённости (<em>adhimuktyā</em>), пусть практикующий в соответствии с предписанием (<em>yathāvidhi</em>) созерцает всех божеств мандалы (<em>māṇḍaleyān</em>), а затем посредством практики сампута-йоги (<em>sampuṭayoga</em>) введёт их в собственное тело (<em>svakāya</em>).</li>
            </ul>
        </div>
        <h3 class="font-bold text-md text-center mt-6 mb-3">(10. Вхождение в Таковость)</h3>
        <div>
            <!-- Шлока 37 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>37.</strong> Созерцая таким образом Будд, пребывающих в чакрах собственного тела (<em>kāyacakragatān buddhān</em>), каждого на его надлежащем месте (<em>yathāyatham</em>), пусть практикующий посредством круга высшей истины (<em>pāramārthikacakra</em>) введёт их в Таковость (<em>tathatā</em>).<a href="#citation-67" id="ref-67" class="citation-mark"><sup>67</sup></a></li>
            </ul>
            <!-- Шлока 38 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>38.</strong> Умертвив (то есть полностью растворив) сонм Татхагат (<em>mārayet tathāgatavyūham</em>), практикующий непременно обретёт высшие сиддхи (<em>sutarāṃ siddhim āpnuyāt</em>).</li>
                <li>Смысл этого подробно и ясно изложен в «Ваджрамале».</li>
            </ul>
        </div>
        <h3 class="font-bold text-md text-center mt-6 mb-3">(11. Растворения скандх в Ясном Свете)</h3>
        <div>
            <!-- Шлока 39 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>39.</strong> Скандхе формы соответствует Зерцалоподобная мудрость (<em>rūpaskandhagatādarśa</em>);</li>
                <li>ей соответствуют элемент земли (<em>bhūdhātu</em>), орган зрения (<em>nayanendriya</em>) и видимая форма (<em>rūpa</em>).</li>
                <li>Пятым соответствием является непревзойдённая пара гневных божеств (<em>krodhadvayam anuttamam</em>).</li>
            </ul>
            <!-- Шлока 40 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>40.</strong> Скандхе ощущения соответствует Мудрость равностности (<em>vedanāskandhasamatā</em>);</li>
                <li>ей соответствуют элемент воды (<em>apdhātu</em>), орган слуха (<em>śravaṇendriya</em>) и звук (<em>śabda</em>).</li>
                <li>Пятым соответствием является непревзойдённая пара гневных божеств.</li>
            </ul>
            <!-- Шлока 41 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>41.</strong> Скандхе распознавания соответствует Различающая мудрость (<em>pratyavekṣaṇā</em>);</li>
                <li>ей соответствуют элемент огня (<em>hutabhug</em>), орган обоняния (<em>nāsikendriya</em>) и запах (<em>gandha</em>).</li>
                <li>Пятым соответствием становится сочетание с парой гневных божеств.</li>
            </ul>
            <!-- Шлока 42 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>42.</strong> Скандхе формирующих факторов соответствует Всеисполняющая мудрость (<em>kṛtyānuṣṭhāna</em>);</li>
                <li>ей соответствуют элемент ветра (<em>māruta</em>), орган вкуса (<em>rasanendriya</em>) и вкус (<em>rasa</em>).</li>
                <li>Пятым соответствием становится сочетание с парой гневных божеств.</li>
            </ul>
            <!-- Шлока 43 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>43.</strong> Гневные [божества], соединённые вверху и внизу, а также изначальное проявление [их] природы,</li>
                <li>вступают в скандху сознания (<em>vijñānaskandham āyāti</em>); само же сознание становится Ясным Светом (<em>vijñānaṃ ca prabhāsvaram</em>).</li>
            </ul>
        </div>
        <h3 class="font-bold text-md text-center mt-6 mb-3">(12. Утверждение в Дхармакае)</h3>
        <div>
            <!-- Шлока 44 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>44.</strong> [Это состояние] провозглашается Нирваной, Всеобъемлющей шуньятой (<em>sarvaśūnyaṃ</em>) и Дхармакаей (<em>dharmakāyaś ca gadyate</em>).</li>
                <li>Ради его окончательного утверждения (<em>dṛḍhīkaraṇahetutvān</em>) следует произнести эту мантру:</li>
            <li class="font-bold text-center italic my-4 text-2xl"><span class="text-red-700">
                oṃ śūnyatājñānavajrasvabhāvātmako 'ham</span>
                </li>
                <li>(ОМ ШУНЬЯТА-ДЖНЯНА-ВАДЖРА-СВАБХАВА-АТМАКО ХАМ)</li>
                <li>(произносится: ОМ ШУУНЬЯТАА-ДЖНЯААНА-ВАДЖРА-СВАБХААВААТМАКОО ХАМ)</li>
                <li>(«ОМ! Я ИМЕЮ ПРИРОДУ ВАДЖРА МУДРОСТИ ШУНЬЯТЫ»)</li>
            </ul>
            <!-- Шлока 45 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>45.</strong> Эта мандала высшего смысла (<em>paramārthamaṇḍalaṃ hy etan</em>) лишена видимых образов и признаков (<em>nirābhāsam alakṣaṇam</em>).</li>
                <li>Она именуется Абсолютной Истиной (<em>paramārthasatya</em>) и является обителью всех Татхагат (<em>sarvatathāgatālayaḥ</em>).<a href="#citation-68" id="ref-68" class="citation-mark"><sup>68</sup></a></li>
            </ul>
        </div>
        <h3 class="font-bold text-md text-center mt-6 mb-3">(13. Выход из Ясного Света)</h3>
        <div>
            <!-- Шлока 46 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>46.</strong> Теперь разъясняется выход из Ясного Света того, кто вошёл в него.</li>
                <li>Посредством применения Тела Мантры (<em>mantramūrti</em>) внимание вновь направляется на божество как объект созерцания.</li>
            </ul>
            <!-- Шлока 47 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>47.</strong> В самом центре сферы пространства (<em>ākāśadhātu</em>) следует визуализировать диск солнца (<em>sūryamaṇḍala</em>).</li>
                <li>Над ним мантрин вновь должен визуализировать лунный диск (<em>candrabimba</em>).</li>
            </ul>
            <!-- Шлока 48 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>48.</strong> Там следует визуализировать красный восьмилепестковый лотос (<em>aṣṭadalaṃ padmaṃ raktavarṇam</em>).</li>
                <li>Над этим лотосом вновь следует визуализировать великую Трёхслоговую мантру [<span class="font-bold italic text-red-700">OṀ ĀḤ HŪṀ</span>] (<em>mahāmantraṃ tryakṣaram</em>).</li>
            </ul>
            <!-- Шлока 49 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>49.</strong> Следует созерцать лунный диск как бодхичитту, полностью наполненную вошедшими в него мантрой, лотосом и солнечным диском.</li>
            </ul>
            <!-- Шлока 50 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>50.</strong> Именно в этой бодхичитте следует созерцать всё неподвижное и подвижное.<a href="#citation-69" id="ref-69" class="citation-mark"><sup>69</sup></a></li>
                <li>Для окончательного утверждения этого созерцания следует произнести следующую мантру:</li>
            </ul>
            <!-- Мантра шлоки 50 -->
            <ul class="list-none mb-6 pl-2 space-y-3 ml-2">
                <li class="font-bold italic text-red-700 text-center text-2xl">oṃ dharmadhātusvabhāvātmako 'ham</li>
                <li>(ОМ ДХАРМАДХАТУ СВАБХАВА АТМАКО ХАМ)</li>
                <li>(произносится: ОМ ДХАРМАДХААТУ-СВАБХААВААТМАКОО ХАМ)</li>
                <li>(«Я ПО СВОЕЙ СУТИ ЕСМЬ ОБЛАДАЮЩИЙ ПРИРОДОЙ ДХАРМАДХАТУ»)</li>
            </ul>
        </div>
        <h3 class="font-bold text-md text-center mt-6 mb-3">(14. Практика Последующей Йоги (ануйоги))</h3>
        <div>
            <!-- Шлока 51 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>51.</strong> Утвердившись таким образом в этой йоге (<em>yogam evaṃ samālambya</em>), следует приступить к последующей йоге (<em>anuyogaṃ samācaret</em>).</li>
                <li>Затем йогин вновь должен созерцать Трёхслоговую мантру в центре лунного диска.</li>
            </ul>
            <!-- Шлока 52 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>52.</strong> Затем, созерцая Изначального Владыку (<em>Ādinātha</em>), возникшего из Трёхслоговой мантры,</li>
                <li>ослепительно белого, подобного цветку жасмина кунды и полной луне, следует приступить к высшей йоге (<em>atiyoga</em>).</li>
            </ul>
        </div>
        <h3 class="font-bold text-md text-center mt-6 mb-3">(15. Установление божеств в теле,<br>практика Высшей Йоги (атийоги))</h3>
        <div>
            <!-- Шлока 53 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>53.</strong> Посредством вхождения Акшобхьи (<em>akṣobhyānupraveśena</em>)</li>
                <li>следует созерцать Ваджрасаттву (<em>vajrasattva</em>),</li>
                <li>трёхликого и лучезарного шестирукого (<em>trimukhaṃ ṣaḍbhujojjvalam</em>),</li>
                <li>сияющего глубоким сапфирово-синим цветом индранилы (<em>indranīlaprabhaṃ dīptam</em>).</li>
            </ul>
            <!-- Шлока 54 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>54.</strong> Следует визуализировать в правых руках ваджр, чакру и лотос (<em>vajraṃ cakraṃ tathā padmam</em>),</li>
                <li>а в левых — колокольчик, драгоценность и меч (<em>ghaṇṭāṃ ratnaṃ tathā khaṅgam</em>).<a href="#citation-70" id="ref-70" class="citation-mark"><sup>70</sup></a></li>
            </ul>
            <div class="not-prose flex justify-center my-4">
                <figure class="rounded-lg shadow-md max-w-[800px] text-center">
                    <img src="\images\dharma\tantra\guhyasamaja\Guhyasamaja_Akshobhyavajra_pindikrita.webp"
                        alt="Guhyasamaja_Akshobhyavajra"
                        class="rounded-lg w-full h-auto mx-auto object-contain transition-all duration-300 ease-in-out">
                    <figcaption class="mt-2 mb-4 px-4 italic text-gray-800 text-sm">
                        Гухьясамаджа Акшобхьяваджра
                    </figcaption>
                </figure>
            </div>
            <!-- Шлока 55 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>55.</strong> Затем, зная распределение скандх</li>
                <li>и остальных соответствий (<em>skandhādīnāṃ vibhāgavit</em>),</li>
                <li>следует совершить ньясу (<em>nyāsa</em>) — </li>
                <li>ритуальное установление семенных слогов —</li>
                <li>от Вайрочаны до Сумбхи (<em>vairocanādisumbhāntaṃ</em>),</li>
                <li>посредством их правильного установления (<em>bījanyāsena tattvataḥ</em>).</li>
            </ul>
            <!-- Шлока 56 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>56.</strong> Знающий мантру (<em>mantravit</em>) должен установить</li>
                <li>на макушку (<em>mūrdhni</em>) семенной слог Вайрочаны (<em>vairocanīyabījaṃ</em>) —</li>
                <li>белый слог <span class="font-bold italic text-red-700">OṀ</span> (<em>oṃkāraṃ śuklavarṇakam</em>),</li>
                <li>имеющий природу скандхи формы (<em>rūpaskandhasvabhāvena</em>).</li>
            </ul>
            <!-- Шлока 57 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>57.</strong> Созерцая во рту (<em>mukhe dhyātvā</em>) красный слог <span class="font-bold italic text-red-700">ĀḤ</span> (<em>āḥkāraṃ raktavarṇaṃ</em>) Амитабхи,</li>
                <li>имеющий природу скандхи распознавания (<em>saṃjñāskandhasvabhāvakam</em>),</li>
                <li>йогин обретает владычество речи (<em>vāgaiśvaryam</em>).</li>
            </ul>
            <!-- Шлока 58 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>58.</strong> Мантрин должен установить в сердце (<em>hṛdaye</em>) слог <span class="font-bold italic text-red-700">HŪṀ</span> (<em>hūṃkāraṃ</em>) Акшобхьи,</li>
                <li>обладающий сиянием чистого лазурита (<em>rājāvartaśukaprabham</em>)</li>
                <li>и имеющий природу скандхи сознания (<em>vijñānaskandharūpataḥ</em>).</li>
            </ul>
            <!-- Шлока 59 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>59.</strong> Следует установить в пупке (<em>nābhau</em>) слог <span class="font-bold italic text-red-700">SVĀ</span> (<em>svākāraṃ</em>)</li>
                <li>Владыки Драгоценностей (<em>ratnanāthasya</em>),</li>
                <li>имеющий природу скандхи ощущения (<em>vedanāskandharūpataḥ</em>),</li>
                <li>жёлтый по цвету (<em>pītavarṇam</em>) и служащий причиной очищения скандхи ощущения (<em>vedanāśuddhihetukam</em>).</li>
            </ul>
            <!-- Шлока 60 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>60.</strong> Мантрин должен установить на обеих стопах (<em>pādadvaye</em>)</li>
                <li>слог <span class="font-bold italic text-red-700">HĀḤ</span> (<em>hāḥkāraṃ</em>) Владыки Деяния (<em>karmanāthasya</em>),</li>
                <li>зелёный по цвету (<em>haritābham</em>) и имеющий природу</li>
                <li>скандхи формирующих факторов (<em>saṃskāraskandhabhāvataḥ</em>).</li>
            </ul>
            <!-- Шлока 61 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>61.</strong> Посредством [мантр] Мохарати и других [богинь] (<em>moharatyādikair</em>)</li>
                <li>мантрин должен последовательно установить</li>
                <li>землю и остальные элементы (<em>pṛthivyādīn</em>)</li>
                <li>вместе с присущими им свойствами —</li>
                <li>твёрдостью, текучестью, жаром и движением (<em>kharatvaṃ dravatā auṣṇyam īraṇatvaṃ ca</em>).</li>
            </ul>
            <!-- Шлока 62 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>62.</strong> Установив в глазах (<em>cakṣuṣi</em>) слог <span class="font-bold italic text-red-700">THLĪṀ</span> (<em>thlīṃkāraṃ</em>),</li>
                <li>следует созерцать Кшитигарбху (<em>kṣitigarbhaṃ</em>).</li>
                <li>Установив в ушах (<em>karṇayoḥ</em>) слог <span class="font-bold italic text-red-700">OṀ</span> (<em>oṃkāraṃ</em>),</li>
                <li>следует созерцать Ваджрапани (<em>vajrapāṇiṃ</em>).</li>
            </ul>
            <!-- Шлока 63 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>63.</strong> Установив в носу (<em>ghrāṇe</em>) слог <span class="font-bold italic text-red-700">OṀ</span> (<em>oṃkāraṃ</em>),</li>
                <li>следует созерцать Акашагарбху (<em>khagarbhaṃ</em>).</li>
                <li>Установив на языке (<em>rasane</em>) слог <span class="font-bold italic text-red-700">OṀ</span> (<em>oṃkāraṃ</em>),</li>
                <li>следует созерцать Локешвару (<em>lokeśaṃ</em>).</li>
            </ul>
            <!-- Шлока 64 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>64.</strong> Созерцая в уме (<em>manasi dhyātvā</em>) слог <span class="font-bold italic text-red-700">HŪṀ</span> (<em>hūṃkāraṃ</em>),</li>
                <li>следует явить Манджугхошу (<em>mañjughoṣaṃ</em>).</li>
                <li>Созерцая во всём теле (<em>sarvakāye ca dhyātvā</em>) слог <span class="font-bold italic text-red-700">OṀ</span> (<em>oṃkāraṃ</em>),</li>
                <li>следует помнить о Сарваниваранавишкамбхине (<em>viṣkambhiṇaṃ</em>).</li>
            </ul>
            <!-- Шлока 65 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>65.</strong> Посредством слога <span class="font-bold italic text-red-700">MAIṀ</span> (<em>maiṃkāreṇa</em>)</li>
                <li>следует созерцать Майтрею (<em>maitreyaṃ</em>),</li>
                <li>пребывающего на макушке (<em>śiraḥsaṃstham</em>).</li>
                <li>Созерцая Самантабхадру (<em>bhadraṃ</em>),</li>
                <li>следует установить слог <span class="font-bold italic text-red-700">SAṀ</span></li>
                <li>во всех сочленениях тела (<em>sarvasaṃdhiṣu saṃnyaset</em>).</li>
            </ul>
            <!-- Шлока 66 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>66.</strong> Ямантаку (<em>yamāntakaḥ</em>) следует созерцать в правой руке (<em>savyabhuje</em>),</li>
                <li>Апараджиту (<em>aparājitaḥ</em>) — в левой (<em>apasavye</em>).</li>
                <li>Хаягриву (<em>hayagrīvaḥ</em>) следует визуализировать во рту (<em>mukhe</em>),</li>
                <li>Амритакундали (<em>amṛtakuṇḍaliḥ</em>) — на ваджре (<em>vajre</em>).</li>
            </ul>
            <!-- Шлока 67 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>67.</strong> Ачалу (<em>acalaṃ</em>) следует разместить на правой стороне (<em>dakṣiṇe bhāge</em>),</li>
                <li>Таккираджу (<em>ṭakkirājakaṃ</em>) — на левой (<em>vāme</em>).</li>
                <li>На правом колене (<em>jānau ca dakṣiṇe</em>) следует созерцать Ниладанду (<em>nīladaṇḍaṃ</em>), пылающего великим сиянием (<em>mahojjvalam</em>).</li>
            </ul>
            <!-- Шлока 68 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>68.</strong> На левом колене (<em>vāmajānau</em>) следует созерцать Махабалу (<em>mahābalaṃ</em>),</li>
                <li>на макушке (<em>mūrdhni</em>) — Ушнишачакравартина (<em>uṣṇīṣacakriṇam</em>).</li>
                <li>Сумбхараджу (<em>sumbharājaṃ</em>) следует визуализировать размещённым на подошвах обеих стоп (<em>pādāntadvayavinyastam</em>).</li>
            </ul>
        </div>
        <h3 class="font-bold text-md text-center mt-6 mb-3">(16. Начало практики Махайоги)</h3>
        <div>
            <!-- Шлока 69 -->
            <div class="not-prose flex justify-center my-4">
                <figure class="rounded-lg shadow-md max-w-[800px] text-center">
                    <img src="\images\dharma\tantra\guhyasamaja\Nyasa.webp"
                        alt="Nyasa"
                        class="rounded-lg w-full h-auto mx-auto object-contain transition-all duration-300 ease-in-out">
                    <figcaption class="mt-2 mb-4 px-4 italic text-gray-800 text-sm">
                        Пример наложения (ньяса) семенных слогов и божеств на тело йогина из другой садханы
                    </figcaption>
                </figure>
            </div>
            <ul class="list-none mb-10 pl-2 space-y-2 ml-2">
                <li><strong>69.</strong> Совершив наложение (<em>nyāsaṃ kṛtvā</em>) скандх и прочих элементов</li>
                <li>по правилу (<em>skandhādīnāṃ yathāvidhi</em>), мантрин,</li>
                <li>полностью воплотивший мандалу тела (<em>kāyamaṇḍalam āpannaḥ</em>),<a href="#citation-71" id="ref-71" class="citation-mark"><sup>71</sup></a></li>
                <li>должен приступить к Великой Йоге (<em>mahāyogaṃ samārabhet</em>).</li>
            </ul>
        </div>
        <h3 class="font-bold text-md text-center mt-6 mb-3">(17. Благословление Тела)</h3>
        <div>
            <!-- Шлока 70 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>70.</strong> В самом центре макушки (<em>mūrdhni madhyagataṃ</em>)</li>
                <li>следует представить полный лунный диск (<em>sampūrṇaṃ candramaṇḍalam</em>),</li>
                <li>а на нём — ослепительно белый слог <span class="font-bold italic text-red-700">OṀ</span> (<em>tatroṃkāraṃ śuklābhaṃ</em>),</li>
                <li>излучающий во все стороны пять лучей света (<em>prasphuratpañcaraśmikam</em>).</li>
            </ul>
            <!-- Шлока 71 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>71.</strong> Затем, посредством йоги владычества (<em>ādhipatyaprayoga</em>) проявив богиню,</li>
                <li>следует созерцать Лочану во множестве её проявлений,</li>
                <li>полностью заполняющих всё пространство.<a href="#citation-72" id="ref-72" class="citation-mark"><sup>72</sup></a></li>
            </ul>
            <!-- Шлока 72 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>72.</strong> Затем, представив Ваджр Тела (<em>kāyavajra</em>)</li>
                <li>устойчиво пребывающий и заполняющий всё пространство (<em>vyomāpūrya vyavasthitam</em>),</li>
                <li>следует созерцать в его центре Владыку (<em>tanmadhye 'dhipatiṃ cintet</em>),</li>
                <li>пребывающего перед [йогином] (<em>ātmanaś ca puraḥsthitam</em>).<a href="#citation-73" id="ref-73" class="citation-mark"><sup>73</sup></a></li>
            </ul>
            <!-- Шлока 73 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>73.</strong> Созерцая Его наделённым тридцатью двумя великими признаками (<em>dvātriṃśallakṣaṇadharaṃ</em>)</li>
                <li>и украшенным восемьюдесятью второстепенными признаками (<em>vyañjanāśītibhūṣitam</em>),</li>
                <li>затем пусть мантрин обратится с прошением (<em>prārthayet tu tato mantrī</em>),</li>
                <li>произнеся следующие две строфы (<em>gāthādvayam udāharan</em>):<a href="#citation-74" id="ref-74" class="citation-mark"><sup>74</sup></a></li>
            </ul>
            <!-- Шлока 74 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>74.</strong> «О славный Держатель Тела Будды (<em>buddhakāyadharaḥ śrīmān</em>),</li>
                <li>постигший нераздельную природу трёх ваджров (<em>trivajrābhedyabhāvitaḥ</em>),</li>
                <li>ниспошли мне сегодня благословение (<em>adhiṣṭhānapadaṃ me 'dya karotu</em>),</li>
                <li>чтобы стал я Обладателем Ваджра Тела (<em>kāyavajriṇaḥ</em>)!»</li>
            </ul>
            <!-- Шлока 75 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>75.</strong> «О Будды, пребывающие в десяти направлениях (<em>daśadikṣu sthitā buddhāḥ</em>),</li>
                <li>постигшие нераздельную природу трёх ваджров (<em>trivajrābhedyabhāvitāḥ</em>),</li>
                <li>пусть сегодня вы ниспошлёте мне благословение (<em>adhiṣṭhānapadaṃ me 'dya kurvantu</em>),</li>
                <li>чтобы стал я Обладателем Ваджра Тела (<em>kāyavajriṇaḥ</em>)!»</li>
            </ul>
            <!-- Шлока 76 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>76.</strong> Следует представить Вайрочану в союзе с Лочаной (<em>locanāsahasaṃyuktaṃ</em>).</li>
                <li>Введя Его [в себя], следует пребывать в благословении (<em>adhitiṣṭheta</em>),</li>
                <li>будучи полностью наполненным пятью скандхами.</li>
            </ul>
            <!-- Шлока 77 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>77.</strong> «Пусть и моё тело станет таким же, как Тело всех Будд,</li>
                <li>полностью наполненное пятью скандхами (<em>pañcaskandhaprapūritam</em>),</li>
                <li>обладая самой природой Тела Будды (<em>buddhakāyasvabhāvena</em>)».<a href="#citation-75" id="ref-75" class="citation-mark"><sup>75</sup></a></li>
            </ul>
            <!-- Мантра шлоки 77 -->
            <ul class="list-none mb-6 pl-2 space-y-3 ml-2">
                <li class="font-bold text-center italic my-4 text-2xl"><span class="text-red-700">oṃsarvatathāgatakāyavajrasvabhāvātmako 'ham</span>
                </li>
                <li>(ОМ САРВА ТАТХАГАТА КАЯВАДЖРА СВАБХАВА АТМАКО ХАМ)</li>
                <li>(произносится: ОМ САРВАТАТХААГАТА-КААЯВАДЖРА-СВАБХААВААТМАКОО ХАМ)</li>
                <li>(«ОМ! Я ОБЛАДАЮ ПРИРОДОЙ ВАДЖРА ТЕЛА ВСЕХ ТАТХАГАТ»)</li>
            </ul>
        </div>
        <h3 class="font-bold text-md text-center mt-6 mb-3">(18. Благословление Речи)</h3>
        <div>
            <!-- Шлока 78 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>78.</strong> Следует созерцать в центре лотоса языка красный слог <span class="font-bold italic text-red-700">ĀḤ</span>.</li>
                <li>Затем следует проявить богиню по имени Пандара</li>
                <li>вместе с её окружением, полностью заполняющими всё пространство.</li>
            </ul>
            <!-- Шлока 79 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>79.</strong> Представив затем Ваджр Речи (<em>vāgvajraṃ ca tathā</em>),</li>
                <li>заполняющим всё пространство и твёрдо пребывающим,</li>
                <li>мантрин должен взмолиться, произнося две эти строфы [из коренной тантры]:</li>
            </ul>
            <!-- Шлока 80 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>80.</strong> «О славный Путь Речи Дхармы (<em>dharmo vai vākpathaḥ śrīmān</em>),</li>
                <li>постигший нераздельную природу трёх ваджров,</li>
                <li>пусть сегодня [Владыка] ниспошлёт мне благословение,</li>
                <li>чтобы стал я Обладателем Ваджра Речи (<em>vāgvajriṇaḥ</em>)!»<a href="#citation-76" id="ref-76" class="citation-mark"><sup>76</sup></a></li>
            </ul>
            <!-- Шлока 81 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>81.</strong> «О Будды, пребывающие в десяти направлениях,</li>
                <li>постигшие нераздельную природу трёх ваджров,</li>
                <li>пусть сегодня вы ниспошлёте мне благословение,</li>
                <li>чтобы стал я Обладателем Ваджра Речи!»</li>
            </ul>
            <!-- Шлока 82 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>82.</strong> Созерцая богиню Пандару,</li>
                <li>соединённую со своим Владыкой и вошедшую в язык,</li>
                <li>пусть [йогин] приступит к благословению Речи (<em>vāgadhiṣṭhānam ārabhet</em>), [произнося]:</li>
            </ul>
            <!-- Шлока 83 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>83.</strong> «Пусть и моя речь станет такой же,</li>
                <li>как совершенное словесное выражение</li>
                <li>Ваджра-Дхармы (<em>vajradharmasya vācā niruktisampadā</em>),</li>
                <li>подобной речи Держателя Дхармы (<em>dharmadharopamā</em>)».</li>
            </ul>
            <!-- Мантра шлоки 83 -->
            <ul class="list-none mb-6 pl-2 space-y-3 ml-2">
                <li class="font-bold text-center italic my-4 text-2xl"><span class="text-red-700">oṃsarvatathāgatavāgvajrasvabhāvātmako 'ham</span>
                </li>
                <li>(ОМ САРВА ТАТХАГАТА ВАГВАДЖРА СВАБХАВА АТМАКО ХАМ)</li>
                <li>(произносится: ОМ САРВАТАТХААГАТА-ВААГВАДЖРА-СВАБХААВААТМАКОО ХАМ)</li>
                <li>(«ОМ! Я ИМЕЮ ПРИРОДУ ВАДЖРА РЕЧИ ВСЕХ ТАТХАГАТ»)</li>
            </ul>
        </div>
        <h3 class="font-bold text-md text-center mt-6 mb-3">(19. Благословление Ума)</h3>
        <div>
            <!-- Шлока 84 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>84.</strong> В сердце (<em>hṛdaye</em>) мантрин должен представить</li>
                <li>сияющий лунный диск (<em>śaśibimbaṃ samujjvalam</em>),</li>
                <li>а на нём — слог <span class="font-bold italic text-red-700">HŪṀ</span> (<em>tatra hūṃkāraṃ</em>),</li>
                <li>цветом подобный лазуриту (<em>rājāvartanibhaṃ</em>),</li>
                <li>излучающий пять лучей света (<em>pañcaraśmikam</em>).</li>
            </ul>
            <!-- Шлока 85 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>85.</strong> Затем следует проявить богиню Мамаки</li>
                <li>вместе со свитой (<em>tato niścārayed devīṃ māmakīṃ sagaṇāṃ punaḥ</em>).</li>
                <li>Представив затем таким же образом Ваджр Ума (<em>cittavajraṃ tathā dhyātvā</em>),</li>
                <li>следует обратиться с мольбой (<em>prārthayeta</em>), как и прежде (<em>yathāpuraḥ</em>):</li>
            </ul>
            <!-- Шлока 86 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>86.</strong> «О славный Носитель Ваджра Ума (<em>cittavajradharaḥ śrīmān</em>),</li>
                <li>постигший нераздельную природу трёх ваджров (<em>trivajrābhedyabhāvitaḥ</em>),</li>
                <li>ниспошли мне сегодня благословение (<em>adhiṣṭhānapadaṃ me 'dya karotu</em>),</li>
                <li>чтобы стал я Обладателем Ваджра Ума (<em>cittavajriṇaḥ</em>)!»</li>
            </ul>
            <!-- Шлока 87 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>87.</strong> «О Будды, пребывающие в десяти направлениях (<em>daśadikṣu sthitā buddhāḥ</em>),</li>
                <li>постигшие нераздельную природу трёх ваджров (<em>trivajrābhedyabhāvitāḥ</em>),</li>
                <li>ниспошлите мне сегодня благословение (<em>adhiṣṭhānapadaṃ me 'dya kurvantu</em>),</li>
                <li>чтобы стал я Обладателем Ваджра Ума (<em>cittavajriṇaḥ</em>)!»</li>
            </ul>
            <!-- Шлока 88 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>88.</strong> Полностью введя в сердце</li>
                <li>весь сонм Мамаки (<em>māmakīvyūham akhilaṃ hṛdaye saṃpraveśya</em>),</li>
                <li>соединённый с Ваджром Ума (<em>cittavajrasamāyuktaṃ</em>),</li>
                <li>пусть [йогин] приступит к благословению Ума (<em>cittādhiṣṭhānam ārabhet</em>), [произнося]:</li>
            </ul>
            <!-- Шлока 89 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>89.</strong> «Каков ум мудрого Владыки Тайн</li>
                <li>Самантабхадры (<em>yaccittaṃ samantabhadrasya guhyakendrasya dhīmataḥ</em>),</li>
                <li>пусть и мой ум станет точно таким же (<em>mamāpi tādṛśaṃ cittaṃ bhaved</em>),</li>
                <li>уподобившись [Уму самого] Держателя Ваджры (<em>vajradharopamam</em>)!»</li>
            </ul>
            <!-- Мантра после шлоки 89 -->
            <ul class="list-none mb-6 pl-2 space-y-3 ml-2">
                <li class="font-bold text-center italic my-4 text-2xl"><span class="text-red-700">oṃsarvatathāgatacittavajrasvabhāvātmako 'ham</span>
                </li>
                <li>(ОМ САРВА ТАТХАГАТА ЧИТТАВАДЖРА СВАБХАВА АТМАКО ХАМ)</li>
                <li>(произносится: ОМ САРВАТАТХААГАТА-ЧИТТАВАДЖРА-СВАБХААВААТМАКОО ХАМ)</li>
                <li>(«ОМ! Я ИМЕЮ ПРИРОДУ ВАДЖРА УМА ВСЕХ ТАТХАГАТ»)</li>
            </ul>
        </div>
        <h3 class="font-bold text-md text-center mt-6 mb-3">(20. Благословление Тела, Речи и Ума)</h3>
        <div>
            <!-- Шлока 90 -->
