                    <li>(«ОМ! Я ИМЕЮ ПРИРОДУ ВАДЖРА ТЕЛА, РЕЧИ И УМА ВСЕХ ТАТХАГАТ»)</li>
                </ul>
        </div>
        <h3 class="font-bold text-md text-center mt-6 mb-3">(21. Представление Самаясаттвы, Джнянасаттвы и Самадхисаттвы)</h3>
        <div>
            <!-- Шлока 91 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>91.</strong> Таким образом, утвердив себя в центре лунного диска,</li>
                <li>наделённым шестью отличительными признаками (<em>ṣaḍbhiś cihnaiḥ samāyuktam</em>),</li>
                <li>следует созерцать самого себя как Существо Обета (<em>samayasattva</em>).<a href="#citation-78" id="ref-78" class="citation-mark"><sup>78</sup></a></li>
            </ul>
            <!-- Шлока 92 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>92.</strong> Следует визуализировать тонкое Существо Мудрости (<em>jñānasattva</em>),</li>
                <li>пребывающее в центре сердца (<em>hṛnmadhyasaṃsthitam</em>),</li>
                <li>и твёрдо установить там же слог <span class="font-bold italic text-red-700">HŪṀ</span> (<em>hūṃkāra</em>),</li>
                <li>именуемый Существом Самадхи (<em>samādhisattva</em>).</li>
            </ul>
        </div>
        <h3 class="font-bold text-md text-center mt-6 mb-3">(22. Начало Махасадханы)</h3>
        <div>
            <!-- Шлока 93 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>93.</strong> Таким образом, осуществив Великую Йогу (<em>mahāyoga</em>),</li>
                <li>состоящую из трёх существ (<em>trisattvātmakam</em>),</li>
                <li>практикующий (<em>ātmavān</em>) посредством этого метода (<em>anena vidhiyogena</em>)</li>
                <li>должен приступить к Великой Садхане (<em>mahāsādhanam ārabhet</em>).</li>
            </ul>
        </div>
        <h3 class="font-bold text-md text-center mt-6 mb-3">(23. Принятие супруги)</h3>
        <div>
            <!-- Шлока 94 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>94.</strong> Обретя широкоокую деву, украшенную красотой и юностью,</li>
                <li>тёмно-синюю, как лепестки синего лотоса,</li>
                <li>дочь великодушного прачки (<em>rajakasya mahātmanaḥ</em>),</li>
            </ul>
        </div>
        <h3 class="font-bold text-md text-center mt-6 mb-3">(24. Установление божеств в теле супруги)</h3>
        <div>
            <!-- Шлока 95 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>95.</strong> приняв к себе эту превосходно обученную деву, преданную практикующему,</li>
                <li>следует, созерцая слог <span class="font-bold italic text-red-700">OṀ</span> на её макушке,</li>
                <li>наложить слог <span class="font-bold italic text-red-700">ĀḤ</span> на пути её речи.</li>
            </ul>
            <!-- Шлока 96 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>96.</strong> Созерцая слог <span class="font-bold italic text-red-700">HŪṀ</span> в её сердце,</li>
                <li>слог <span class="font-bold italic text-red-700">SVĀ</span> — в пупке,</li>
                <li>а слог <span class="font-bold italic text-red-700">HĀḤ</span> — на обеих стопах (<em>hā dvipādayoḥ</em>),</li>
                <li>[следует созерцать] также Лочану, Мамаки</li>
                <li>и Пандаравасини (<em>locanāṃ māmakīṃ cāpi tathā pāṇḍaravāsinīm</em>).</li>
            </ul>
            <!-- Шлока 97 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>97.</strong> Также мантрин должен наложить Тару на землю</li>
                <li>и прочие [элементы],</li>
                <li>а на ней самой следует визуализировать богинь,</li>
                <li>начиная с Рупаваджры.</li>
            </ul>
            <!-- Шлока 98 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>98.</strong> Следует созерцать их соединёнными с Кшитигарбхой и другими бодхисаттвами;</li>
                <li>на её правой руке — Ваджраветали,</li>
                <li>а на левой руке — Апараджиту.</li>
            </ul>
            <!-- Шлока 99 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>99.</strong> [Пусть йогин созерцает] Бхрикути на её лице,</li>
                <li>Экаджати — в её тайном месте,</li>
                <li>а также Татхагати по имени Вишваваджри, расположенную на её правом предплечье.</li>
            </ul>
            <!-- Шлока 100 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>100.</strong> И пусть он отчётливо визуализирует Вишваратну на левом предплечье этой мудры-супруги,</li>
                <li>а на её правом колене — Татхагати по имени Вишвападма,</li>
            </ul>
            <!-- Шлока 101 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>101.</strong> На её левом [колене] — Вишвакарму,</li>
                <li>на макушке головы — Гаганаваджрини,</li>
                <li>а на подошвах обеих стоп — богиню Дхараниндхару, Владычицу Земли.<a href="#citation-79" id="ref-79" class="citation-mark"><sup>79</sup></a></li>
            </ul>
        </div>
        <h3 class="font-bold text-md text-center mt-6 mb-3">(25. Союз с супругой)</h3>
        <div>
            <!-- Шлока 102 -->
