        <h3 class="font-bold text-md text-center mt-6 mb-3">(26. Визуализация себя как главного божества и совершение деяний Будды)</h3>
        <div>
            <!-- Шлока 107 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>107.</strong> Возникнув из слогов собственной мантры (<em>svamantrākṣaraniṣpannaṃ</em>) и благословив самого себя посредством трёх ваджров (<em>trivajrādhiṣṭhitasvakam</em>),</li>
                <li>породив себя в центре лотоса (<em>padmamadhye tu niṣpādya</em>), [йогин] вновь становится Ваджром Гнева (<em>dveṣavajro bhavet punaḥ</em>);</li>
            </ul>
            <!-- Шлока 108 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>108.</strong> затем, созерцая Владыку, Ваджродержателя семейства Акшобхьи (<em>paśyed akṣobhyavajriṇam</em>),</li>
                <li>порождённого мантрой <strong><em>Ваджрадхрик</em></strong> (<em>vajradhṛṅmantraniṣpannaṃ</em>),</li>
                <li>носящего корону из высоко уложенных и заплетённых волос (<em>jaṭāmukuṭadharaṃ nātham</em>)</li>
                <li>и увенчанного образом Акшобхьи (<em>akṣobhyakṛtaśekharam</em>),</li>
            </ul>
            <!-- Шлока 109 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>109.</strong> сияющего цветом чистого лазурита (<em>rājāvartaśukasaṅkāśaṃ</em>),</li>
                <li>с чёрным, красным и белым ликами (<em>kṛṣṇaraktasitānanam</em>),</li>
                <li>полностью украшенного всеми украшениями (<em>sarvālaṅkārasampūrṇaṃ</em>),</li>
                <li>шестирукого (<em>ṣaḍbhujaṃ tu vibhāvayet</em>),</li>
            </ul>
            <!-- Шлока 110 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>110.</strong> держащего в правых руках ваджр, чакру и лотос (<em>vajraṃ cakraṃ tathā padmaṃ savyahasteṣu dhārayet</em>),</li>
                <li>а в левых — колокольчик, драгоценность, исполняющую желания, и меч (<em>ghaṇṭāṃ cintāmaṇiṃ khaḍgaṃ tasya vāmeṣu bhāvayet</em>),</li>
            </ul>
            <!-- Шлока 111 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>111.</strong> пусть представляет, как Он, выйдя из его собственного сердца (<em>niṣkramya hṛdayād eṣa</em>),</li>
                <li>обозревает все десять сторон света (<em>vyavalokya diśo daśa</em>),</li>
                <li>совершает все чудесные деяния Будды (<em>buddharddhim akhilāṃ kṛtvā</em>)</li>
                <li>и приводит в движение Колесо Дхармы (<em>dharmacakraṃ pravartya ca</em>),</li>
            </ul>
            <!-- Шлока 112 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>112.</strong> полностью очищает всех живых существ (<em>saṃśodhya nikhilān sattvān</em>)</li>
                <li>и утверждает их в состоянии Ваджра Гнева (<em>dveṣavajrapade sthitān</em>),</li>
                <li>а затем возвращается и садится перед Владыкой Ваджра (<em>āgatya vajranāthasya purato 'bhiniṣīdati</em>);</li>
            </ul>
            <!-- Шлока 113 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>113.</strong> вновь введя этот образ в себя (<em>anupraveśya taṃ</em>), мантрин созерцает себя в собственном сердце (<em>hṛdy ātmānaṃ vibhāvayet</em>)</li>
                <li>и, полностью преобразив свой прежний облик (<em>pūrvarūpaṃ parāvṛttya</em>),</li>
                <li>пребывает в состоянии Ваджра Гнева (<em>dveṣavajrapade sthitaḥ</em>),</li>
            </ul>
            <!-- Шлока 114 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>114.</strong> сияющего цветом сапфира индранила (<em>indranīlaprabhaṃ dīptaṃ</em>),</li>
                <li>пребывающего в центре солнечного диска (<em>sūryamaṇḍalamadhyagam</em>),</li>
                <li>Героя, объятого собственной мудрой (<em>svamudrāliṅgitaṃ vīraṃ</em>),</li>
                <li>украшенного всеми украшениями (<em>sarvālaṅkārabhūṣitam</em>),</li>
            </ul>
            <!-- Шлока 115 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>115.</strong> сочетающего гневный, мирный и исполненный великой страсти облики (<em>raudraśāntamahārāgaṃ</em>)</li>
                <li>и украшенного тремя ликами (<em>mukhatrayavirājitam</em>),</li>
                <li>после чего, пребывая в самадхи Ваджра Гнева (<em>dveṣavajrasamādhisthaḥ</em>),</li>
                <li>йогин излучает всю мандалу (<em>protsṛjet sarvamaṇḍalam</em>).<a href="#citation-81" id="ref-81" class="citation-mark"><sup>81</sup></a></li>
            </ul>
        </div>
        <h3 class="font-bold text-md text-center mt-6 mb-3">(27. Визуализация других божеств, их деяния и размещение в мандале)</h3>
        <div>
            <!-- Шлока 116 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>116.</strong> Пусть [йогин] породит Владыку Вайрочану (<em>sṛjed vairocanaṃ vibhum</em>),</li>
                <li>возникшего из мантры <strong><em>Джинаджик</em></strong> (<em>jinajigmantraniṣpannaṃ</em>),</li>
                <li>подобного сиянию осенней луны (<em>śaraccandrāṃśusaṅkāśaṃ</em>)</li>
                <li>и украшенного короной из высоко уложенных и заплетённых волос (<em>jaṭāmukuṭamaṇḍitam</em>),</li>
            </ul>
            <!-- Шлока 117 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>117.</strong> с белым, красным и чёрным ликами (<em>sitaraktakṛṣṇavadanaṃ</em>), шестирукого (<em>ṣaḍbhujaṃ</em>),</li>
                <li>пребывающего в мирном облике (<em>śāntarūpiṇam</em>),</li>
                <li>держащего в правых руках чакру, ваджр и белый лотос (<em>cakravajrasitāmbhojaṃ dakṣiṇeṣu vicintayet</em>),</li>
            </ul>
            <!-- Шлока 118 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>118.</strong> а в левых — колокольчик, драгоценность, исполняющую желания, и меч (<em>ghaṇṭāṃ cintāmaṇiṃ khaḍgaṃ vāmeṣvasya vibhāvayet</em>);</li>
                <li>затем [пусть представляет, как] Он, выйдя точно так же из сердца (<em>hṛdayāt tathaiva nirgatya</em>),</li>
                <li>очищает существ, пребывающих под властью неведения (<em>mohacaryāsthitāḥ prajāḥ</em>),</li>
            </ul>
            <!-- Шлока 119 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>119.</strong> после чего возвращается и вновь восседает на своём месте в круге мандалы (<em>saṃśodhya punar āgatya punaś cakre niṣīdati</em>).<a href="#citation-82" id="ref-82" class="citation-mark"><sup>82</sup></a></li>
                <li>После этого мудрый [йогин] пусть породит Ратнакету (<em>ratnaketuṃ sṛjed budhaḥ</em>),</li>
                <li>возникшего из мантры <strong><em>Ратнадхрик</em></strong> (<em>ratnadhṛgmantraniṣpannaṃ</em>),</li>
            </ul>
            <!-- Шлока 120 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>120.</strong> мирного (<em>saumyam</em>), носящего корону из высоко уложенных и заплетённых волос (<em>jaṭājūṭadharaṃ</em>),</li>
                <li>увенчанного образом Акшобхьи (<em>akṣobhyakṛtaśekharam</em>),</li>
                <li>с жёлтым, чёрным и белым ликами (<em>pītakṛṣṇasitāsyaṃ</em>), шестирукого (<em>ṣaḍbhujaṃ</em>),</li>
            </ul>
            <!-- Шлока 121 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>121.</strong> держащего в правых руках драгоценность, исполняющую желания, ваджр и чакру (<em>tasya cintāmaṇiṃ vajraṃ cakraṃ savyeṣu bhāvayet</em>),</li>
                <li>а в левых — колокольчик, жёлтый лотос и меч (<em>ghaṇṭāṃ ca pītakamalaṃ khaḍgaṃ vāmeṣu bhāvayet</em>),</li>
            </ul>
            <!-- Шлока 122 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>122.</strong> который, выйдя таким же образом из сердца (<em>hṛdayāt tathaiva nirgatya</em>),</li>
                <li>очищает существ, пребывающих во власти эго-гордыни (<em>ahaṅkārapade sthitān</em>),</li>
                <li>после чего восседает в южной части, в центре драгоценности (<em>dakṣiṇe bhāge ratnamadhye niṣīdati</em>).<a href="#citation-83" id="ref-83" class="citation-mark"><sup>83</sup></a></li>
            </ul>
            <!-- Шлока 123 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>123.</strong> Породив Обладателя Ваджра Амитабхи (<em>sṛjed amitavajriṇam</em>),</li>
                <li>возникшего из мантры <strong><em>Аролик</em></strong> (<em>ārolik-mantraniṣpannaṃ</em>),</li>
                <li>сияющего цветом рубина (<em>padmarāgaprabhaṃ</em>), мирного (<em>saumyam</em>)</li>
                <li>и увенчанного [образом] Акшобхьи (<em>akṣobhyakṛtaśekharam</em>),</li>
            </ul>
            <!-- Шлока 124 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>124.</strong> Владыку (<em>nāthaṃ</em>), носящего корону из высоко уложенных и заплетённых в косы волос (<em>jaṭāmukuṭadharaṃ</em>),</li>
                <li>с красным, чёрным и белым ликами (<em>raktakṛṣṇasitānanam</em>),</li>
                <li>исполненного любовного очарования (<em>śṛṅgārarasasaṃyuktaṃ</em>) и шестирукого (<em>ṣaḍbhujam</em>),</li>
            </ul>
            <!-- Шлока 125 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>125.</strong> держащего в левой руке стебель лотоса вместе с колокольчиком (<em>padmanālaṃ gṛhītvā tu vāmena saha ghaṇṭayā</em>)</li>
                <li>и раскрывающего правой рукой лотос, пребывающий на уровне сердца (<em>hṛtpradeśasthitaṃ padmaṃ dakṣiṇena vikāśayet</em>),</li>
            </ul>
            <!-- Шлока 126 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>126.</strong> в двух правых руках держащего ваджр и чакру (<em>savyayoḥ vajracakre tu</em>),</li>
                <li>а в двух левых — драгоценность и меч (<em>vāmayoḥ ratnakhaḍgakau</em>),</li>
                <li>[йогин представляет, как] Он, подобно прежде описанному (<em>pūrvavat</em>),</li>
                <li>очищает существ, охваченных страстью (<em>rāgiṇaḥ śodhya</em>),</li>
                <li>после чего восседает на западе, на лотосе (<em>pṛṣṭhato 'bje niṣīdati</em>).<a href="#citation-84" id="ref-84" class="citation-mark"><sup>84</sup></a></li>
            </ul>
            <!-- Шлока 127 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>127.</strong> Пусть [йогин] породит Обладателя Ваджра Амогхасиддхи (<em>amoghavajriṇam</em>),</li>
                <li>возникшего из мантры <strong><em>Праджнядхрик</em></strong> (<em>prajñādhṛg-mantranirmitam</em>),</li>
                <li>Владыку зелёного цвета (<em>haritābhaṃ nāthaṃ</em>),</li>
                <li>увенчанного короной из высоко уложенных и заплетённых в косы волос (<em>jaṭāmukuṭamaṇḍitam</em>),</li>
            </ul>
            <!-- Шлока 128 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>128.</strong> с зелёным, чёрным и белым ликами (<em>haritakṛṣṇasitāsyaṃ</em>),</li>
                <li>шестирукого (<em>ṣaḍbhujam</em>),</li>
                <li>сияющего лучами света (<em>raśmibhāsuram</em>),</li>
                <li>держащего в правых руках меч, вишваваджр и чакру (<em>khaḍgaṃ ca viśvavajraṃ ca cakraṃ savyeṣu</em>),</li>
            </ul>
            <!-- Шлока 129 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>129.</strong> а в левых руках — колокольчик, зелёный лотос и драгоценность (<em>ghaṇṭāṃ vāmeṣu hasteṣu haritapadmaṃ maṇiṃ tathā</em>),</li>
                <li>после чего, очистив живых существ, пребывающих во власти зависти (<em>īrṣyādoṣastha-sattvānāṃ viṣodhya</em>),</li>
                <li>Он возвращается обратно (<em>punar āgataḥ</em>)</li>
            </ul>
            <!-- Шлока 130 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>130.</strong> и восседает в северном направлении на вишваваджре (<em>uttarasyāṃ diśi tathā viśvavajre niṣīdati</em>).</li>
                <li>Семейства Гнева, Неведения, Страсти, Драгоценности и Самаи (<em>dveṣo mohas tathā rāgaś cintāmaṇiḥ samayas tathā</em>) —</li>
            </ul>
            <!-- Шлока 131 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>131.</strong> воистину, эти пять семейств (<em>kulā hy ete tu vai pañca</em>)</li>
                <li>являются совершенными средствами для достижения как мирских желаний, так и освобождения (<em>kāmamokṣaprasādhakāḥ</em>).<a href="#citation-85" id="ref-85" class="citation-mark"><sup>85</sup></a></li>
                <li>Затем [йогин], породив богиню Лочану (<em>sṛjed devīṃ tu locanām</em>), возникшую из мантры <strong><em>Мохарати</em></strong> (<em>moharatyādibhir jātām</em>),</li>
            </ul>
            <!-- Шлока 132 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>132.</strong> белую (<em>śvetāṃ</em>), исполненную безмятежного покоя (<em>śāntarasopetāṃ</em>),</li>
                <li>отмеченную образом Вайрочаны на макушке (<em>mūrdhni vairocanāṅkitām</em>),</li>
                <li>с белым, красным и чёрным ликами (<em>sitaraktakṛṣṇavadanāṃ</em>), шестирукую (<em>ṣaḍbhujāṃ tu vibhāvayet</em>),</li>
            </ul>
            <!-- Шлока 133 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>133.</strong> держащую в правых руках чакру, ваджр и белый лотос-утпалу (<em>savye cakraṃ ca vajraṃ ca tathaiva sitam utpalam</em>),</li>
                <li>а в левых — колокольчик, драгоценность и меч (<em>vāme ghaṇṭāṃ tathā ratnaṃ khaḍgaṃ cāpi vibhāvayet</em>),</li>
            </ul>
            <!-- Шлока 134 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>134.</strong> [пусть представляет, как] Она, выйдя из сердца (<em>hṛdayāt tu vinirgatya</em>),</li>
                <li>обозревает все десять сторон света (<em>vyavalokya diśo daśa</em>)</li>
                <li>и, движимая великим состраданием (<em>mahākṛpāḥ</em>),</li>
                <li>приносит мир и покой мирозданию, терзаемому злыми духами и болезнями (<em>grahavyādhyāture loke śāntiṃ kṛtvā</em>),</li>
            </ul>
            <!-- Шлока 135 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>135.</strong> после чего возвращается и восседает на лунном диске в [юго-] восточном  углу (<em>āgatya cakramadhye tu pūrvakoṇe niṣīdati</em>).<a href="#citation-86" id="ref-86" class="citation-mark"><sup>86</sup></a></li>
                <li>Затем [йогин] порождает богиню Мамаки (<em>sṛjed devīṃ tu māmakīm</em>), возникшую из мантры <strong><em>Двешарати</em></strong> (<em>mantrād dveṣarater jātām</em>),</li>
            </ul>
            <!-- Шлока 136 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>136.</strong> тёмно-синюю, подобную лепесткам синего лотоса (<em>nīlotpaladalaśyāmāṃ</em>),</li>
                <li>прекрасноликую и пленительную (<em>cāruvaktrāṃ manoramām</em>),</li>
                <li>с чёрным, красным и белым ликами (<em>kṛṣṇaraktasitāsyaṃ</em>),</li>
                <li>увенчанную образом Акшобхьи (<em>akṣobhyakṛtaśekharām</em>),</li>
            </ul>
            <!-- Шлока 137 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>137.</strong> держащую в правых руках ваджр, чакру и сине-красный лотос (<em>savyeṣu vajraṃ cakraṃ ca nīlaraktotpalaṃ tathā</em>),</li>
                <li>а в левых — колокольчик, драгоценность и меч (<em>ghaṇṭāṃ ratnaṃ ca khaḍgaṃ ca vāmahasteṣu dhārayet</em>),</li>
            </ul>
            <!-- Шлока 138 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>138.</strong> [пусть представляет, как] Она, движимая великим состраданием (<em>mahākṛpāḥ</em>),</li>
                <li>дарует защиту существам, терзаемым страхом перед великими препятствиями (<em>mahāvighnabhayārtānāṃ rakṣāṃ kṛtvā</em>),</li>
                <li>после чего, выйдя [из сердца] и вновь возвратившись (<em>niṣkramya punar āgatya</em>),</li>
                <li>восседает в юго-западном направлении (<em>nairṛtyāṃ sā niṣīdati</em>).<a href="#citation-87" id="ref-87" class="citation-mark"><sup>87</sup></a></li>
            </ul>
            <!-- Шлока 139 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>139.</strong> Пусть [йогин] излучит богиню Пандаравасини (<em>sṛjet pāṇḍaravāsinīm</em>),</li>
                <li>рождённую из мантры <strong><em>Рагарати</em></strong> (<em>mantrād rāgarater jātāṃ</em>),</li>
                <li>с красным, чёрным и белым ликами (<em>raktakṛṣṇasitāsyāṃ vai</em>),</li>
                <li>сияющую блеском рубина (<em>padmarāgamaṇiprabhām</em>),</li>
            </ul>
            <!-- Шлока 140 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>140.</strong> увенчанную образом Амитабхи и носящую корону из высоко уложенных и заплетённых волос (<em>sāmitābhajaṭājūṭāṃ</em>),</li>
                <li>шестирукую (<em>ṣaḍbhujāṃ tu vibhāvayet</em>),</li>
                <li>держащую в левой руке вместе с колокольчиком стебель лотоса (<em>gṛhītvotpalanālaṃ tu vāmena saha ghaṇṭayā</em>),</li>
            </ul>
            <!-- Шлока 141 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>141.</strong> раскрывающую пальцами правой руки красный лотос, пребывающий у сердца (<em>utpalaṃ hṛtpradeśasthaṃ raktaṃ savyena bodhayet</em>),</li>
                <li>а в двух других правых руках держащую ваджр и чакру (<em>vajraṃ cakraṃ ca savyābhyāṃ</em>),</li>
                <li>в двух левых — драгоценность и меч (<em>maṇiṃ khaḍgaṃ ca vāmataḥ</em>),</li>
            </ul>
            <!-- Шлока 142 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>142.</strong> после чего, выйдя [из сердца] и даровав покой миру, тяжко терзаемому духами (<em>śāntiṃ kṛtvā mahāture</em>),</li>
                <li>Она возвращается и восседает в центре лотоса в северо-западном углу (<em>āgatya padmamadhye ca vāyukoṇe niṣīdati</em>).<a href="#citation-88" id="ref-88" class="citation-mark"><sup>88</sup></a></li>
            </ul>
            <!-- Шлока 143 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>143.</strong> Пусть [йогин] излучит пленительную богиню Тару (<em>sṛjet tārāṃ manoramām</em>),</li>
                <li>рождённую из мантры <strong><em>Ваджрарати</em></strong> (<em>mantrād vajrarater jātāṃ</em>),</li>
                <li>с зелёным, чёрным и белым ликами (<em>haritakṛṣṇasitāsyāṃ ca</em>),</li>
                <li>сияющую цветом листьев травы дурва (<em>dūrvāpatrasamaprabhām</em>),</li>
            </ul>
            <!-- Шлока 144 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>144.</strong> шестирукую (<em>ṣaḍbhujāṃ tu vibhāvayet</em>), увенчанную образом Амогхасиддхи (<em>amoghena kṛtoṣṇīṣāṃ</em>),</li>
                <li>держащую в правых руках вишваваджр, чакру и тёмно-синий лотос (<em>viśvavajraṃ ca cakraṃ ca savyato 'sitam utpalam</em>),</li>
            </ul>
            <!-- Шлока 145 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>145.</strong> а в левых — колокольчик, драгоценность и меч (<em>vāmeṣu vinyased ghaṇṭāṃ ratnaṃ khaḍgaṃ tathā</em>),</li>
                <li>после чего, подчинив своей просветлённой власти всех живых существ (<em>sarvasattvān vaśīkṛtya</em>),</li>
                <li>практикующий (<em>vratī</em>) вновь созерцает её на престоле из вишваваджра (<em>viśvavajrāsanāḥ punaḥ</em>);</li>
            </ul>
            <!-- Шлока 146 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>146.</strong> выйдя [из сердца] и возвратившись обратно (<em>nirgatā 'sau samāgamya</em>),</li>
                <li>Она занимает своё место в северо-восточном углу, в обители Шивы (<em>śivasthāne niṣīdati</em>),</li>
                <li>после чего йогин переходит ко второму ярусу мандалы (<em>dvitīye tu puṭe yogī</em>)</li>
                <li>и излучает богинь, начиная с Рупаваджры (<em>rūpavajrādikaṃ sṛjet</em>).<a href="#citation-89" id="ref-89" class="citation-mark"><sup>89</sup></a></li>
            </ul>
            <!-- Шлока 147 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>147.</strong> В юго-восточном направлении [в углу огня] (<em>agnikoṇe</em>) пусть [йогин] излучит пленительную богиню Рупаваджру (<em>sṛjed devīṃ rūpavajrāṃ manoramām</em>),</li>
                <li>трёхликую, шестирукую, белого цвета и увенчанную на макушке образом славного Вайрочаны (<em>trimukhāṃ ṣaḍbhujāṃ śvetāṃ śrīvairocanamaulikām</em>),</li>
            </ul>
            <!-- Шлока 148 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>148.</strong> держащую двумя руками зеркало (<em>gṛhītadarpaṇāṃ dvābhyāṃ</em>), а во всём остальном подобную Мохарати (<em>śeṣaṃ moharater iva</em>);</li>
                <li>в юго-западном направлении (<em>nairṛtyāṃ</em>) следует поместить шестирукую богиню Шабдаваджру (<em>śabdavajrāṃ tu ṣaḍbhujām</em>),</li>
            </ul>
            <!-- Шлока 149 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>149.</strong> жёлтого цвета (<em>pītavarṇāṃ</em>), трёхликую (<em>trivaktrāṃ</em>), увенчанную образом Ратнасамбхавы (<em>ratnasambhavamaulikām</em>),</li>
                <li>держащую двумя руками лютню (<em>vīṇāvyagradvihastāṃ</em>), а во всём остальном подобную Мамаки (<em>śeṣaṃ māmakīvad bhavet</em>);</li>
            </ul>
            <!-- Шлока 150 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>150.</strong> в северо-западном направлении [углу ветра] (<em>vāyusthāne</em>) следует поместить шестирукую богиню Гандхаваджру (<em>gandhavajrāṃ tu ṣaḍbhujām</em>),</li>
                <li>красного цвета (<em>raktavarṇāṃ</em>), трёхликую (<em>trivaktrāṃ</em>), носящую причёску Амитабхи (<em>amitābhajaṭādharām</em>),</li>
            </ul>
            <!-- Шлока 151 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>151.</strong> держащую двумя руками раковину (<em>śaṅkhavyagradvihastāṃ</em>), а во всём остальном подобную Пандаравасини (<em>śeṣaiḥ pāṇḍaravāsinīm</em>);</li>
                <li>в северо-восточном направлении (<em>aiśānyāṃ</em>) следует поместить шестирукую богиню Расаваджру (<em>rasavajrāṃ tu ṣaḍbhujām</em>),</li>
            </ul>
            <!-- Шлока 152 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>152.</strong> трёхликую, тёмно-зелёного цвета (<em>trimukhāṃ śyāmavarṇāṃ</em>), увенчанную образом Дундубхисвары (<em>dundubhisvaramaulikām</em>),</li>
                <li>держащую двумя руками сосуд со вкусами (<em>hastastharasabhāṇḍāṃ</em>), а во всём остальном подобную Таре (<em>śeṣais tārāsamākṛtim</em>);</li>
            </ul>
            <!-- Шлока 153 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>153.</strong> затем следует созерцать Спаршаваджру (<em>cintayet sparśavajrāṃ tu</em>), пребывающую в центре диска мандалы (<em>cakramadhye vyavasthitām</em>),</li>
                <li>в тесном объятии с Ваджрасаттвой (<em>vajrasattvaṃ samāliṅgya</em>)</li>
                <li>и подобную своему Владыке лицами и всеми прочими признаками (<em>patitulyāṃ mukhādibhiḥ</em>).<a href="#citation-90" id="ref-90" class="citation-mark"><sup>90</sup></a></li>
            </ul>
            <!-- Шлока 154 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>154.</strong> На третьем ярусе (<em>tṛtīye tu puṭe</em>), на восточной стороне веранды (<em>pūrve paṭṭikāyāṃ</em>),</li>
                <li>соблюдающий обет йогин (<em>vratī</em>) порождает Майтрею и Кшитигарбху (<em>maitreyakṣitigarbhakau</em>),</li>
                <li>возникших из семенных слогов <span class="font-bold italic text-red-700">MAIṀ</span> и <span class="font-bold italic text-red-700">THLĪṀ</span> (<em>maiṃ-thlīṃ bījaviniṣpannau</em>),</li>
            </ul>
            <!-- Шлока 155 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>155.</strong> затем на южной стороне веранды (<em>paṭṭikāyāṃ... dakṣiṇāyāṃ</em>), в установленном порядке (<em>yathākramam</em>),</li>
                <li>мантрин пусть породит (<em>sṛjet</em>) Ваджрапани и Кхагарбху [Акашагарбху] (<em>vajrapāṇikhagarbhakau</em>),</li>
                <li>возникших из слога <span class="font-bold italic text-red-700">OṀ</span> (<em>praṇavena samutpannau</em>),</li>
            </ul>
            <!-- Шлока 156 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>156.</strong> на западной стороне (<em>paścimāyāṃ</em>) — Локешвару и Манджугхошу (<em>lokeśaṃ mañjughoṣakam</em>),</li>
                <li>возникших из слогов <span class="font-bold italic text-red-700">OṀ</span> и <span class="font-bold italic text-red-700">HŪṀ</span> (<em>oṃ-hūṃkāraviniṣpannau</em>),</li>
                <li>а на северной стороне пусть также породит (<em>uttarasyāṃ punaḥ sṛjet</em>)</li>
            </ul>
            <!-- Шлока 157 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>157.</strong> Сарваниваранавишкамбхина вместе с Самантабхадрой, возникших из семенных слогов <span class="font-bold italic text-red-700">OṀ</span> и <span class="font-bold italic text-red-700">SAṀ</span> (<em>oṃ-saṃ-bījaviniṣpannau saviṣkambhisamantakam</em>);</li>
                <li>все они (<em>ete</em>), увенчанны образами своих Владык (<em>svanāthamukuṭāḥ</em>),</li>
                <li>подобны им цветом тела и прочими признаками (<em>varṇādyais tatsamāḥ punaḥ</em>),</li>
            </ul>
            <!-- Шлока 158 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>158.</strong> а также количеством рук и атрибутами (<em>bhujaiḥ praharaṇaiś cāpi</em>),</li>
                <li>соответствующими каждому из своих Владык (<em>svasvādhipatibhiḥ samāḥ</em>);</li>
                <li>лишь один Майтрея (<em>maitreyaḥ kevalaṃ</em>) держит в правой руке (<em>savye</em>) цветок нагапушпа (<em>nāgapuṣpaṃ bibharti ca</em>),</li>
            </ul>
            <!-- Шлока 159 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>159.</strong> после чего, полностью очистив аятаны (<em>saṃśodhyāyatanāny ete</em>) живых существ (<em>sattvānām</em>)</li>
                <li>и даровав им божественное зрение и другие [сверхобычные способности] (<em>divyanetrādidāyakāḥ</em>),</li>
                <li>и возвратившись (<em>punar āgatya</em>), вновь восседают каждый на своём престоле (<em>niṣīdanty āsaneṣu vai</em>).<a href="#citation-91" id="ref-91" class="citation-mark"><sup>91</sup></a></li>
            </ul>
            <!-- Шлока 160 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>160.</strong> Пусть мантрин породит Ямантаку (<em>yamāntakaṃ sṛjet mantrī</em>),</li>
                <li>возникшего из мантры <strong><em>Ямантакрит</em></strong> (<em>yamāntakṛnmantrabhavaṃ</em>),</li>
                <li>с чёрным, красным и белым ликами (<em>kṛṣṇaraktasitānanam</em>),</li>
                <li>увенчанного [образом Вайрочаны] и окружённого густым вихрем искр пламени (<em>sphuliṅgagahanākulam</em>),</li>
            </ul>
            <!-- Шлока 161 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>161.</strong> держащего в правых руках посох, чакру и ваджр (<em>daṇḍaṃ cakraṃ tathā vajraṃ savyahasteṣu dhārayan</em>),</li>
                <li>у сердца — аркан и угрожающий жест (<em>hṛddeśe tarjanīpāśaṃ</em>),</li>
                <li>а в остальных левых руках — колокольчик и топор (<em>ghaṇṭāparaśuṃ ca vāmataḥ</em>),</li>
            </ul>
            <!-- Шлока 162 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>162.</strong> повергающего в ужас грозных препятствующих, включая Индру и его свиту (<em>vighnān santrāsayan ghorān indrādīn sagaṇān api</em>),</li>
                <li>и стоящего [в позе пратьялидха], попирая лотос и солнечный диск (<em>padmasūryaṃ samākramya</em>),</li>
                <li>в восточном направлении (<em>pūrvasyāṃ diśi tiṣṭhati</em>).<a href="#citation-92" id="ref-92" class="citation-mark"><sup>92</sup></a></li>
            </ul>
            <div class="not-prose flex justify-center my-4">
                <figure class="rounded-lg shadow-md max-w-[600px] text-center">
                    <img src="\images\dharma\tantra\guhyasamaja\Yamantaka.webp"
                        alt="Ямантака"
                        class="rounded-lg w-full h-auto mx-auto object-contain transition-all duration-300 ease-in-out">
                    <figcaption class="mt-2 mb-4 px-4 italic text-gray-800 text-sm">
                        Ямантака
                    </figcaption>
                </figure>
            </div>
            <!-- Шлока 163 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>163.</strong> Пусть мантрин породит Апараджиту (<em>aparājitaṃ sṛjet mantrī</em>),</li>
                <li>возникшего из мантры <strong></em>Праджнянтакрит</em></strong> (<em>prajñāntakṛnmantrabhavaṃ</em>),</li>
                <li>увенчанного [образом] Ратнасамбхавы (<em>ratnasambhavamaulikam</em>),</li>
                <li>сияющего белым светом и украшенного драгоценностями (<em>śvetābhamaṇibhūṣaṇam</em>),</li>
            </ul>
            <!-- Шлока 164 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>164.</strong> с белым, чёрным и красным ликами (<em>sitakṛṣṇaraktavadanaṃ</em>), с огромным чревом (<em>bṛhatkukṣiṃ</em>),</li>
                <li>трёхглазого (<em>trilocanam</em>), с устрашающе оскаленными клыками (<em>daṃṣṭrākarālavikaṭaṃ</em>)</li>
                <li>и окружённого густым вихрем искр пламени (<em>sphuliṅgagahanākulam</em>),</li>
            </ul>
            <!-- Шлока 165 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>165.</strong> держащего в правых руках ваджр, посох и меч (<em>vajraṃ daṇḍaṃ tathā khaḍgaṃ savyahasteṣu dhārayan</em>),</li>
                <li>у сердца — аркан и угрожающий жест (<em>hṛddeśe tarjanīpāśaṃ</em>),</li>
                <li>а в остальных левых руках — колокольчик и топор (<em>ghaṇṭāṃ paraśuṃ ca vāmataḥ</em>),</li>
            </ul>
            <!-- Шлока 166 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>166.</strong> повергающего в ужас грозных препятствующих (<em>vighnān santrāsayan ghorān</em>),</li>
                <li>стоящего в позе пратьялидха (<em>pratyālīḍhapadena tu</em>)</li>
                <li>и попирающего лотос и солнечный диск (<em>padmasūryaṃ samākramya</em>),</li>
                <li>в южном направлении (<em>yāmyāṃ diśi sa tiṣṭhati</em>).<a href="#citation-93" id="ref-93" class="citation-mark"><sup>93</sup></a></li>
            </ul>
            <div class="not-prose flex justify-center my-4">
                <figure class="rounded-lg shadow-md max-w-[200px] text-center">
                    <img src="\images\dharma\tantra\guhyasamaja\Aparajit.webp"
                        alt="Апараджит"
                        class="rounded-lg w-full h-auto mx-auto object-contain transition-all duration-300 ease-in-out">
                    <figcaption class="mt-2 mb-4 px-4 italic text-gray-800 text-sm">
                        Апараджит
                    </figcaption>
                </figure>
            </div>
            <!-- Шлока 167 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>167.</strong> Пусть соблюдающий обет [йогин] (<em>vratī</em>) излучит Хаягриву (<em>hayagrīvaṃ</em>),</li>
                <li>порождённого мантрой <strong><em>Падмантакрит</em></strong> (<em>padmāntakṛnmantrabhavaṃ</em>),</li>
                <li>сияющего цветом рубина (<em>padmarāganibhaṃ</em>), трёхглазого (<em>tryakṣaṃ</em>),</li>
                <li>с красным, чёрным и белым ликами (<em>raktakṛṣṇasitānanam</em>),</li>
            </ul>
            <!-- Шлока 168 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>168.</strong> с разинутой в яростном крике пастью (<em>karālāsyaṃ</em>), с огромным чревом (<em>bṛhatkukṣim</em>),</li>
                <li>увенчанного [образом] Амитабхи (<em>amitābhakirīṭinam</em>), Героя (<em>vīraṃ</em>),</li>
                <li>пребывающего в позе пратьялидха (<em>pratyālīḍhapadaṃ</em>)</li>
                <li>и объятого густым вихрем огненных искр (<em>sphuliṅgagahanākulam</em>),</li>
            </ul>
            <!-- Шлока 169 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>169.</strong> держащего в правых руках лотос, меч и пест (<em>padmaṃ khaḍgaṃ ca musalaṃ savyahasteṣu bhāvayet</em>),</li>
                <li>а в левых — колокольчик, горделиво воздетый топор и аркан (<em>ghaṇṭāṃ sagarvaparaśuṃ pāśaṃ savyetareṣu ca</em>),</li>
            </ul>
            <!-- Шлока 170 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>170.</strong> взошедшего на лотос и солнечный диск (<em>padmasūryaṃ samāruhya</em>),</li>
                <li>обозревшего все десять сторон света (<em>vyavalokya diśo daśa</em>),</li>
                <li>повергшего в ужас грозных препятствующих (<em>vighnasaṃtrāsanaṃ kṛtvā</em>)</li>
                <li>и стоящего в западном направлении, в обители Варуны (<em>vāruṇyāṃ diśi tiṣṭhati</em>).<a href="#citation-94" id="ref-94" class="citation-mark"><sup>94</sup></a></li>
            </ul>
            <div class="not-prose flex justify-center my-4">
                <figure class="rounded-lg shadow-md max-w-[600px] text-center">
                    <img src="\images\dharma\tantra\guhyasamaja\Hayagriva.webp"
