            <!-- Шлока 171 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>171.</strong> Пусть мантрин породит Амритакундали (<em>amṛtakuṇḍaliṃ sṛjed</em>),</li>
                <li>возникшего из мантры <strong><em>Вигхнантакрит</em></strong> (<em>vighnāntakṛnmantrabhavaṃ</em>),</li>
                <li>увенчанного [образом] Дундубхисвары (<em>dundubhisvaramaulikam</em>),</li>
                <li>цвета тёмно-синих лепестков лотоса утпала (<em>nīlotpaladalaśyāmaṃ</em>),</li>
            </ul>
            <!-- Шлока 172 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>172.</strong> с синим, красным и белым ликами (<em>nīlaraktasitāsyaṃ</em>),</li>
                <li>с устрашающе разинутой пастью (<em>karālamukhavibhramam</em>),</li>
                <li>с огромным чревом (<em>bṛhatkukṣiṃ</em>), трёхглазого (<em>trinayanaṃ</em>),</li>
                <li>озарённого красным пламенем (<em>raktajvālāvibhūṣitam</em>),</li>
            </ul>
            <!-- Шлока 173 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>173.</strong> держащего в правых руках вишваваджр, чакру и пест (<em>viśvavajraṃ tathā cakraṃ musalaṃ cāpi savyataḥ</em>),</li>
                <li>у сердца центральной левой рукой — аркан с жестом угрозы (<em>dhārayaṃs tarjanīpāśaṃ</em>),</li>
                <li>а в остальных левых руках — колокольчик и топор (<em>ghaṇṭāṃ paraśuṃ ca vāmataḥ</em>),</li>
            </ul>
            <!-- Шлока 174 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>174.</strong> наводящего ужас на грозных препятствующих (<em>vighnasaṃtrāsanaṃ kṛtvā</em>),</li>
                <li>стоящего в позе пратьялидха, попирающего лотос и солнечный диск (<em>pratyālīḍhapadena tu padmasūryaṃ samāruhya</em>)</li>
                <li>и пребывающего в северном направлении, в обители Куберы (<em>kauberyāṃ diśi tiṣṭhati</em>).<a href="#citation-95" id="ref-95" class="citation-mark"><sup>95</sup></a></li>
            </ul>
