            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>197.</strong> взошедшего на лотос и солнечный диск (<em>padmasūryaṃ samāruhya</em>)</li>
                <li>и пребывающего ниже поверхности земли (<em>bhuvo 'dhastāt sa tiṣṭhati</em>).<a href="#citation-98" id="ref-98" class="citation-mark"><sup>98</sup></a></li>
            </ul>
            <div class="not-prose flex justify-center my-4">
                <figure class="rounded-lg shadow-md max-w-[600px] text-center">
                    <img src="\images\dharma\tantra\guhyasamaja\Sumbharaja.webp"
                        alt="Сумбхараджа"
                        class="rounded-lg w-full h-auto mx-auto object-contain transition-all duration-300 ease-in-out">
                    <figcaption class="mt-2 mb-4 px-4 italic text-gray-800 text-sm">
                        Сумбхараджа
                    </figcaption>
                </figure>
            </div>
        </div>
        <h3 class="font-bold text-md text-center mt-6 mb-3">(28. Практика тонкой йоги — визуализация ваджра и капли)</h3>
        <div>
            <div class="not-prose flex justify-center my-4">
                <figure class="rounded-lg shadow-md max-w-[800px] text-center">
                    <img src="\images\dharma\tantra\guhyasamaja\Guhyasamaja_mandala_pindikrita.webp"
                        alt="Мандала 32-х божеств Гухьясамаджи"
                        class="rounded-lg w-full h-auto mx-auto object-contain transition-all duration-300 ease-in-out">
                    <figcaption class="mt-2 mb-4 px-4 italic text-gray-800 text-sm">
                        Мандала 32-х божеств Гухьясамаджи
                    </figcaption>
                </figure>
            </div>
            <!-- Шлока 198 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>198.</strong> Полностью растворив всю мандалу (<em>utsṛjya maṇḍalaṃ sarvaṃ</em>),</li>
                <li>состоящую из тридцати двух божеств (<em>dvātriṃśaddevatāmayam</em>),</li>
                <li>и пребывая в центре круга (<em>cakramadhyasthito bhūtvā</em>),</li>
                <li>следует затем приступить к тонкой йоге (<em>sūkṣmayogam athārabhet</em>).</li>
            </ul>
            <!-- Шлока 199 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>199.</strong> На кончике носа (<em>nāsāgre</em>) следует созерцать горчичное зерно (<em>sarṣapaṃ</em>),</li>
                <li>а в этом горчичном зерне — всё движущееся и неподвижное (<em>sacarācaram</em>).</li>
                <li>Следует созерцать прекрасное, тайное место мудрости (<em>jñānapadaṃ ramyaṃ rahasyaṃ</em>),</li>
                <li>мысленно построенное мантрой (<em>mantrakalpitam</em>).</li>
            </ul>
            <!-- Шлока 200 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>200.</strong> Пятицветную великую драгоценность (<em>pañcavarṇaṃ mahāratnaṃ</em>),</li>
                <li>размером с горчичное зерно (<em>sarṣapasthūlamātrakam</em>),</li>
                <li>следует постоянно и усердно созерцать посредством йоги</li>
                <li>на кончике носа (<em>nāsikāgre prayatnena bhāvayed yogataḥ sadā</em>).</li>
            </ul>
            <!-- Шлока 201 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>201.</strong> Когда драгоценность станет устойчивой (<em>sthiraṃ</em>), следует распространять её (<em>sphārayed</em>);</li>
                <li>если же она неустойчива (<em>asthiraṃ</em>), распространять её не следует.</li>
                <li>Затем следует распространять её в виде превосходных облаков (<em>pravara-meghaiḥ</em>),</li>
                <li>сияющих светом, подобным пламени Будд (<em>buddhajvālāsamaprabhaiḥ</em>).</li>
            </ul>
            <!-- Шлока 202 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>202.</strong> Вкушающему подаяние (<em>bhikṣāśinā</em>) не следует начитывать мантру (<em>na japtavyam</em>),</li>
                <li>и не следует привязываться к подаянию (<em>na ca bhaikṣārato bhavet</em>).</li>
                <li>Следует начитывать мантру, не нарушая её составных частей (<em>abhinnāṅgam</em>),</li>
                <li>[что] приносит наслаждение всеми желанными благами (<em>sarvakāmopabhogakṛt</em>).</li>
            </ul>
            <!-- Шлока 203 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>203.</strong> Произнеся [мантру], следует проявить ваджр (<em>uccārya saṃsphared vajram</em>);</li>
                <li>по завершении следует совершить растворение (<em>samāptaṃ saṃhāram ādiśet</em>).</li>
                <li>Это, согласно высшему смыслу (<em>paramārthataḥ</em>),</li>
                <li>и есть то, что все Будды называют начитыванием (<em>japoktam</em>).<a href="#citation-99" id="ref-99" class="citation-mark"><sup>99</sup></a></li>
            </ul>
            <!-- Шлока 204 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>204.</strong> Совершив начитывание Тонкой йоги (<em>sūkṣmayogajapaṃ cāpi</em>) двумя способами (<em>dvidhā kṛtvā</em>), по своему усмотрению (<em>yathāruci</em>),</li>
                <li>мантрин должен затем вновь ввести самого себя в Таковость (<em>ātmānaṃ ca punar mantrī tathatāyāṃ praveśayet</em>).</li>
            </ul>
        </div>
        <h3 class="font-bold text-md text-center mt-6 mb-3">(29. Песни Четырёх Богинь)</h3>
        <div>
            <!-- Шлока 205 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>205.</strong> Затем четыре богини, пребывающие в мандале (<em>maṇḍalasthāś caturdevyo</em>),</li>
                <li>не видя более своего Владыку (<em>na paśyantyas tataḥ patim</em>),</li>
                <li>пробуждают Его к Великому Блаженству (<em>bodhayanti mahāsukham</em>)</li>
                <li>следующими четырьмя строфами (<em>gāthācatuṣṭayenetthaṃ</em>):</li>
            </ul>
            <!-- Шлока 206 — Песнь Лочаны -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>206.</strong> [Песнь Лочаны]</li>
                <li>«О Ваджрасаттва, Владыка мира (<em>tvaṃ vajrasattva bhuvaneśvara</em>),</li>
                <li>Владыка сферы живых существ (<em>sattvadhāto</em>)!</li>
                <li>Защити меня, о чарующий любовью (<em>trāyāhi māṃ ratimanojña</em>),</li>
                <li>великими желанными благами (<em>mahārthakāmaiḥ</em>)!</li>
                <li>Возжелай меня, о Родитель (<em>kāmāhi māṃ janaka</em>),</li>
                <li>Высший Друг всех живых существ (<em>sattvamahāgrabandho</em>)!</li>
                <li>Если на то есть Твоя воля, пусть продолжается моя жизнь,</li>
                <li>о Господин (<em>yadīcchase jīvatu mahya nātha</em>)!»</li>
            </ul>
            <!-- Шлока 207 — Песнь Мамаки -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>207.</strong> [Песнь Мамаки]</li>
                <li>«О Ваджрное Тело (<em>vajrakāya</em>), высшая чакра,</li>
                <li>любимый множеством существ (<em>bahusattvapriyāgracakra</em>),</li>
                <li>взирающий на благо Будд, высшую цель пробуждения</li>
                <li>и высшее благо (<em>buddhārthabodhiparamārthahitānudarśī</em>)!</li>
                <li>Возжелай меня страстью (<em>rāgeṇa</em>),</li>
                <li>согласно обету страсти (<em>rāgasamayām</em>)!</li>
                <li>Если на то есть Твоя воля, пусть продолжается моя жизнь,</li>
                <li>о Господин (<em>yadīcchase jīvatu mahya nātha</em>)!»</li>
            </ul>
            <!-- Шлока 208 — Песнь Пандаравасини -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>208.</strong> [Песнь Пандаравасини]</li>
                <li>«О Ваджрная Речь (<em>vajravāca</em>),</li>
                <li>сострадательный ко благу всех существ (<em>sakalasya hitānukampī</em>),</li>
                <li>всегда устремлённый к совершению деяний</li>
                <li>ради блага мира (<em>lokārthakāryakaraṇe sadā sampravṛttaḥ</em>)!</li>
                <li>Возжелай меня, о Самантабхадра (Всеблагой),</li>
                <li>пребывающий в практике йогического союза (<em>suratacarya</em>)!</li>
                <li>Если на то есть Твоя воля, пусть продолжается моя жизнь,</li>
                <li>о Господин (<em>yadīcchase jīvatu mahya nātha</em>)!»</li>
            </ul>
            <!-- Шлока 209 — Песнь Тары -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>209.</strong> [Песнь Тары]</li>
                <li>«О Ваджракама [Ваджрное Желание] (<em>tvaṃ vajrakāma</em>),</li>
                <li>высший среди обетов (<em>samayāgra</em>),</li>
                <li>имеющий своей целью великое благо (<em>mahāhitārtha</em>),</li>
                <li>украшение рода Совершенно Пробуждённых (<em>saṃbuddhavaṃśatilakaḥ</em>),</li>
                <li>равно сострадательный ко всем (<em>samatānukampī</em>)!</li>
                <li>Возжелай меня, сокровищницу достоинств (<em>kāmāhi māṃ guṇanidhiṃ</em>),</li>
                <li>ставшую вместилищем множества драгоценностей (<em>bahuratnabhūtam</em>)!</li>
                <li>Если на то есть Твоя воля, пусть продолжается моя жизнь,</li>
                <li>о Господин (<em>yadīcchase jīvatu mahya nātha</em>)!»<a href="#citation-100" id="ref-100" class="citation-mark"><sup>100</sup></a></li>
            </ul>
        </div>
        <h3 class="font-bold text-md text-center mt-6 mb-3">(30. Прославление Татхагат)</h3>
        <div>
            <!-- Шлока 210 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>210.</strong> Когда Владыка таким образом побуждён восхвалением его подлинных достоинств (<em>evam utthāpito nāthaḥ sadbhūtaguṇakīrtanaiḥ</em>),</li>
                <li>Татхагаты, [пребывая] в своей собственной природе, начиная с Акшобхьи (<em>akṣobhyādisvabhāvena</em>),</li>
                <li>прославляют Его следующими царями гимнов (<em>saṃstuvanti tathāgatāḥ</em>):</li>
            </ul>
            <!-- Шлока 211 — Гимн Акшобхье -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>211.</strong> [Гимн Акшобхье]</li>
                <li>«О Акшобхьяваджра (<em>akṣobhyavajra</em>)! О Великое Знание (<em>mahājñāna</em>)!</li>
                <li>О Великий Пробуждённый ваджрной сферы (<em>vajradhātumahābudha</em>)!</li>
                <li>О Высший среди трёх мандал и трёх ваджров (<em>trimaṇḍala trivajrāgra</em>)!</li>
                <li>О Тайная Речь (<em>bhāṣa guhyaṃ</em>), поклонение Тебе (<em>namo'stu te</em>)!»</li>
            </ul>
            <!-- Шлока 212 — Гимн Вайрочане -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>212.</strong> [Гимн Вайрочане]</li>
                <li>«О Вайрочана (<em>vairocana</em>)! О Пречистый (<em>mahāśuddha</em>)!</li>
                <li>О Ваджрный Покой (<em>vajraśānta</em>)! О Великое Наслаждение (<em>mahārate</em>)!</li>
                <li>О Ваджрный [Наставник], открывающий дхармы,</li>
                <li>изначально светоносные по своей природе (<em>prakṛtiprabhāsvarān dharmān</em>),</li>
                <li>поклонение Тебе (<em>deśa vajra namo'stu te</em>)!»</li>
            </ul>
            <!-- Шлока 213 — Гимн Ратнасамбхаве -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>213.</strong> [Гимн Ратнасамбхаве]</li>
                <li>«О Царь Драгоценностей (<em>ratnarāja</em>)! О Глубочайший (<em>sugāmbhīra</em>)!</li>
                <li>О Ваджр Пространства, чистый как небо (<em>khavajrākāśanirmala</em>)!</li>
                <li>Чистый по своей природе и лишённый пятен (<em>svabhāvaśuddha nirlepa</em>)!</li>
                <li>О Тайная Речь (<em>bhāṣa guhyaṃ</em>), поклонение Тебе (<em>namo'stu te</em>)!»</li>
            </ul>
            <!-- Шлока 214 — Гимн Амитабхе -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>214.</strong> [Гимн Амитабхе]</li>
                <li>«О Безмерный Ваджр, Великий Царь (<em>vajrāmitamahārāja</em>)!</li>
                <li>Свободный от умозрительных построений (<em>nirvikalpa</em>)!</li>
                <li>О Держатель Ваджра Пространства (<em>khavajradhṛk</em>)!</li>
                <li>Достигший совершенства страсти (<em>rāgapāramitāprāpta</em>)!</li>
                <li>О Ваджрная Речь (<em>bhāṣa vajra</em>), поклонение Тебе (<em>namo'stu te</em>)!»</li>
            </ul>
            <!-- Шлока 215 — Гимн Амогхасиддхи -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>215.</strong> [Гимн Амогхасиддхи]</li>
                <li>«О Амогхаваджра (<em>amoghavajra</em>)!</li>
                <li>О Совершенно Пробуждённый (<em>saṃbuddha</em>)!</li>
                <li>Полностью исполняющий все надежды (<em>sarvāśāparipūraka</em>)!</li>
                <li>Возникший из чистой собственной природы (<em>śuddhasvabhāvasambhūta</em>)!</li>
                <li>О Ваджрасаттва (<em>vajrasattva</em>), поклонение Тебе (<em>namo'stu te</em>)!»<a href="#citation-101" id="ref-101" class="citation-mark"><sup>101</sup></a></li>
            </ul>
        </div>
        <h3 class="font-bold text-md text-center mt-6 mb-3">(31. Пребывание как Владыка)</h3>
        <div>
            <!-- Шлока 216 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>216.</strong> После восхваления Буддами (<em>nutvātha buddhair</em>), наполнив круг [мандалы] любовью (<em>anurāgya cakraṃ</em>),</li>
                <li>проявив высшую тайну в точном соответствии с её смыслом (<em>prakāśya guhyaṃ paramaṃ yathāyatham</em>)</li>
                <li>и установив этот круг в круге собственного тела (<em>svakāyacakre viniveśya cakraṃ</em>),</li>
                <li>[йогин созерцает, как] Владыка один пребывает в Великом Блаженстве (<em>mahāsukhas tiṣṭhati nātha ekaḥ</em>).</li>
        </ul>
        </div>
        <h3 class="font-bold text-md text-center mt-6 mb-3">(32. Восприятие всего мира как проявления Ваджрасаттвы)</h3>
        <div>
            <!-- Шлока 217 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>217.</strong> Таким образом, йогин, совершающий четыре вида йоги (<em>caturyogakarastu yogī</em>),</li>
                <li>помыслив мир как содержащий в себе слог <span class="font-bold italic text-red-700">HŪṀ</span> (<em>hūṃkāragarbhaṃ pravicintya lokam</em>),</li>
                <li>увидев, что весь мир есть проявление Ваджрасаттвы (<em>dṛṣṭvā jagat tadbhavavajrasattvaṃ</em>),</li>
                <li>выйдя [из самадхи], пусть действует, сохраняя это понимание, как подобает (<em>vyutthāya taddhīrvicared yathāvad</em>).<a href="#citation-102" id="ref-102" class="citation-mark"><sup>102</sup></a></li>
            </ul>
        </div>
        <h3 class="font-bold text-md text-center mt-6 mb-3">(33. Укрепление тела)</h3>
        <div>
            <!-- Шлока 218 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>218.</strong> Когда у мантрина, удерживающего самадхи, иссыхает тело (<em>samādhim ālambayan mantrī śuṣkamūrtir yadā bhavet</em>),</li>
                <li>пусть он размышляет об этой йоге, услаждающей тело, речь и ум (<em>vicintayed imaṃ yogaṃ kāyavākcittaprīṇanam</em>):</li>
            </ul>
            <!-- Шлока 219 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>219.</strong> Охватив пространство размером в пядь (<em>vitastimātram ākramya</em>), следует представить мандалу на макушке (<em>mūrdhni maṇḍalakalpanā</em>),</li>
                <li>созерцая находящийся там слог <span class="font-bold italic text-red-700">OṀ</span> (<em>oṃkāraṃ tatragaṃ dhyātvā</em>)</li>
                <li>и нисхождение пяти нектаров (<em>pañcāmṛtanipātanam</em>).</li>
            </ul>
            <!-- Шлока 220 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>220.</strong> Посредством этого ваджрного метода йоги (<em>anena vajrayogena</em>) он мгновенно становится сияющим (<em>tejasvī bhavati kṣaṇāt</em>)</li>
                <li>и обретает блаженное, устойчивое состояние тела, речи и ума (<em>kāyavākcittasausthityaṃ labhate</em>);</li>
                <li>в этом нет сомнения (<em>nātra saṃśayaḥ</em>).<a href="#citation-102" id="ref-102" class="citation-mark"><sup>102</sup></a></li>
            </ul>
        </div>
        <h3 class="font-bold text-md text-center mt-6 mb-3">(34. Подношение пищи)</h3>
        <div>
            <!-- Шлока 221 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>221.</strong> Так, посредством постоянной практики (<em>evam abhyāsato</em>), мантрин пусть соответственно очищает и познаёт её (<em>śodhayed bodhayet yathā</em>);</li>
                <li>очистив также сердце и горло (<em>hṛtkaṇṭhaṃ caiva saṃśodhya</em>),</li>
                <li>пусть услаждает Татхагат (<em>prīṇayec ca tathāgatān</em>).</li>
            </ul>

            <!-- Шлока 222 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>222.</strong> Очистив [её] слогом <span class="font-bold italic text-red-700">HŪṀ</span> (<em>hūṃkāreṇa ca saṃśodhya</em>) и познав слогом <span class="font-bold italic text-red-700">ĀḤ</span> (<em>āḥkāreṇa tu bodhayet</em>),</li>
                <li>пусть воспламенит [её], охваченную слогом <span class="font-bold italic text-red-700">OṀ</span> (<em>jvālayet praṇavākrāntam</em>).</li>
                <li>Таково очищение пищи (<em>iyam āhāraśodhanā</em>).</li>
            </ul>

            <!-- Шлока 223 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>223.</strong> Прежде всего следует созерцать в горле раковину (<em>kaṇṭhe śaṅkhaṃ vicintyādau</em>),</li>
                <li>а в ней — восьмилепестковый лотос, возникший из слога <span class="font-bold italic text-red-700">HRĪḤ</span> (<em>tasmin hrīṃkārasambhavaṃ padmam aṣṭadalaṃ cinted</em>);</li>
                <li>над его сердцевиной — слог <span class="font-bold italic text-red-700">HŪṀ</span> (<em>hūṃkāraṃ karṇikopari</em>).</li>
            </ul>

            <!-- Шлока 224 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>224.</strong> Следует созерцать великий ваджр, рождённый из слога <span class="font-bold italic text-red-700">HŪṀ</span> (<em>hūṃkārajaṃ mahāvajraṃ</em>), пятиконечный (<em>pañcaśūcaṃ vibhāvayet</em>),</li>
                <li>и на конце его центральной спицы — слог <span class="font-bold italic text-red-700">OṀ</span> (<em>madhyaśūcāgre sañcinted</em>),</li>
                <li>очищающий горло (<em>oṃkāraṃ kaṇṭhaśodhanam</em>).</li>
            </ul>

            <!-- Шлока 225 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>225.</strong> Созерцая в сердце звук грома (<em>meghanādaṃ hṛdi dhyātvā</em>),</li>
                <li>затем пусть он распространит трёхпламенный огонь (<em>triśikhāgniṃ tataḥ spharet</em>).</li>
                <li>Там пусть он приносит пищу как жертвенное подношение (<em>tatrāhāraṃ ca juhuyād</em>);</li>
                <li>воистину, это и есть внутреннее огненное подношение (<em>homam ādhyātmikaṃ tvidam</em>).</li>
            </ul>

            <!-- Шлока 226 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>226.</strong> Пусть посредством ветра воспламенит огонь (<em>vāyavyaṃ dīpayed agniṃ</em>);</li>
                <li>затем пусть варит [водное] (<em>vāruṇaṃ pacate tu saḥ</em>)</li>
                <li>в месте мандалы Великого Индры (<em>māhendramaṇḍalasthānaṃ</em>),</li>
                <li>где движется жертвенное приношение (<em>yatra sañcarate haviḥ</em>).</li>
            </ul>

            <!-- Шлока 227 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>227.</strong> Какую бы пищу и питьё он ни принимал (<em>annaṃ pānaṃ ca yat kiñcit</em>),</li>
                <li>всё это, соотнесённое с водным [началом] (<em>tat sarvaṃ vāruṇena tu</em>),</li>
                <li>пусть вводит как пищу (<em>aśanaṃ</em>) через лотос рта (<em>mukhapadmena</em>)</li>
                <li>в лотос сердца (<em>hṛtpadmaṃ sampraveśayet</em>).</li>
            </ul>

            <!-- Шлока 228 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>228.</strong> Затем, достигнув лотоса пупка посредством йоги соединения (<em>saṃpuṭīkaraṇayogataḥ</em>),</li>
                <li>выйдя из тайного лотоса (<em>gūḍhapadmād vinirgatya</em>),</li>
                <li>пусть представит [это] как завершающееся пеплом (<em>bhasmāntaṃ ca vinirdiśet</em>).<a href="#citation-103" id="ref-103" class="citation-mark"><sup>103</sup></a></li>
            </ul>
        </div>
        <h3 class="font-bold text-md text-center mt-6 mb-3">(35. Благо от этой практики)</h3>
        <div>
            <!-- Шлока 229 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>229.</strong> Для него нет ни старости, ни болезни, ни смерти, ни яда и тому подобного;</li>
                <li>нет и преждевременной смерти — это полное уничтожение всех бедствий (<em>sarvopadravanāśanam</em>).</li>
            </ul>
        </div>
        <h3 class="font-bold text-md text-center mt-6 mb-3">(36. Колофон)</h3>
        <div>
            <!-- Шлока 230 -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>230.</strong> Взбив сокровенный океан Гухьясамаджи (<em>gūḍhaṃ samājāmbunidhiṃ mathitvā</em>)</li>
                <li>мутовкой — Славной Ваджрной Гирляндой (<em>śrīvajramālāvarmanthanena</em>),</li>
                <li>пусть, обретя благодаря этому нектар, составляющий часть садханы (<em>yat sādhanāṅgāmṛtam āpi tena</em>),</li>
                <li>весь мир достигнет бессмертия (<em>lokaḥ samasto 'maratām upaitu</em>).</li>
            </ul>
            <!-- Индийский колофон -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>Индийский колофон</strong></li>
                <li>Здесь завершается «Пиндикрита-садхана» (<em>Piṇḍīkṛtasādhana</em>).</li>
                <li>Сочинение досточтимого ачарьи Шри Нагарджуны (<em>kṛtir ācāryaśrīnāgārjunapādānām</em>).</li>
            </ul>
            <!-- Тибетский канонический колофон -->
            <ul class="list-none mb-6 pl-2 space-y-2 ml-2">
                <li><strong>Тибетский канонический колофон</strong></li>
                <li>Индийский настоятель ачарья Шраддхакараварма (<em>shrad+dhA ka ra wa rma</em>) и великий переводчик, почтенный Ринчен Зангпо (<em>rin chen bzang po</em>) перевели [этот текст], проверили его и окончательно установили.</li>
                <li>Впоследствии, в присутствии индийского настоятеля, гуру, великого и почитаемого Ваджрадхары Реванты (<em>re ben+ta</em>), монах Чаг Лоцава Чойджэпал (<em>chag lo tsA ba dge slong chos rje dpal</em>) превосходно исправил и окончательно утвердил его в соответствии с рукописью из Магадхи.</li>
            </ul>
        </div>
    </div>
    <!-- Разделитель с Дхармачакрой -->
    <div class="relative my-12">
        <div class="absolute inset-0 flex items-center">
            <div class="w-full border-t border-sky-400"></div>
        </div>
        <div class="relative flex justify-center">
            <span class="bg-sky-50 px-4 text-2xl text-sky-800">☸</span>
        </div>
