    <h2 class="text-center text-sky-900 font-bold text-xl my-4">Примечания</h2>
    <!-- Блок примечаний -->
    <hr class="my-8 border-t-4 border-gray-500">
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p class="my-2" id="citation-1"><sup>1</sup> <strong>Единое проявление (<em>eka-mūrti</em>):</strong> указывает на единство Дхармакаи, свободное от различий и множественности. Для всех Будд она не разделяется на отдельные проявления и потому называется «единым проявлением». <a href="#ref-1" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-2"><sup>2</sup> <strong>Свобода от умопостроений (<em>nirvikalpa</em>):</strong> отсутствие всякого размножествления умопостроений, разделяющего переживание на воспринимающего и воспринимаемое. Здесь речь идёт о свободе от двойственного способа восприятия, не подразумевающем отсутствие познания. <a href="#ref-2" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-3"><sup>3</sup> <strong>Несравненное и равное блаженство (<em>sukham asamasama</em>):</strong> в Ануттара-тантре высшее блаженство понимается как неотделимое от полного освобождения ума от омрачений. Оно несравненно (<em>asama</em>) с мирскими удовольствиями и равно (<em>sama</em>) блаженству всех Будд, не зависит от условий и не иссякает. <a href="#ref-3" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-4"><sup>4</sup> <strong>Выход за пределы трёх миров (<em>trailokyācāra-mukta</em>):</strong> означает свободу от обусловленного круговорота трёх миров — мира желаний, мира форм и мира без форм. <a href="#ref-4" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-5"><sup>5</sup> <strong>Равенство пространству (<em>gagana-samagata</em>):</strong> подобно тому как пространство вмещает все объекты, но само не загрязняется, Дхармакая подобно пространству не имеет препятствий и не ограничивается каким-либо местом. <a href="#ref-5" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-6"><sup>6</sup> <strong>Собственная природа всех явлений (<em>sarvabhāva-svabhāva</em>):</strong> выражение указывает на одинаковый способ существования всех явлений — отсутствие собственного независимого бытия. Поэтому Дхармакая не является отдельной сущностью наряду с явлениями, а постигается как их подлинный способ существования. <a href="#ref-6" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-7"><sup>7</sup> <strong>Чистота (<em>śuddha</em>):</strong> изначальная чистота от двух видов завес – клеш (эмоциональная нестабильность) и неведения (искажений познания). Подобно золоту, скрытому в грязи, природа ума всегда незапятнана. <a href="#ref-7" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-8"><sup>8</sup> <strong>Умиротворённость (<em>śānta</em>):</strong> полное затихание мыслей, беспокойств и кармических ветров; состояние абсолютного покоя нирваны. <a href="#ref-8" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-9"><sup>9</sup> <strong>Свобода от всего постороннего (<em>vivikta</em>):</strong> дословно «обособленный», «уединённый». В тантрическом смысле – отделённость от любых загрязнений, двойственности, иллюзий и сансарических наслоений; свободное пребывание без примеси омрачений. <a href="#ref-9" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-10"><sup>10</sup> <strong>Пронизанность высшим благим покоем (<em>paramaśivamaya</em>):</strong> слово <em>śiva</em> здесь используется в прямом значении – «благо», «благоприятный покой», «высшее благо» (не путать с именем индуистского божества). Дхармакая соткана из высшего блага и умиротворения, исключающего любое страдание. <a href="#ref-10" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-11"><sup>11</sup> <strong>Постижимость лишь йогинами (<em>yoginām eva gamyam</em>):</strong> обычные учёные могут понять шуньяту лишь интеллектуально, но живая Дхармакая – Ясный Свет – доступна лишь прямому восприятию. <a href="#ref-11" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-12"><sup>12</sup> <strong>Труднопостижимость (<em>durbodha</em>):</strong> невозможно понять умом, привыкшим опираться на слова, книги и двойственное восприятие. Для обычного интеллекта Дхармакая непостижима. <a href="#ref-12" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-13"><sup>13</sup> <strong>Сложность для рассудочного анализа (<em>durvicāra</em>):</strong> формальная логика и умопостроения бессильны в постижении Дхармакаи. Пытаться анализировать Ясный Свет логикой – всё равно что измерять бездну пространства линейкой. <a href="#ref-13" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-14"><sup>14</sup> <strong>Величайшее благо себе и другим (<em>sva-para-hita-tama</em>)</strong>. Обретая Дхармакаю, Будда полностью исполняет собственное благо (освобождение) и одновременно, спонтанно разворачивает Рупакаи (формы Будды) для блага всех существ. <a href="#ref-14" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-15"><sup>15</sup> <strong>Всепроникновенность (<em>vyāpin</em>):</strong> подобно пространству, Дхармакая не ограничивается каким-либо местом или временем. Поэтому говорится, что она «всепроникает», хотя речь не идёт о пространственном распространении некоторой сущности. <a href="#ref-15" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-16"><sup>16</sup> <strong>Пребывание вне образов (<em>nirnimitta</em>):</strong> <em>nimitta</em> – «знак», «образ», «характеристика» (например, длинный, короткий, синий). Дхармакая свободна от всяких признаков и образов, за которые может ухватиться рассудок. <a href="#ref-16" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлоке 2 -->
        <p class="my-2" id="citation-17"><sup>17</sup> <strong>Шесть пределов смысла (<em>ṣaṭkoṭi</em>):</strong> традиция допускает два основных понимания. (1) Числовое: <em>koṭi</em> как «десять миллионов» — тогда речь идёт о шестидесяти миллионах строк изначальной, развёрнутой версии Тантры, проповеданной для божеств и бодхисаттв, тогда как дошедший до нас канонический текст «Гухьясамаджи» из 18 глав — краткая версия для людей; тем самым Нагарджуна показывает, что излагаемый им метод охватывает весь скрытый объём и смысл этой Тантры. (2) Толкование: <em>koṭi</em> как «предел, альтернатива» — по образцу мадхьямаковской <em>catuṣkoṭi</em> («тетралемма», четыре альтернативы логического анализа). В комментаторской традиции линии Арья засвидетельствовано понимание <em>ṣaṭkoṭi</em> как шести граней толкования тантрического текста: 1) буквальный смысл, 2) не-буквальный, 3) скрытый, 4) прямой, 5) намеренный («сумеречный») язык, 6) прояснённый язык. Оба прочтения грамматически равноправны; не исключено, что двузначность (<em>śleṣa</em>) — часть замысла автора, одновременно указывающего на масштаб Тантры и на многослойность её толкования. <a href="#ref-17" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-18"><sup>18</sup> <strong>Сжатый метод (<em>piṇḍīkrama</em>):</strong> заглавный термин трактата, здесь переведён нейтрально, в согласии с заглавием всего произведения. Термин имеет два слоя значения. Литературный — «сжатое изложение», «конспект», структурирующий разрозненные инструкции Тантры в последовательную систему практики (садхану). Йогический (внутренний) — <em>piṇḍa</em> означает «сгусток», «единое целое»; на стадии зарождения это также метод сворачивания макрокосма вселенной в микродворец мандалы тела и сведения множественности воспринимаемых явлений к единому переживанию мандалы (ср. шлоки 198–204). Заглавие трактата, вероятно, сознательно удерживает оба смысла одновременно. <a href="#ref-18" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-19"><sup>19</sup> <strong>Благо всем живым существам (<em>sarvasattvahitodaya</em>):</strong> Нагарджуна подчёркивает, что изложение этого метода направлено на благо всех существ. Тем самым уже в начале трактата задаётся махаянская мотивация всего последующего изложения. <a href="#ref-19" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлоке 3 (продолжение сквозной нумерации) -->
        <p class="my-2" id="citation-20"><sup>20</sup> <strong>Отпечатки умозрительных построений (<em>vikalpavāsanādoṣa</em>):</strong> термин сложен из двух частей: <em>vikalpa</em> обозначает умозрительные построения, посредством которых переживание разделяется на воспринимающего и воспринимаемое. <em>Vāsanā</em> — остаточные склонности, сохраняющиеся в потоке сознания и поддерживающие такое восприятие. Именно эти глубинные склонности Нагарджуна называет изъянами (<em>doṣa</em>), поскольку они служат причиной дальнейшего возникновения омрачений и страдания. <a href="#ref-20" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-21"><sup>21</sup> <strong>Вводящие в заблуждение три мира (<em>jagattraya-vimohaka</em>):</strong> «три мира» – мир желаний, мир форм и мир без форм, составляющие сферу сансарного существования. Отпечатки умозрительных построений становятся причиной ошибочного восприятия, вследствие которого существа принимают обусловленное за обладающее самостоятельным существованием. <a href="#ref-21" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-22"><sup>22</sup> <strong>Очищение посредством Йога-тантры (<em>yogatantreṇa</em>):</strong> здесь очищение (<em>śodhana</em>) понимается не как устранение явлений, а как изменение способа их восприятия. На стадии зарождения практикующий последовательно растворяет обычное восприятие и затем разворачивает чистое видение мандалы и божеств. В традиции Арья такое созерцание иногда называют «чистой викальпой», поскольку оно использует умозрительные построения как средство, которое впоследствии также оставляется. <a href="#ref-22" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлоке 4 (продолжение сквозной нумерации) -->
        <p class="my-2" id="citation-23"><sup>23</sup> <strong>Пять объектов желаний (<em>pañca kāmān</em>):</strong> формы, звуки, запахи, вкусы и осязаемые объекты, воспринимаемые посредством пяти органов чувств. В данном контексте <em>parityajya</em> («полностью оставив») означает отказ не от самих чувственных объектов, а от привязанности и цепляния за них как обладающих самостоятельным существованием. В практике Гухьясамаджи те же самые объекты становятся частью пути благодаря их очищенному восприятию и включению в созерцание мандалы. <a href="#ref-23" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-24"><sup>24</sup> <strong>Не следует истязать себя аскезой (<em>tapas</em>):</strong> в древней Индии в ряде учений считалось, что для укрощения ума нужно подвергать тело суровой дисциплине – голодать, подолгу сидеть неподвижно, терпеть боль. Традиция Гухьясамаджи не считает физическое изнурение необходимым. Для тантрической практики необходимы устойчивость тела и ума, поскольку работа с внутренними процессами требует сохранения их естественного равновесия. <a href="#ref-24" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-25"><sup>25</sup> <strong>Следуя учению Йога-тантры (<em>yogatantrānusārataḥ</em>):</strong> слово <em>anusārataḥ</em> подчёркивает необходимость точного следования наставлениям Йога-тантры. Использование блаженства как части пути возможно лишь в рамках целостной системы практики, где все её элементы взаимосвязаны и последовательно развиваются. <a href="#ref-25" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-26"><sup>26</sup> <strong>Поддерживать Пробуждение посредством блаженства (<em>sukhena dhārayed bodhiṃ</em>):</strong> <em>Sukha</em> (блаженство/радость) здесь обозначает собое йогическое переживание блаженства, занимающее центральное место в практике Высшей Йога-тантры (<em>mahāsukha</em>), рождающееся в теле, когда йогин собирает ветры-праны в центральном канале. Обычный ум чрезвычайно подвижен; Сутра пытается остановить его годами сухой медитации. Тантра использует блаженство как «клей» – когда тонкие капли-бинду плавятся внутри центрального канала, ум мгновенно замирает, двойственное различение исчезает само собой, и обнажается чистая Шуньята. Переживание недвойственности блаженства и шуньяты (<em>sukha-śūnyatā</em>) – самый быстрый способ реализовать природу Будды за одну жизнь. <a href="#ref-26" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлоке 5 (продолжение сквозной нумерации) -->
        <p class="my-2" id="citation-27"><sup>27</sup> <strong>Пребывающий в самваре (<em>saṃvarasthaḥ</em>):</strong> <em>saṃvara</em> охватывает совокупность дисциплины, обязательств и стиля практики, благодаря которым становится возможным дальнейшее осуществление Ваджра Тела, Речи и Ума. Это внутренняя установка, поддерживающая чистоту практики и служащая её необходимым основанием. <a href="#ref-27" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-28"><sup>28</sup> <strong>Непоколебимо соблюдающий обеты (<em>bhedyaḥ sarvadā vratī</em>):</strong> слово <em>abhedya</em> означает «несокрушимый», «неподдающийся нарушению». Оно характеризует твёрдость практикующего в соблюдении принятых обязательств (<em>vrata</em>). Тем самым подчёркивается необходимость постоянства и непрерывности тантрической дисциплины. <a href="#ref-28" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-29"><sup>29</sup> <strong>Приступить к практике Ваджра Тела, Речи и Ума (<em>kāyavākcittavajrasya sādhana</em>):</strong> слово <em>sādhana</em> означает и выполнение ритуальных действий, и последовательное осуществление пути. Практика Ваджра Тела, Речи и Ума представляет собой основу дальнейшего тантрического созерцания, в котором обычные тело, речь и ум постепенно преобразуются в соответствующие аспекты состояния Будды. <a href="#ref-29" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлоке 6 (продолжение сквозной нумерации) -->
        <p class="my-2" id="citation-30"><sup>30</sup> <strong>Глухие леса, цветы, плоды и безлюдная гора:</strong> в комментаторской традиции это описание места практики допускает несколько уровней истолкования. <em>Буквальный</em> – указывает на реальное уединённое место в лесу или горах, как сказано в XII главе «Гухьясамаджа-тантры». В <em>йогическом</em> истолковании отдельные элементы пейзажа могут соотноситься с внутренним телом практикующего: лес — с сетью каналов, гора — с центральным каналом или осью тела, цветы — с чакрами, плоды — с каплями (<em>bindu</em>), а уединённость — с внутренним сосредоточением. <em>Тайный (сумеречный язык, sandhyābhāṣā)</em> – в некоторых поздних комментариях эти термины выступают иносказаниями: лес – волосы, гора – женское тело, цветы – йони, плод – бинду, что является обычным приёмом в текстах Высшей Йога-тантры. <a href="#ref-30" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-31"><sup>31</sup> <strong>Совокупность всех сиддхи (<em>sarvasiddhisamuccaya</em>):</strong> данная шлока почти дословно воспроизводит вторую шлоку XII главы «Гухьясамаджа-тантры». В каноническом тексте выражение <em>sarvasiddhisamuccaya</em> стоит в винительном падеже и обозначает «совокупность всех сиддхи», а не название отдельного произведения. Тибетский перевод Пиндикрамы также передаёт это выражение как обычное словосочетание, что подтверждает именно такое понимание. <a href="#ref-31" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлоке 7 (продолжение сквозной нумерации) -->
        <p class="my-2" id="citation-32"><sup>32</sup> <strong>Мягкое сиденье (<em>mṛdvāsana</em>):</strong> как уже указывалось в шлоке 4, в Высших Тантрах запрещён изнуряющий аскетизм. Йогин не должен сидеть на жёстких камнях или голой земле, причиняя телу боль. Мягкое удобное сиденье необходимо, чтобы каналы тела не пережимались, а энергия циркулировала свободно и ровно. <a href="#ref-32" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-33"><sup>33</sup> <strong>Поза бодхисаттвы (<em>sattvaparyaṅka</em>):</strong> санскрит и тибетский текст называют её «позой бодхисаттвы», не описывая подробно её форму. В различных тантрических традициях она понимается как одна из устойчивых медитативных поз, обеспечивающих неподвижность тела и пригодных для длительного созерцания. <a href="#ref-33" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-34"><sup>34</sup> <strong>Самадхи Ваджра Гнева (<em>dveṣavajra</em>):</strong> в традиции Гухьясамаджи Ваджр Гнева обычно соотносится с семейством Акшобхьи, преобразующим гнев в Зерцалоподобную мудрость (<em>ādarśajñāna</em>). Поэтому пребывание в данном самадхи понимается как созерцание в соответствии с этим аспектом пути. <a href="#ref-34" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-35"><sup>35</sup> <strong>Защита места практики (<em>sthānarakṣā</em>):</strong> установление защиты пространства представляет собой один из начальных этапов тантрической садханы. Практикующий посредством визуализации, мантры и сосредоточения делает место практики свободным от препятствий и пригодным для дальнейшего развёртывания созерцания. В последующих шлоках этот этап получает дальнейшее развитие через появление гневных защитных божеств. <a href="#ref-35" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлокам 8–9 (продолжение сквозной нумерации) -->
        <p class="my-2" id="citation-36"><sup>36</sup> <strong>Десять Гневных (<em>daśakrodhān</em>):</strong> это десять гневных охранителей (кродха), излучаемых из сердца йогина, созерцающего себя Гневным Акшобхьей. Слово <em>samutsṛjya</em> («испустив/излучив») подчёркивает, что они не приходят извне, и являются проявлениями собственной просветлённой природы ума практикующего. <a href="#ref-36" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-37"><sup>37</sup> <strong>Пылающие, сияющие и устрашающие (<em>jvālābhāsurabhīṣaṇa</em>):</strong> божества объяты огнём изначальной мудрости (<em>jñānāgni</em>), который символизирует уничтожение омрачений и препятствий. Их устрашающий облик – проявление силы, сокрушающей неведение. <a href="#ref-37" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-38"><sup>38</sup> <strong>Возникшие из слога ХУМ:</strong> слог <em>hūṃ</em> в Тантрах – семенной слог ума всех Будд. Йогин, созерцающий себя в форме Акшобхьи, сосредотачивается на сердце, где на лотосе и солнечном диске стоит синий слог ХУМ. Произнося нарастающий звук ХУМ-М-М, он излучает из этого слога десять лучей света, несущих слоги ХУМ на солнечных дисках, которые, достигнув границ десяти сторон, преобразуются в десять Гневных. <a href="#ref-38" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-39"><sup>39</sup> <strong>Пребывающие на солнечных дисках (<em>bhānustha</em>):</strong> солнечный диск (<em>bhānu / sūrya</em>) символизирует праджню – озаряющую, выжигающую неведение мудрость. Каждый слог ХУМ и соответствующее ему гневное божество находятся на своём солнечном диске-опоре, что указывает на их природу как чистого знания, разрушающего тьму неведения. <a href="#ref-39" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-40"><sup>40</sup> <strong>Поза пратьялидха (<em>pratyālīḍhapada</em>):</strong> традиционная боевая стойка (правая нога согнута, левая вытянута). Она символизирует подавление неведения и победу над силами Мары. <a href="#ref-40" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-41"><sup>41</sup> <strong>На краях мандалы десяти направлений (<em>daśadigmaṇḍalāgre</em>):</strong> десять сторон света включают четыре основные, четыре промежуточные, а также зенит и надир. Размещая божеств на «вершинах» или границах мандалы во всех десяти направлениях, йогин создаёт замкнутое защищённое пространство. <a href="#ref-41" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-42"><sup>42</sup> <strong>Уничтожение всех препятствий (<em>sarvavighnavināśa</em>):</strong> цель данного ритуала – полностью устранить все внешние и внутренние помехи для практики: от злых духов и болезней до привязанностей и умозрительных отвлечений. <a href="#ref-42" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-43"><sup>43</sup> <strong>Повелев Сумбхе (<em>Sumbham ājñāya</em>):</strong> имя Сумбха (Сумбхараджа), одного из десяти гневных божеств, также известно по широко распространённой мантре очищения пространства («Ом Сумбха Нисумбха Хум...»). «Отдав приказ» Сумбхе, практикующий повелевает ему совершить действиев — уничтожить и пригвоздить зловредных духов, препятствующих практике. <a href="#ref-43" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-44"><sup>44</sup> <strong>Пригвоздить килой (<em>kīlayet</em>):</strong> кила (тиб. <em>phur ba</em>) – ритуальный трёхгранный кинжал, символизирующий неразрушимую силу пробуждённой мудрости. На внешнем (ритуальном) уровне это пригвождает и парализует злых духов и препятствия, изгоняя их с места созерцания. На внутреннем (йогическом) уровне три грани килы символизируют три ваджра (Тело, Речь, Ум Будды), а само пригвождение символизирует устранение препятствий, удерживающих ум в рассеянности, и окончательное утверждение устойчивого созерцания. <a href="#ref-44" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлоке 10 (продолжение сквозной нумерации) -->
        <p class="my-2" id="citation-45"><sup>45</sup> <strong>Гневный облик (<em>krodharūpa</em>):</strong> указывает на состояние практикующего, уже объединившего свой ум с Ваджром Гнева – Буддой Акшобхьей. Силой этого гневного состояния он приводит в движение своего слугу – Нисумбхараджу. Слово «этим» (<em>anena</em>) подчёркивает, что все последующие действия совершаются именно из этого состояния, не являющегося обычным человеческим гневом. В традиции Гухьясамаджи такой гнев понимается как проявление пробуждённой деятельности, направленной на устранение препятствий. <a href="#ref-45" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-46"><sup>46</sup> <strong>Притянув владык препятствий (<em>vināyakān ākṛṣya</em>):</strong> Нисумбхараджа по приказу йогина устремляется во все стороны света, железным крюком насильственно захватывает владык помех, арканом притягивает и ставит их перед десятью стражами, расположенными по краям защитного круга. В толкованиях школы Нагарджуны (Арья) <em>vināyaka</em> – это не внешние зловредные существа, а образы собственных хаотических ветров-энергий, блуждающих по правому и левому каналам тела и порождающих непрерывное блуждание мыслей. «Притянуть» – значит стянуть эти рассеянные силы и успокоить. <a href="#ref-46" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-47"><sup>47</sup> <strong>В соответствии с ритуальным предписанием (<em>vidhivat</em>):</strong> указывает на строгое соблюдение направлений и канонических правил. Каждая помеха должна быть намертво закреплена в своём секторе на внешней границе круга, что прекращает всякий хаос. Это отсылка к точным инструкциям из 13-й главы коренной «Гухьясамаджа-тантры». <a href="#ref-47" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-48"><sup>48</sup> <strong>Посредством данного ритуала (<em>prayogeṇa</em>):</strong> <em>prayoga</em> означает практическое применение предписанного метода. Здесь речь идёт о правильном выполнении всей последовательности защитного ритуала. <a href="#ref-48" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-49"><sup>49</sup> <strong>Пригвоздить килой (<em>kīlayet</em>):</strong> вколачивание ритуального кола-килы (тиб. <em>phur ba</em>), подробно разобранное нами в сноске 44. В контексте Высших Тантр образ вонзания ваджрного острия в голову, конечности или сердце вредоносного существа знаменует метод гневного сострадания. Ритуальное пронзание символизирует окончательное подчинение омрачений действию пробуждённой мудрости. В некоторых линиях передачи это действие истолковывается как собирание рассеянных жизненных ветров (<em>prāṇa</em>) в центральном канале (<em>avadhūtī</em>), что создаёт условия для прекращения цепляния за «я» и проявления бодхичитты. <a href="#ref-49" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлокам 11–12 (продолжение сквозной нумерации) -->
        <p class="my-2" id="citation-50"><sup>50</sup> <strong>Форма острия Ваджракилы (<em>śūlākāra</em>):</strong> шлока описывает телесную форму самого божества как оружие. Нижняя часть его тела (от пупка и ниже) имеет вид острия килы (трёхгранного кинжала), тогда как верхняя разворачивается как антропоморфный образ Гневного Божества. Тем самым Ваджракила предстаёт как единое неразделимое сочетание ритуального орудия и гневного образа пробуждённого состояния. <a href="#ref-50" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-51"><sup>51</sup> <strong>Гневное Божество, трёхликое и шестирукое (<em>krodhākṛti trimukha ṣaṭbhuja</em>):</strong> разделение тела в области пупка (<em>nābhideśa</em>) имеет йогическое значение. Пупочный центр является очагом зарождения внутреннего тепла (<em>caṇḍālī</em>). Превращение нижней части тела в острое ваджрное лезвие позволяет йогину перекрыть нисходящие токи энергии, удерживая их внутри центрального канала. Трёхликая и шестирукая форма верхней части тела знаменует преображение обычных тела, речи и ума в три неразрушимых Ваджра всех Татхагат. Становясь живым ваджрным колом, практикующий полностью подчиняет себе пространство созерцания, лишая блуждающие ветры ума возможности порождать сансарические иллюзии. <a href="#ref-51" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлоке 13 -->
        <p class="my-2" id="citation-52"><sup>52</sup> <strong>Пригвождение препятствий ваджрной килой:</strong> тринадцатая шлока вместе с сопровождающей её мантрой относится к завершению ритуала очищения и закрепления защитного круга. Взгляд, направленный вниз (<em>adho vighnagaṇān vīkṣya</em>), обращён к сонмам препятствующих сил, уже собранных у защитного круга. Глагол <em>nikhanet</em> («глубоко вбить», «прочно вонзить») подчёркивает необратимость действия. На внутреннем уровне пригвождение символизирует полное подчинение омрачений действию пробуждённой мудрости. Повелительные формы мантры — <em>ghātaya</em> («порази»), <em>kīlaya</em> («пригвозди») и завершающий слог <em>phaṭ</em> — последовательно выражают поражение, закрепление и окончательное отсечение препятствующих сил. <a href="#ref-52" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлоке 14 -->
        <p class="my-2" id="citation-53"><sup>53</sup> <strong>Ваджрный молот (<em>vajramudgara</em>):</strong> в ритуальной практике он служит орудием для вколачивания килы, поэтому появление Сумбхараджи естественно продолжает предшествующие шлоки, где препятствия были пригвождены ваджрной килой. В созерцании кила и ваджрный молот дополняют друг друга: кила обездвиживает препятствия, а молот окончательно закрепляет её, делая достигнутый результат необратимым. <a href="#ref-53" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлоке 15 -->
        <p class="my-2" id="citation-54"><sup>54</sup> <strong>Очищение пространства ваджрным огнём:</strong> пятнадцатая шлока продолжает защитную фазу ритуала, описывая очищение пространства ваджрным огнём (<em>vajravahni</em>). После закрепления килы защитный круг охватывается пламенем пробуждённой мудрости, уничтожающим последние проявления препятствующих сил. Образы мечущихся и испускающих вопли препятствующих существ (<em>pralapitāṃś</em>) символизируют окончательное разрушение омрачений и привычных способов восприятия. Тем самым защитная мандала полностью очищается и становится пригодной для дальнейших этапов созерцания. Определённую параллель этому образу можно усмотреть в некоторых практиках тибетской йоги каналов и ветров, в частности в упражнениях внутреннего тепла (<em>gtum mo</em>), где используется приём <em>'bebs babs</em> («падение»). Во время этого упражнения резкое воздействие на основание тела применяется как средство направления ветров в центральный канал и возжигания внутреннего тепла. Хотя между данным ритуальным описанием и более поздними йогическими техниками нельзя проводить прямого исторического тождества, в обоих случаях используется сходная символика: закрепление основания, прекращение рассеянности и возгорание очищающего внутреннего огня. <a href="#ref-54" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлоке 16 -->
        <p class="my-2" id="citation-55"><sup>55</sup> <strong>Созерцание трёх миров как лишённых собственной природы (<em>niḥsvabhāva</em>):</strong> благословив верх и низ (<em>adha ūrdhvam adhiṣya</em>), йогин завершает построение защитной сферы, полностью запечатывая пространство практики. Однако в методологии Высших Тантр любая визуализация относится к сфере умозрительных построений (<em>vikalpa</em>) и служит лишь искусным средством. Поэтому сразу после завершения защитного ритуала практикующий обращается к созерцанию высшей истины (<em>paramārtha</em>). Он созерцает, что защитники, препятствия и сами три мира (<em>bhavatraya</em>) не обладают собственной природой (<em>niḥsvabhāva</em>), возникая лишь зависимо от причин, условий и мысленного обозначения. Таким образом вся совокупность ранее выстроенных образов вновь растворяется в таковости. Такое «растворение в таковости» / «растворение в Ясном Свете» предотвращает цепляние за ритуальные построения как за обладающие собственной природой и подготавливает переход к следующему этапу садханы — развёртыванию чистой мандалы Гухьясамаджи из состояния Ясного Света. Можно отметить определённую символическую параллель с практиками йоги каналов и ветров, где запечатывание верхнего и нижнего направлений также предшествует введению ветров в центральный канал и последующему переживанию Ясного Света. Хотя данная шлока описывает последовательность ритуального созерцания, а не технику внутренней йоги, структурное сходство обоих методов заслуживает внимания. <a href="#ref-55" class="text-blue-500 hover:underline">↩</a></p>
        <!-- Блок примечаний к шлоке 17 -->
        <p class="my-2" id="citation-56"><sup>56</sup> <strong>Необнаружимость созерцания:</strong> семнадцатая шлока воспроизводит строфу из второй главы «Гухьясамаджа-тантры». Когда все явления созерцаются как не обладающие собственной природой, исчезает и обычный акт созерцания. Поэтому само созерцание невозможно обнаружить (<em>bhāvanā nopalabhyate</em>) как нечто существующее само по себе и устраняется разделение на созерцающего, созерцаемое и сам акт созерцания, открывая путь к непосредственному переживанию Таковости. <a href="#ref-56" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлоке 18 -->
        <p class="my-2" id="citation-57"><sup>57</sup> <strong>Подвижное и неподвижное (<em>sthiracarātmaka</em>), Основа Мудрости (<em>jñānabhūmi</em>):</strong> древнеиндийское сложносоставное слово <em>sthira-cara</em> (тиб. <em>rgyu mi rgyu</em>) — устойчивое выражение, обозначающее весь проявленный мир. «Неподвижное» (<em>sthira</em>) — это неодушевлённый мир природы, элементы, горы, дома, физическое пространство и сам защитный ваджрный дворец, построенный йогином. «Подвижное» (<em>cara</em>) — одушевлённый мир: живые существа, люди, боги и препятствующие силы. Йогин созерцает всё подвижное и неподвижное как шунью, то есть как не обладающее неизменной собственной природой. В таком созерцании исчезает различение между внешним и внутренним, между воспринимающим и воспринимаемым. «Уровень мудрости / Основа Мудрости» (<em>jñānabhūmi</em>) — это Ум Ясного Света (<em>prabhāsvara-citta</em>), изначальная основа ума, очищенная от умозрительных наслоений. Когда прекращается цепляние за внешнее и внутреннее, двойственный ум затихает, и становится явной светоносная природа ума. <a href="#ref-57" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-58"><sup>58</sup> <strong>Посредством данного метода (<em>vidhiyogena</em>):</strong> слово <em>vidhiyogena</em> (тиб. <em>cho ga'i sbyor ba</em>) означает «посредством применения этого йогического приёма». Сам приём заключался в последовательности: 1) построение защитных границ, 2) стягивание помех, 3) созерцание всей ранее выстроенной визуализации как не обладающей неизменной собственной природой посредством строфы, приведённой в предыдущей шлоке. Глагол <em>adhiṣyate</em> (тиб. <em>byin gyis brlab</em>) означает «благословляется», «утверждается» или «наделяется силой». Благодаря этому методу сознание утверждается в Основе Мудрости (<em>jñānabhūmi</em>), становящейся основанием для последующего развёртывания чистой мандалы. <a href="#ref-58" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлоке 19 -->
        <p class="my-2" id="citation-59"><sup>59</sup> <strong>Мандала ветра, два слога ХУМ и два ваджра (<em>vāyumaṇḍala</em>, <em>dvihūṃyaṃbījaniṣpanna</em>, <em>vajradvaya</em>):</strong> после растворения всех образов в шуньяте начинается развёртывание чистой мандалы. Первой проявляется мандала ветра. Это соответствует буддийской космологии, согласно которой после разрушения мира из пространства (<em>ākāśadhātu</em>) прежде всего возникает тонкий первичный ветер, постепенно сгущающийся в диск ветра, служащий основанием для последующего развёртывания мира. В традиции «Гухьясамаджи» мандала ветра созерцается в форме дымчатого полумесяца, на двух концах которого расположены два ваджра. Они символизируют устойчивость и неразрушимость основания, удерживая подвижную природу ветра в равновесии. В отличие от большинства тантрических визуализаций, где проявление возникает из одного семенного слога, здесь мандала ветра рождается из двух слогов ХУМ и слога ЯМ. В традиции Арья два слога ХУМ могут рассматриваться как символ двух боковых каналов, по которым в обычном состоянии движутся ветры, поддерживающие двойственное восприятие. В таком прочтении их очищение знаменует преображение обычных ветров в просветлённую энергию. Поэтому мандала ветра становится первым основанием, на котором последовательно разворачивается вся чистая мандала Гухьясамаджи. <a href="#ref-59" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлоке 20 -->
        <p class="my-2" id="citation-60"><sup>60</sup> <strong>Мандала огня (<em>agnimaṇḍala</em>):</strong> проявление диска огня (<em>agnimaṇḍala</em>) над мандалой ветра (<em>tasyopari</em>) соответствует буддийской космологической последовательности, согласно которой вслед за элементом ветра проявляется элемент огня. В традиции «Гухьясамаджи» мандала огня созерцается в форме красного треугольника. Два ваджра (<em>vajradvaya</em>) отмечают два его нижних угла, подчёркивая устойчивость основания и связь мандалы огня с расположенной под ней мандалой ветра. Как и в предыдущей шлоке, возникновение мандалы из семенного слога РАМ и двух слогов ХУМ допускает внутреннее йогическое истолкование. В таком прочтении два слога ХУМ соотносятся с двумя боковыми каналами, тогда как слог РАМ символизирует внутренний огонь (<em>caṇḍālī</em>, тиб. <em>gtum mo</em>). Возгорание этого огня символизирует преображение обычных энергий и направление ветров в центральный канал, подготавливая основу для дальнейшего развёртывания чистой мандалы. <a href="#ref-60" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлокам 22-25 -->
        <p class="my-2" id="citation-61"><sup>61</sup> <strong>Мандала воды (<em>vārimaṇḍala</em>):</strong> вслед за мандалой огня проявляется мандала воды, что соответствует традиционной последовательности развёртывания элементов. Огонь завершает очищение и преобразование, тогда как вода символизирует успокоение, связность и образование устойчивой основы для дальнейшего развёртывания мандалы. <a href="#ref-61" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-62"><sup>62</sup> <strong>Мандала земли (<em>pṛthivīmaṇḍala</em>):</strong> появление мандалы земли завершает построение четырёх элементных оснований. Земля символизирует устойчивость и завершённость проявленного порядка. В космологическом смысле именно на её основе становится возможным дальнейшее возведение ваджрного основания и дворца. Внутреннее йогическое истолкование связывает этот этап с достижением устойчивости созерцания, при которой очищенные ветры и внутреннее тепло пребывают в равновесии. <a href="#ref-62" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-63"><sup>63</sup> <strong>Ваджрное основание (<em>vajrabhūbhāga</em>) и дворец (<em>kūṭāgāra</em>):</strong> после завершения четырёх мандал элементов они рассматриваются как единое основание (<em>caturmaṇḍalasaṃhāra</em>). Поверх него возникает ваджрное основание — совершенно чистая и неразрушимая основа будущей мандалы. Только после этого из семенного слога <span class="font-bold italic text-red-700">BHRŪṀ</span> проявляется дворец. <a href="#ref-63" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-64"><sup>64</sup> <strong>Квадратный дворец с четырьмя вратами:</strong> квадратная форма символизирует устойчивость и полноту совершенного порядка. Четверо врат, обращённые к сторонам света, выражают открытость пробуждённой мудрости для существ всех направлений. Четыре осевые линии образуют внутреннюю структуру мандалы, определяя её центр и основные направления, а восемь колонн подчёркивают завершённость и устойчивость всего сооружения. Эти архитектурные элементы одновременно описывают внешний дворец и внутреннюю структуру созерцания, выстроенного вокруг единого центра. <a href="#ref-64" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-65"><sup>65</sup> <strong>Украшения дворца:</strong> перечисляемые гирлянды, полугирлянды, драгоценные камни, ваджры и полумесяцы не являются декоративными деталями в обычном смысле. В традиции тантры каждое украшение выражает полноту достоинств пробуждённого состояния, а сам дворец изображается как зримое проявление качеств Будды. Сходным образом в других тантрах архитектурное убранство дворца, его украшения рассматривается как самопроизвольное проявление просветлённых мудростей.</p>
        <p class="my-2">На основании иных текстов традиции можно составить более подробное описание дворца:</p>
        <p class="my-2">Что касается единиц измерения, их три: палец (<em>anguli</em>, тиб. <em>sor mo</em> — ширина пальца); пядь/ладонь (<em>vitasti</em>, тиб. <em>mtho</em>) = 12 пальцев; локоть (<em>hasta</em>, тиб. <em>khru mo</em>) = 2 пяди = 24 пальца; длина руки/лук (<em>dhanus</em>) = 4 локтя = 96 пальцев.</p>
        <p class="my-2">Дворец покоится на квадратном постаменте (ширина 12 длин руки, высота 5), внутри которого — вишваваджр (<em>viśvavajra</em>, 12 длин руки от вершины до вершины), символ устойчивости земли. Пять рогов ваджра окрашены по направлениям. В двумерной мандале эти рога образуют часть Т-образных врат; в трёхмерной — двадцатиступенчатые опоры-террасы находятся внутри каждой пятиконечной главы ваджра, так что горизонтальные рога окружают опору, а вертикальные рога и центральная ось проходят сквозь неё.</p>
        <p class="my-2">Каждая опора имеет лестницу из 20 ступеней (высота ступени 1 локоть, глубина — пол-локтя; терраса шириной 16 локтей), обычно разделённую на пролёты по 5 ступеней с промежуточными террасами (всего 4 террасы на опору). Четыре таких лестницы по 20 ступеней символизируют 80 второстепенных признаков Будды. Опора выступает из постамента на 14,5 локтя; её боковые стороны украшены символами направлений — колесо (восток), драгоценность (юг), лотос (запад), скрещенный ваджр и меч (север). На зубцах ваджра — резные головы макар.</p>
        <p class="my-2">Стены сотканы из света пяти цветов (изнутри наружу: синий, зелёный, красный, жёлтый, белый) — изнутри синие, снаружи белые. Толщина 1 локоть, ширина 24 локтя, высота 13 локтей. По центру каждой стены — дверной проём шириной 4 локтя с вестибюлем (1 длина руки) и внешним портиком (ширина 2 длины руки, глубина 2 локтя).</p>
        <p class="my-2">Платформа Богинь подношений: снаружи стен — платформа (в мандале — красная, с 8 или 16 белыми лотосами; во дворце высотой и шириной 2 локтя), украшенная символом золотого полу-ваджра на белом полумесяце (единство относительной и абсолютной бодхичитты) по углам и краям. 16 богинь подношений (в деревянной мандале — вырезаны из белого дерева, в танцевальной позе «лук и стрела», лицом внутрь) расположены группами по 4 (две справа, две слева):</p>
        <p class="my-2">Восток (подношение музыки): Вина (синяя, играет на вине, или лютне), Вамша (жёлтая, играет на флейте), Мураджа (зелёная, играет на двухсторонних барабанах), Мридангам (красная, играет на одностороннем барабане двумя барабанными палочками).</p>
        <p class="my-2">Юг (подношение красоты и танца): Ласья (красная Богиня очарования и красоты), Мала (синяя Богиня гирлянд и смеха), Гита (желтая Богиня песни, держащая цимбалы), Нритья (зеленая Богиня танца).</p>
        <p class="my-2">Запад (подношение цветов, благовоний, света и аромата): Пушпа (белая Богиня, подносящая цветы), Дхупа (Богиня дымчатого цвета, подносящая благовония), Дипа (красно-желтая Богиня, подносящая свет), Гандха (красная Богиня, подносящая аромат).</p>
        <p class="my-2">Север (Богини формы, вкуса, прикосновения и дхармадхату): Рупа (белая Богиня формы, держащая зеркало), Раса (красная Богиня вкуса, держащая фрукты), Спарша (зеленая Богиня, держащая шелковые одежды), Дхармадхату (красная Богиня, держащая дхармадхату в форме шестиконечной звезды).</p>
        <p class="my-2">При сокращённом варианте из 8 богинь берутся южные и западные (Ласья, Мала, Гита, Нритья, Пушпа, Дхупа, Дипа, или Алока (свет), и Гандха).</p>
        <p class="my-2">По верху стен дворца проходит декоративный золотой фриз, состоящий из геометрических символов пяти элементов: квадраты (земля), круги (вода), треугольники (огонь), полумесяцы (ветер), пустые промежутки (пространство). Высота фриза 1 локоть, толщина пол-локтя. В мандале — тёмно-синяя полоса с жемчужными подвесками снаружи платформы подношений; во дворце — оформлен как вентиляционная решётка высотой 2 локтя, толщиной 1 локоть, из двух ярусов.</p>
        <p class="my-2">Вентиляционная решётка из семи драгоценностей. Слои (снизу вверх): 1) кубический изумруд, 2) сужающийся рубин, 3) пластина бирюзы в форме лука, 4) два кубических кристалла по краям бирюзы, 5) два клина ляпис-лазури, 6) серебро в форме лука, 7) тонкая золотая балка поверх стен и вестибюлей. Каждый ярус — 1 локоть шириной и высотой; решётка зажата между двумя золотыми балками (у других мандал — 4 яруса, здесь 2; общая высота скреплённых слоёв — пол-локтя).</p>
        <p class="my-2">Структура крыши: скрытая внутри деревянной мандалы конструкция. Четыре основные поперечные балки (34 локтя длиной, сечение 1 кв. локоть) пересекаются крест-накрест (восток–запад, север–юг) с интервалом 10 локтей, деля потолок на 9 квадратных секций. Балки сходятся с круговой балкой (радиус — половина расстояния от центра до угла дворца). Перемычки (6 локтей, сечение 1 локоть) входят в решётку над каждым дверным проёмом.</p>
        <p class="my-2">Восемь опор стоят кольцом под круговой балкой вокруг центрального ваджрного постамента; толщина каждой — 1 локоть; рифлёные, с двойным лотосом в основании и расширяющейся кверху драгоценной конструкцией. Символизируют «сосуд неистощимых сокровищ» и семь драгоценностей Чакравартина.</p>
        <p class="my-2">Стропила: 28 стропил (4 группы) идут от стен к центральному квадратному проёму, оставляя отверстие для светового люка; их концы соединяются с 4 диагональными стропилами от углов. Внешние концы (украшены головами макар) выступают на 1 локоть, с жемчужными подвесками. 28 стропил символизируют лунные созвездия (луна = бодхичитта); общее число стропил — 112 — символизирует 32 главных и 80 второстепенных признаков Будды. Поверх — рейки «ёлочкой» с ваджрным скреплением.</p>
        <p class="my-2">Кронштейны и «сушики»: Каждое стропило несёт кронштейн с ликом обезьяны (на локоть выше макар); снизу кронштейна — водосточная труба-«сушика» (в форме слоновьего хобота / перевёрнутой ступы), с которой свисают зеркало (Ум, Дхармакая), колокольчик (Речь, Самбхогакая) и метёлка из ячьего хвоста (сострадание, Нирманакая). В мандале эти сушики изображаются уменьшающимся рядом ступообразных линий после жемчужного фриза.</p>
        <p class="my-2">Кронштейны поддерживают нависающий портик по всему краю крыши; над ним — парапет из половинок лотоса (1 локоть шириной и высотой) — в мандале это шестой, финальный белый квадрат мандалы, украшенный лепестками лотоса.</p></p>
        <p class="my-2">В центре каждой из четырёх стен расположена симметричная пара дверей, открывающихся наружу. Каждая дверь имеет толщину пол-локтя, ширину полтора и высоту двенадцать локтей; в закрытом состоянии они находятся вровень с внутренними стенами мандалы. Двери помещены в прямоугольные проёмы шириной пол-локтя. Над каждым входом находится фрамуга высотой два и шириной четыре локтя, разделённая на восемь квадратных панелей с символами соответствующего направления: белыми колёсами на востоке, жёлтыми драгоценностями на юге, красными лотосами на западе и зелёными пылающими мечами на севере.</p>
        <p class="my-2">Каждый вход имеет двадцатиступенчатую лестницу, ведущую на шестнадцатилоктевую террасу, над которой возвышается одиннадцатислойная триумфальная арка (<em>toraṇa</em>). По сторонам входа, на расстоянии одного локтя от стены, стоят две украшенные колонны. Они покоятся на пьедесталах длиной три и шириной один локоть; золотые вазы служат их основаниями. Восьмиугольные колонны имеют высоту пять и ширину около одного локтя; сверху они завершаются золотыми капителями высотой один и шириной два с половиной локтя.</p>
        <p class="my-2">Арка состоит из одиннадцати декоративных слоёв. Первые семь образованы отдельными парами блоков, украшенных соответственно «слоновьими хоботами», символами пяти элементов, облачными орнаментами и символами четырёх направлений — колесом или слоном на востоке, драгоценностью или конём на юге, лотосом или павлином на западе, мечом или гарудой на севере. Верхние три слоя представляют собой длинные горизонтальные блоки: восьмой и десятый украшены «слоновьими хоботами», девятый — символами пяти элементов. Одиннадцатый слой образует парапет из белых лепестков лотоса.</p>
        <p class="my-2">Внутренний контур каждой арки выстлан красной мембраной с рядом белых кругов, символизирующих единство Двух истин; белые круги представлены также как семена бодхичитты, проникающие в красную почву мудрости. Глубина арок составляет три локтя. На выступах некоторых слоёв стоят золотые вазы с древками шёлковых победных знамён и декоративных флагов. В центре вершины каждой арки находится золотая восьмиспицевая дхармачакра диаметром один локоть; по её сторонам изображены олень и олениха, напоминающие о первом повороте Колеса Учения в Оленьем парке Сарнатха. За оленями находятся обезьяны с белыми зонтами, увенчанными исполняющей желания драгоценностью; такие изображения располагаются также по углам крыши.</p>
        <p class="my-2">По сторонам каждого входа стоят большие золотые вазы с исполняющими желания деревьями. Вазы украшены семью символами Чакравартина: колесом, драгоценностью, исполняющей желания, царицей, министром, военачальником, конём и слоном. На вершине каждого дерева находится металлический стержень с изображением Будды соответствующего направления, сидящего в ваджрной позе на лунном диске и лотосе. Над парапетом также размещены золотые вазы со знамёнами, а между ними — стержень с изображением божеств на облаке. Восемь богов и богинь, расположенные по углам дворца, держат арочные гирлянды из драгоценных цветочных бутонов.</p>
        <p class="my-2">В трёхмерной мандале в потолке дворца устроен квадратный световой люк со стороной десять локтей; в двухмерных живописных и песочных мандалах он обычно не изображается. Четыре плоские балки, закрепленные на плоской крыше и идущие вниз через середину потолочных балок, образуют бордюр вокруг этого квадратного отверстия. Длина этих четырех балок двенадцать локтей, ширина — один локоть, толщина — пол-локтя. Они служат основанием для двенадцати колонн светового люка. Эти колонны красного цвета, высотой в три с половиной локтя и с сечением в один локоть. Четыре колонны находятся в углах люка, остальные восемь расположены через равные промежутки между углами и на каждой из четырех сторон.</p>
        <p class="my-2">Двенадцать колонн символизируют двенадцать аятан, а пространство между ними — пустотную природу двенадцати звеньев взаимозависимого возникновения и двенадцати астрологических периодов. Их капители украшены облачными контрфорсами. Четыре балки образуют каркас люка и поддерживают плоский потолок размером шестнадцать на шестнадцать локтей и толщиной пол-локтя. Потолок окружён фризом из лепестков лотоса; в его углах помещены четыре головы макар, символизирующие четыре основы чудесных сил.</p>
        <p class="my-2">Над потолком находится золотая наклонная крыша. Её высота меняется от двенадцати до шести локтей; плоский конёк имеет длину двенадцать, ширину три и высоту один локоть. По краям конька находятся головы гаруд, а в центре — драгоценная кубическая шкатулка со стороной два локтя, содержащая Учения, Тантры и комментарии Гухьясамаджи. Над шкатулкой помещена многогранная драгоценность, символизирующая сияющую природу ума Гухьясамаджи, а над ней — вертикальный золотой ваджр высотой полтора локтя. Его кончик касается лотосового лона, окружающего дворец.</p>
        <p class="my-2">Общая высота дворца над ваджрным основанием составляет тридцать два локтя, что соответствует внутреннему сечению дворцового зала.</p>
        <p class="my-2">Дворец с квадратным цоколем, ступенчатыми контрфорсами и соединёнными зубцами вишва-ваджры окружён тремя защитными кругами, расположенными на уровне земли на восьмиугольной деревянной основе. Квадратный цоколь имеет ширину двенадцать длин руки и высоту пять; длина вишва-ваджры от конца до конца также составляет двенадцать длин руки. Внутренний диаметр защитной системы — двадцать, общий диаметр мандалы — двадцать четыре длины руки, или девяносто шесть локтей. Все три круга разделены на 64 равных сегмента, по 16 в каждом из четырёх основных квадрантов.</p>
        <p class="my-2">Первый круг — «Лотосовое лоно». Его ширина три локтя. Он образован 64 лепестками с чередующейся розово-оранжевой и зелёно-голубой окраской; лепестки основных и промежуточных направлений выделяются особым цветом. Шестьдесят четыре лепестка соответствуют 64 лепесткам лотосовой чакры пупочного центра. Лотосовое лоно символизирует чистоту мандалы и возможность рождения внутри неё лишь для чистых сердцем. Поднимаясь вверх, лотос образует полусферический купол, охраняющий дворец.</p>
        <p class="my-2">Второй круг — «Ваджрная ограда». Его ширина один локоть. В двумерных мандалах он может изображаться как тёмно-синее кольцо с 8, 16 или 32 ваджрами, соединёнными золотой ваджрной нитью; в трёхмерной мандале он представлен 64 симметричными пятиспицевыми ваджрами. Ограда образует непроницаемую защитную решётку и, расширяясь вверх, — ваджрный купол. 32 ваджра соответствуют 32 основным признакам Будды, а 64 указывают на их внешнее и внутреннее значение. Ваджрная ограда также символизирует защиту мандалы от нарушивших ваджрные обеты и от разрушительных природных сил.</p>
        <p class="my-2">Третий круг — «Гирлянда огня». Его ширина четыре локтя. Он состоит из 32 цветных языков огня мудрости, каждый из которых занимает два из 64 сегментов. Языки последовательно окрашены в белый, жёлтый, красный, зелёный и тёмно-синий цвета; два последних имеют оранжевую и бирюзовую окраску. 32 языка соответствуют 32 лепесткам колеса великого блаженства макушечной чакры. Подобно ваджрному куполу, огненная гирлянда образует окружающую дворец полусферу пламени, очищающего мандалу от загрязнений и препятствующего проникновению негативных сил.</p>
        <p class="my-2">Пять цветов огня и света дворца соответствуют мудрости пяти Будд: белому Вайрочане на востоке, жёлтому Ратнасамбхаве на юге, красному Амитабхе на западе, зелёному Амогхасиддхи на севере и тёмно-синему Гухьясамадже в форме Ваджра-Акшобхьи в центре.</p>
        <p class="my-2">Три защитных круга соотносятся с тремя разрушительными энергиями — страстью, неведением и ненавистью — и символизируют соответствующие им противоядия. В космологическом плане они также защищают мандалу от трёх великих катастроф: наводнения, землетрясения и пожара. <a href="#ref-65" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлокам 27-35 -->
        <p class="my-2" id="citation-66"><sup>66</sup> <strong>Размещение тридцати двух божеств в мандале:</strong> шлоки 27–35 завершают построение дворца безграничного пространства его наполнением. После возникновения мандалы из шуньяты практикующий созерцает себя в центре, а затем последовательно размещает остальных божеств на строго определённых местах. Тем самым мандала предстаёт как упорядоченное поле пробуждённой мудрости, в котором каждое божество выражает определённый аспект просветлённой деятельности и занимает своё неизменное место относительно центра и сторон света. Последовательность размещения соответствует обходу мандалы по часовой стрелке (<em>pradakṣiṇā</em>), начиная с восточной стороны, что отражает традиционный принцип развёртывания сакрального пространства в индийской ритуальной практике. Такое расположение можно понимать как указание на два взаимодополняющих аспекта пробуждённой мудрости. Центральное божество и Татхагаты четырёх направлений выражают её вневременное измерение, тогда как божества промежуточных направлений, привратники и бодхисаттвы — деятельное проявление. Тем самым мандала соединяет неизменность основы с непрерывной деятельностью пробуждения. <a href="#ref-66" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлокам 36–38 -->
        <p class="my-2" id="citation-67"><sup>67</sup> <strong>Свёртывание мандалы и её растворение в Таковости:</strong> шлоки 36–38 провозглашают свёртывание мандалы после её построения. Посредством сампута-йоги (<em>sampuṭayoga</em>) все ранее созерцаемые божества вводятся в тело практикующего. Будды, пребывающие в чакрах тела, посредством круга высшей истины (<em>pāramārthikacakra</em>) вводятся в Таковость (<em>tathatā</em>). Глагол <em>mārayet</em> («умертвить») в заключительной шлоке представляет собой характерный пример сумеречного языка (<em>sandhyābhāṣā</em>) Высших Тантр. Речь не идёт об уничтожении Татхагат, подразумевается полное прекращение двойственного различения между созерцающим, созерцаемым и самим актом созерцания. Подробное изложение смысла этого этапа, как отмечает сам Нагарджуна, содержится в «Ваджрамале». <a href="#ref-67" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлокам 39–45 -->
        <p class="my-2" id="citation-68"><sup>68</sup> <strong>Свёртывание мандалы и соответствия пяти скандх:</strong> шлоки 39–45 описывают постепенное свёртывание мандалы после её полного развёртывания. Перечисляемые соответствия между скандхами, мудростями, элементами, органами чувств, объектами восприятия и гневными божествами представляют собой последовательность внутреннего созерцания стадии завершения (<em>niṣpannakrama</em>). Следует иметь в виду, что традиционное выражение «растворение элементов» носит условный характер. По мере ослабления проявленности более грубого элемента наиболее отчётливо раскрывается следующий, более тонкий уровень переживания. Именно эта последовательная смена преобладающего опыта описывается как «растворение» земли в воде, воды в огне, огня в ветре и далее — в сознании.
        </p>
        <div class="max-w-3xl mx-auto my-10 space-y-4 text-[1.0rem] leading-relaxed">
            <!-- Шлока 39: Восточный сектор -->
            <div class="rounded-lg border border-gray-400 bg-gray-50 p-4">
                <div class="font-semibold text-sky-900 mb-2">Шлока 39 — Свёртывание Восточного сектора</div>
                <div><strong>Основное направление:</strong> Восток (<em>pūrva</em>)</div>
                <div><strong>Привратник ворот:</strong> Ямантака (<em>Yamāntaka</em>)</div>
                <div><strong>Промежуточный угол:</strong> Юго-восток (<em>agni-koṇa</em>)</div>
                <div><strong>Гневный хранитель угла:</strong> Ачала (<em>Acala</em>)</div>
                <hr class="my-2 border-gray-200">
                <div><strong>Скандха:</strong> форма (<em>rūpa</em>)</div>
                <div><strong>Мудрость:</strong> Зерцалоподобная (<em>ādarśa-jñāna</em>)</div>
                <div><strong>Элемент:</strong> земля (<em>bhūdhātu</em>)</div>
                <div><strong>Орган чувств:</strong> зрение (<em>nayanendriya</em>)</div>
                <div><strong>Объект восприятия:</strong> видимая форма (<em>rūpa</em>)</div>
            </div>

            <!-- Шлока 40: Южный сектор -->
            <div class="rounded-lg border border-gray-400 bg-gray-50 p-4">
