            <!-- Шлока 43: Центральная Вертикальная Кульминация -->
            <div class="rounded-lg border-2 border-sky-500 bg-sky-50 p-4">
                <div class="font-semibold text-sky-900 mb-2">Шлока 43 — Сворачивание оси (Центр)</div>
                <div><strong>Основное направление:</strong> Центр (Сердечная чакра / <em>Anāhata</em>)</div>
                <div><strong>Вертикальная ось пространства:</strong> Зенит — Надир</div>
                <div><strong>Верхний хранитель оси:</strong> Ушнишачакравартин (<em>Uṣṇīṣacakravartin</em>)</div>
                <div><strong>Нижний хранитель оси:</strong> Сумбхараджа (<em>Śumbharāja</em>)</div>
                <hr class="my-2 border-sky-300">
                <div><strong>Скандха:</strong> сознание (<em>vijñāna</em>)</div>
                <div><strong>Мудрость:</strong> Всепроникающего пространства (<em>Dharmadhātu</em>)</div>
                <div><strong>Элемент:</strong> пространство (<em>ākāśa</em>)</div>
                <div><strong>Орган чувств:</strong> осязание (<em>tvagindriya</em>)</div>
                <div><strong>Объект восприятия:</strong> телесное ощущение / тактильный контакт (<em>spraṣṭavya</em>)</div>
                <div><strong>Раскрывается как</strong> Ясный Свет Шуньяты (<em>prabhāsvara</em>)</div>
            </div>
        </div>

        <p class="my-2">Пять этапов образуют последовательное движение от периферии мандалы к её центру. Верхний и нижний хранители — Ушнишачакравартин и Нисумбхараджа — замыкают вертикальную ось мандалы, после чего сознание раскрывается как Ясный Свет (<em>prabhāsvara</em>). Заключительные шлоки 44–46 определяют это состояние как Нирвану, Всеобъемлющую шуньяту (<em>sarvaśūnya</em>) и Дхармакаю, как лишённое видимых образов и признаков (<em>nirābhāsam alakṣaṇam</em>), обитель всех Татхагат. <a href="#ref-68" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлокам 46–50 -->
        <p class="my-2" id="citation-69"><sup>69</sup> <strong>Обратное развёртывание после Ясного Света и первые два метода полного Пробуждения:</strong> шлоки 46–50 открывают следующий этап практики — обратное развёртывание (<em>vyutthāna</em>) после пребывания в Ясном Свете. Предшествующие шлоки завершались введением мандалы в Таковость и созерцанием Дхармакаи; теперь начинается её новое проявление. Согласно объяснительной традиции Гухьясамаджи, этот переход совершается как последовательное проявление Самбхогакаи ради блага существ, поскольку Дхармакая сама по себе недоступна восприятию непробуждённых существ.</p>
        <p class="my-2">На этом этапе начинается последовательность пяти методов полного Пробуждения (<em>pañcābhisaṃbodhi</em>, тиб. <em>mngon byang lnga</em>). Первым является <strong>Пробуждение через Таковость</strong> (<em>tathatābhisaṃbodhi</em>, тиб. <em>de bzhin nyid las byang chub pa</em>), когда созерцается одна лишь шуньята Ясного Света. Вторым становится <strong>Пробуждение через Луну</strong> (<em>candrābhisaṃbodhi</em>, тиб. <em>zla ba las byang chub pa</em>): из шуньяты последовательно возникают солнечный диск, отмеченный слогом Ваджрной Речи <span class="font-bold italic text-red-700">ĀḤ</span>, лунный диск, отмеченный слогом Ваджрного Тела <span class="font-bold italic text-red-700">OṀ</span>, и красный восьмилепестковый лотос, несущий в своей сердцевине слог Ваджрного Ума <span class="font-bold italic text-red-700">HŪṀ</span>.</p>
        <p class="my-2">Согласно традиционному толкованию Гухьясамаджи, эти три основы на уровне пути соответствуют трём стадиям обратного развёртывания тонкого сознания после Ясного Света: чёрному кануну (близкому достижению), красному возрастанию и белому проявлению. Три семенных слога выражают нераздельность тонкого ума и сопровождающих его тонких ветров, тогда как три опоры служат основой для последующего проявления Самбхогакаи. В шлоке 49 солнце, лотос и Трёхслоговая мантра последовательно входят в лунный диск, который раскрывается как бодхичитта — единое световое основание последующего проявления пробуждённого тела.</p>
        <p class="my-2">Произнесением мантры <em>oṃ dharmadhātusvabhāvātmako 'ham</em> практикующий утверждает нераздельность собственного потока сознания с природой Дхармадхату. Тем самым завершаются первые два метода полного Пробуждения и подготавливается переход к трём последующим методам, в которых непосредственно раскрывается Самбхогакая. <a href="#ref-69" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлокам 51–54 -->
        <p class="my-2" id="citation-70"><sup>70</sup> <strong>Завершение пяти методов полного Пробуждения:</strong> шлоки 51–54 продолжают последовательность пяти методов полного Пробуждения (<em>pañcābhisaṃbodhi</em>, тиб. <em>mngon byang lnga</em>) и раскрывают три заключительные ступени возникновения Самбхогакаи.</p>
        <p class="my-2">Созерцание Трёхслоговой мантры (<span class="font-bold italic text-red-700">OṀ ĀḤ HŪṀ</span>) в центре лунного диска составляет третью ступень — <strong>Пробуждение через семенные слоги</strong> (<em>bījābhisaṃbodhi</em>, тиб. <em>sa bon las byang chub pa</em>). Из этих трёх слогов проявляется Изначальный Владыка (<em>Ādinātha</em>), которого традиция Арья отождествляет с Махаваджрадхарой. Это первое проявление Самбхогакаи, возникающее непосредственно из Ясного Света.</p>
        <p class="my-2">Выражение <em>akṣobhyānupraveśa</em> («вхождение в Акшобхью») обозначает четвёртую ступень — <strong>Пробуждение через атрибут</strong> (<em>mudrābhisaṃbodhi</em>, тиб. <em>phyag mtshan las byang chub pa</em>). Согласно объяснительной традиции Гухьясамаджи, семенные слоги и возникшие ранее основы соединяются и проявляются как пятиконечный синий (белый) ваджр, соответствующий семейству Акшобхьи и отмеченный коренным слогом <span class="font-bold italic text-red-700">HŪṀ</span>. Этот ваджр выражает нераздельность тончайшего ума и сопровождающего его тонкого ветра и служит непосредственной причиной следующего этапа проявления.</p>
        <p class="my-2">Из этого ваджра возникает Ваджрасаттва — пятая ступень, <strong>Пробуждение через совершенное тело</strong> (<em>kāyābhisaṃbodhi</em>, тиб. <em>sku rdzogs pa las byang chub pa</em>). В комментариях традиции этот шестирукий синий Ваджрасаттва именуется <strong>Ваджродержцем причины</strong>, поскольку именно из него впоследствии разворачивается вся мандала. На уровне основы очищения ему соответствует очищенное психическое тело существа промежуточного состояния (бардо), тогда как на уровне пути он представляет первое проявление Самбхогакаи, возникающее непосредственно из переживания Ясного Света.</p>
        <p class="my-2">Шлока 54 завершает описание этого проявления перечислением шести атрибутов Ваджрасаттвы. В правых руках он держит ваджр, колесо и лотос, а в левых — колокольчик, драгоценность и меч. Эти атрибуты выражают полноту искусных средств (<em>upāya</em>) и мудрости (<em>prajñā</em>) пяти семейств Татхагат и показывают, что Ваджрасаттва причины соединяет в себе их качества, являясь исходным проявлением, из которого далее разворачивается вся мандала тридцати двух божеств. <a href="#ref-70" class="text-blue-500 hover:underline">↩</a></p>
        <!-- Блок примечаний к шлокам 55–68 -->
        <p class="my-2" id="citation-71"><sup>71</sup> <strong>Ньяса (<em>nyāsa</em>) как построение внутренней мандалы:</strong> шлоки 55–68 описывают последовательное размещение божеств и семенных слогов в теле практикующего. После возникновения Самбхогакаи из Ясного Света (шл. 46–54) тело йогина более не рассматривается как обычное. Оно постепенно раскрывается как внутренняя мандала Гухьясамаджи, в которой каждая часть тела соотносится с определённым божеством, семейством Будд и аспектом пробуждённой мудрости.</p>
        <p class="my-2">Ньяса разворачивается четырьмя взаимосвязанными этапами. Сначала пять Татхагат посредством своих семенных слогов очищают пять скандх (<em>pañcaskandha</em>), раскрывая их как пять мудростей Будд. Затем четыре богини вводят в тело очищенные качества четырёх великих элементов — земли, воды, огня и ветра. После этого восемь великих бодхисаттв освящают органы чувств, ум и основные центры восприятия, а завершается практика размещением десяти Кродхараджей, которые запечатывают границы тела, превращая его в защищённую ваджрную мандалу.</p>
