        <script>
        document.addEventListener('DOMContentLoaded', function () {
            const topScroll = document.getElementById('top-scroll');
            const topContent = document.getElementById('top-scroll-content');
            const tableScroll = document.getElementById('table-scroll');
            const table = document.getElementById('mandala-table');

            // Ширина верхней прокрутки равна полной ширине таблицы
            topContent.style.width = table.scrollWidth + 'px';

            let syncing = false;

            topScroll.addEventListener('scroll', function () {
                if (syncing) return;
                syncing = true;
                tableScroll.scrollLeft = topScroll.scrollLeft;
                syncing = false;
            });

            tableScroll.addEventListener('scroll', function () {
                if (syncing) return;
                syncing = true;
                topScroll.scrollLeft = tableScroll.scrollLeft;
                syncing = false;
            });

            // Пересчитываем ширину при изменении окна
            window.addEventListener('resize', function () {
                topContent.style.width = table.scrollWidth + 'px';
            });
        });
        </script>
        <p class="my-2">(Таблица отражает как размещение божеств в теле, так и размещение в мандале / дворце, описанном далее в тексте)</p>
        <p class="my-2">Такое распределение отражает последовательное очищение всего человеческого опыта. Скандхи становятся мудростями, элементы — чистыми качествами тела Будды, органы чувств — проявлениями пробуждённого восприятия, а конечности и оси тела — местопребыванием гневных хранителей мандалы. Благодаря этому тело, речь и ум практикующего постепенно раскрываются как неотделимые от Тела, Речи и Ума всех Татхагат. Интересно отметить порядок перечисления Татхагат в тексте: он совпадает с их положением на авандуди, соответствует порядку атрибутов в руках центрального божества, порядку Татхагат в мандале Выдринского дубтаба и не совпадает с порядком обхода мандала в данной садхане. <a href="#ref-71" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлокам 71–77 -->
        <p class="my-2" id="citation-72"><sup>72</sup> <strong>Проявление Лочаны и множественность её форм:</strong> имя богини <em>Locanā</em> происходит от корня <em>loc</em> («видеть», «созерцать»). Тибетский перевод передаёт её именем <em>spyan</em> («глаз», «взор»), сохраняя игру слов оригинала. Поэтому выражение <em>locanāṃ vividhām</em> естественно понимать двояко: как имя богини Лочаны и одновременно как указание на множественность её проявлений, заполняющих всё пространство. Причастие <em>viniścārya</em> («проявив», «испустив») может толковаться как проявление богини посредством союза с Владыкой. Эта интерпретация раскрывает внутреннюю логику визуализации, однако сам санскрит ограничивается указанием на проявление посредством <em>ādhipatyaprayoga</em> («йоги владычества»). Проявление Лочаны служит началом последовательного развёртывания всей мандалы Тела (<em>kāyamaṇḍala</em>): сначала пространство полностью заполняется проявлениями Лочаны, затем возникает Ваджр Тела (<em>kāyavajra</em>), в центре которого созерцается Владыка (<em>adhipati</em>), после чего совершается испрошение благословения (<em>adhiṣṭhāna</em>). В комментариях <em>sarvavyomni</em> («во всём пространстве») понимается как пространство пустотности (<em>śūnyatā</em>), очищенное от обычных представлений; Лочана выступает как проявление очищенного элемента земли, заполняющего это пространство созерцания. <a href="#ref-72" class="text-blue-500 hover:underline">↩</a></p>

        <p class="my-2" id="citation-73"><sup>73</sup> <strong>Ваджр Тела (<em>kāyavajra</em>) и Владыка в его центре:</strong> согласно «Прадиподдьотане», термин <em>kāyavajra</em> в данном контексте относится к Вайрочане — Ваджру Тела. После проявления Лочаны перед практикующим разворачивается Ваджр Тела, заполняющий всё пространство, а в его центре созерцается Владыка (<em>adhipati</em>), к которому затем обращены молитвенные строфы 74–75. Лишь после получения благословения (шл. 76–78) Вайрочана вводится в тело практикующего, после чего произносится формула самоотождествления <em>oṃ sarvatathāgatakāyavajrasvabhāvātmako 'ham</em>. <a href="#ref-73" class="text-blue-500 hover:underline">↩</a></p>

        <p class="my-2" id="citation-74"><sup>74</sup> <strong>Стихи с просьбой к Буддам десяти направлений:</strong> эти строфы взяты из 12-й главы коренной «Гухьясамаджа-тантры». Их произнесение делает возможным дальнейшее отождествление с Ваджром Тела. <a href="#ref-74" class="text-blue-500 hover:underline">↩</a></p>

        <p class="my-2" id="citation-75"><sup>75</sup> <strong>Окончательное отождествление с Телом Будды:</strong> эта строфа, также восходящая к коренной тантре (глава 7), выражает завершающую стадию процесса. Практикующий утверждает Тело Будды как собственную природу. Следующая мантра служит закреплением (<em>dṛḍhīkaraṇa</em>) этого отождествления. <a href="#ref-75" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлоке 80 -->
        <p class="my-2" id="citation-76"><sup>76</sup> <strong>Обращение к Амитабхе как к Ваджру Речи:</strong> выражение <em>dharmo vai vākpathaḥ</em> буквально означает «Дхарма — воистину путь Речи». Согласно «Прадиподдьотане» (<em>Pradīpodyotana</em>), под этой формулой понимается Амитабха (Ваджрадхарма), поскольку именно он является природой пробуждённой речи (<em>vāk-svabhāva</em>). Поэтому молитва обращена к Амитабхе как владыке семейства Речи, хотя сам санскритский текст называет его не по имени, а через его действие. <a href="#ref-76" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлоке 90 -->
        <p class="my-2" id="citation-77"><sup>77</sup> <strong>Завершение трёх благословений и их объединение:</strong>
        шлоки 84–90 завершают цикл трёх благословений (<em>adhiṣṭhāna</em>) Тела, Речи и Ума. Их построение полностью повторяет структуру двух предыдущих разделов: сначала возникает биджа соответствующего семейства, затем проявляется богиня со свитой, далее произносятся две строфы-мольбы, заимствованные из XII главы «Гухьясамаджа-тантры», после чего божество вводится в тело практикующего и завершается недвойственным самоотождествлением посредством соответствующей мантры. Как и в предыдущих двух разделах, молитвы представляют собой дословную цитату из XII главы коренной тантры. Меняется только объект благословения: вместо Ваджра Тела и Ваджра Речи здесь испрашивается благословение Ваджра Ума (<em>cittavajra</em>). Согласно «Прадиподдьотане» (<em>Pradīpodyotana</em>), под «Обладателем Ваджра Ума» (<em>cittavajrin</em>) здесь понимается Акшобхья, владыка семейства Ума. Согласно тому же комментарию, последовательное благословение Тела, Речи и Ума представляет собой необходимое условие осуществления неделимости трёх ваджров (<em>trivajrābheda</em>). Только после завершения всех трёх этапов практикующий посредством заключительной мантры объединяет их в единую практику (<em>sarvātmaka</em>), приближаясь тем самым к стадии завершения (<em>niṣpannakrama</em>). <a href="#ref-77" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлокам 91–93 -->
        <p class="my-2" id="citation-78"><sup>78</sup> <strong>Завершение Великой йоги и тройственная структура существ:</strong> шлоки 91–93 завершают раздел Великой йоги (<em>mahāyoga</em>). После последовательного благословения Тела, Речи и Ума практикующий вновь собирает их в единую структуру трёх существ (<em>trisattva</em>): Самаясаттвы, Джнянасаттвы и Самадхисаттвы. Самаясаттва составляет внешнюю форму созерцания; в её сердце пребывает Джнянасаттва, а в сердце Джнянасаттвы утверждается слог <span class="font-bold italic text-red-700">HŪṀ</span> как Самадхисаттва. Эта трёхуровневая структура завершает Великую йогу и непосредственно подготавливает переход к следующему разделу — Великому свершению (<em>mahāsādhana</em>). Под «шестью знаками» (<em>ṣaḍcihna</em>), вероятнее всего, понимаются шесть традиционных украшений мужского божества, но возможны и шесть атрибутов. Точная расшифровка в рамках данного текста не встретилась. <a href="#ref-78" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлокам 94–101 -->
        <p class="my-2" id="citation-79"><sup>79</sup> <strong>Переход к Великому свершению и карма-мудра:</strong>
        шлоки 94–101 открывают раздел Великого свершения (<em>mahāsādhana</em>). Здесь речь идёт о карма-мудре (<em>karmamudrā</em>), то есть о реальной супруге, а не о созерцаемой джняна-мудре (<em>jñānamudrā</em>). На это указывает прямое предписание «обрести девушку» (<em>prāpya kanyām</em>). Выражение <em>rajakasya mahātmanaḥ</em> буквально означает «дочь великодушного прачки» и последовательно сохраняется санскритской рукописной традицией. После этого мандала, ранее построенная на теле самого практикующего, последовательно переносится на тело карма-мудры посредством наложения бидж и размещения женских божеств на соответствующих частях её тела.</p>
