        <!-- Блок примечаний к шлокам 102–106 -->
        <p class="my-2" id="citation-80"><sup>80</sup> <strong>Великое свершение и практика карма-мудры:</strong>
        после завершения построения мандалы на теле практикующего и его карма-мудры оба тела становятся опорой для дальнейшей визуализации. Мужской тайный орган созерцается как пятиконечный ваджр, возникший из слога <span class="font-bold italic text-red-700">HŪṀ</span>, с белым слогом <span class="font-bold italic text-red-700">OṀ</span> на его центральной оси, а женский — как восьмилепестковый лотос, возникший из слога <span class="font-bold italic text-red-700">ĀḤ</span>. Так обычное восприятие тел заменяется созерцанием символов метода (<em>upāya</em>) и мудрости (<em>prajñā</em>). Практика сопровождается мантрой Ваджра Страсти (<em>anurāgaṇavajra</em>). Во время соединения йогин удерживает «гордость Ваджрадхары» (<em>vajradharasya garva</em>) и сопровождает движения внутренним звучанием слога <span class="font-bold italic text-red-700">HŪṀ</span>. В момент возникновения бодхичитты (<em>svabodhicittodaya</em>) предписывается произнести слог <span class="font-bold italic text-red-700">PHAṬ</span>. Этот момент нередко связывается с практикой удержания бодхичитты и направлением жизненных ветров в центральный канал, однако сами шлоки ограничиваются лишь предписанием произнести биджу <span class="font-bold italic text-red-700">PHAṬ</span>. Заключительная шлока описывает подношение бодхичитты Буддам десяти направлений (<em>bodhicittena pūjayet daśadikṣu sthitān buddhān</em>) и завершается мантрой Ваджра Подношения (<em>pūjāvajra</em>). Выражение <em>visargānte</em> буквально означает «по завершении истечения». В различных комментариях этот термин получает разные объяснения: от указания на физиологический момент ритуала до его внутреннего созерцательного истолкования. Сам текст не конкретизирует это значение, ограничиваясь предписанием совершить подношение и произнести заключительную мантру.
        <a href="#ref-80" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлокам 107–115 -->
        <p class="my-2" id="citation-81"><sup>81</sup> <strong>Развёртывание деятельности Ваджра Гнева:</strong> шлоки 107–115 описывают следующий этап практики после Великого свершения (<em>mahāsādhana</em>): то, что прежде было осуществлено как внутреннее созерцание, теперь разворачивается как деятельность. <em>Buddharddhi</em> («чудесные деяния Будды») обозначает проявление сверхобычных способностей (<em>ṛddhi</em>), широко известных уже по ранним буддийским сутрам. В тантрическом контексте речь идёт о деятельности Будды, направленной на благо существ. Для этого йогин порождает себя в облике Ваджра Гнева (<em>dveṣavajra</em>) — Владыки семейства Акшобхьи — со всеми его иконографическими признаками. Подобные образы служат опорой для созерцания недвойственного ума. Затем этот образ исходит из сердца, обходит десять направлений, совершает деяния Будды, очищает существ и утверждает их в состоянии Ваджра Гнева, после чего возвращается обратно, воспроизводя тот же круг деятельности. Возвращение образа в сердце и «преобразование прежнего облика» (<em>pūrvarūpaṃ parāvṛttya</em>) означает отказ от прежнего самоотождествления и утверждение нового способа созерцания себя. Заключительные шлоки изображают Ваджр Гнева в союзе с собственной мудрой. <a href="#ref-81" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлокам 116–122 -->
        <p class="my-2" id="citation-82"><sup>82</sup> <strong>Вайрочана и очищение неведения:</strong> Вайрочана открывает цикл четырёх Татхагат, которые поочерёдно исходят из сердца йогина, совершают деятельность Будды и возвращаются в соответствующий сектор мандалы. Здесь Вайрочана очищает существ, пребывающих во власти неведения (<em>moha</em>), после чего занимает восточное место мандалы. Тем самым внутреннее созерцание получает внешнее выражение как деятельность Будды; далее этот же цикл последовательно повторяется для остальных Татхагат. <a href="#ref-82" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-83"><sup>83</sup> <strong>Ратнакету (Ратнасамбхава) и очищение эго-гордыни:</strong> Вместо имени Ратнасамбхава здесь употреблено имя Ратнакету («Драгоценное знамя»), обозначающее его деятельное проявление. Подобно Вайрочане, Ратнакету исходит из сердца йогина, очищает существ и занимает своё место в мандале — южный сектор. Объектом очищения становится <em>ahaṅkāra</em> — эго-гордыня. В тантрической традиции этот термин имеет два уровня значения: в обычном состоянии он обозначает цепляние за мысленно построенное «я», тогда как в практике после очищения такое самоотождествление заменяется «божественной гордостью» (<em>devatāgarva</em>) — устойчивым созерцанием себя в облике божества. <a href="#ref-83" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлокам 123–126 -->
        <p class="my-2" id="citation-84"><sup>84</sup> <strong>Амитабха (Аролик) и очищение страсти:</strong>
        в шлоке 123 Амитабха назван своим тантрическим именем Аролик (<em>Ārolik</em>, тиб. <em>A ro lIk</em>), связанным с его мантрой (<em>ārolikmantra</em>). Это одно из традиционных имён Амитабхи, употребляемых в литературе Ануттара-йога-тантры. Далее текст показывает деятельность Татхагаты семейства Лотоса: Амитабха исходит из сердца йогина, очищает существ, охваченных страстью (<em>rāga</em>), после чего занимает западный сектор мандалы. Тем самым страсть включается в путь практики и преобразуется в Различающую мудрость (<em>pratyavekṣaṇājñāna</em>) семейства Лотоса. <a href="#ref-84" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлокам 127–131 -->
        <p class="my-2" id="citation-85"><sup>85</sup> <strong>Завершение цикла четырёх Татхагат и пять семейств: </strong>после описания Вайрочаны, Ратнакету и Амитабхи данный пассаж завершает цикл четырёх Татхагат плода, последним из которых является Амогхасиддхи. Все они проявляются по одной и той же последовательности: возникают из соответствующей коренной мантры (Вайрочана — <em>jinajigmantra</em>, Ратнакету — <em>ratnadhṛgmantra</em>, Амитабха — <em>ārolikmantra</em>, Амогхасиддхи — <em>prajñādhṛgmantra</em>), исходят из сердца йогина, совершают деятельность Будды, очищая определённое омрачение живых существ, после чего возвращаются и занимают своё место по сторонам света в мандале. В данном случае Амогхасиддхи очищает живых существ, пребывающих во власти зависти (<em>īrṣyā</em>) и её омрачений (<em>īrṣyādoṣa</em>), после чего утверждается в северном секторе мандалы на скрещённом ваджре (<em>viśvavajra</em>). Заключительные строки (130–131) подводят итог всему циклу, перечисляя пять семейств — Гнева (<em>dveṣa</em>), Неведения (<em>moha</em>), Страсти (<em>rāga</em>), Драгоценности (<em>cintāmaṇi</em>) и Самаи (<em>samaya</em>). Они названы средствами, посредством которых достигаются как мирские цели (<em>kāma</em>), так и освобождение (<em>mokṣa</em>) (<em>kāmamokṣaprasādhakāḥ</em>), то есть один и тот же тантрический путь ведёт как к относительным, так и к окончательным результатам. <a href="#ref-85" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлокам 131–135 -->
        <p class="my-2" id="citation-86"><sup>86</sup> <strong>Цикл Богинь-Праджней и очищение омрачений:</strong>
        начиная с этого места открывается новый цикл — проявление четырёх Богинь-Праджней, занимающих угловые секторы мандалы и соответствующих четырём Татхагатам. Лочана рождается из мантры Мохарати (<em>moharatyādibhir jātām</em>), связанной с <em>moha</em> — неведением. Однако речь идёт не о продолжении неведения, а о его преобразовании в путь. Подобно тому как <em>ahaṅkāra</em> после очищения переосмысляется как «божественная гордость» (<em>devatāgarva</em>), здесь и <em>moha</em> не устраняется как нечто существующее само по себе, оно становится основой для проявления Лочаны — Богини, исполненной безмятежного покоя (<em>śāntarasopetā</em>) и увенчанной образом Вайрочаны. Далее Лочана проходит тот же цикл деятельности, который ранее был установлен для Татхагат: она исходит из сердца (<em>hṛdayāt tu vinirgatya</em>), обозревает десять направлений, движимая великим состраданием приносит миру покой (<em>grahavyādhyāture loke śāntiṃ kṛtvā</em>), а затем возвращается и занимает своё место в мандале. Тем самым схема «созерцание — деятельность — возвращение» последовательно применяется сначала к Татхагатам, а затем к Богиням-Праджням. <a href="#ref-86" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлоке 138 -->
        <p class="my-2" id="citation-87"><sup>87</sup> <strong>Мамаки и защита от великих препятствий:</strong>
        Мамаки рождается из мантры Двешарати (<em>Dveṣaratī</em>, «Восторг гнева») и увенчана образом Акшобхьи, что указывает на её принадлежность к Ваджрному семейству. Мамаки связана с <em>dveṣa</em> (гневом), который преображается в Зерцалоподобную мудрость Акшобхьи. Выйдя из сердца практикующего, Она дарует защиту существам, страдающим от великих препятствий (<em>mahāvighna</em>), после чего возвращается и занимает своё место в юго-западном секторе мандалы (<em>nairṛtyām</em>), продолжая установленный ранее цикл деятельности Богинь-Праджней. <a href="#ref-87" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлокам 139–142 -->
        <p class="my-2" id="citation-88"><sup>88</sup> <strong>Пандаравасини и преобразование страсти:</strong>
        шлоки 139–142 описывают проявление третьей Богини-Праджни — Пандаравасини, рождающейся из мантры Рагарати (<em>Rāgaratī</em>, «Восторг страсти», тиб. <em>rā ga ra ti</em>). Подобно тому как Лочана связана с <em>moha</em>, а Мамаки — с <em>dveṣa</em>, Пандаравасини связана с <em>rāga</em> (страстью и привязанностью), которые в практике стадии завершения преобразуются в Различающую мудрость семейства Амитабхи. Иконография Пандаравасини повторяет пластику её Будды-родителя Амитабхи: центральная пара рук раскрывает у сердца красный лотос Мудрости (<em>utpalaṃ hṛtpradeśasthaṃ... savyena bodhayet</em>), подчёркивая связь этого семейства с преобразованием страсти. Выйдя из сердца практикующего, Богиня приносит умиротворение миру, страдающему от вредоносных воздействий (<em>śāntiṃ kṛtvā mahāture</em>), после чего возвращается и занимает своё место в северо-западном углу мандалы (<em>vāyukoṇe</em>). <a href="#ref-88" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлокам 143–146 -->
        <p class="my-2" id="citation-89"><sup>89</sup> <strong>Завершение цикла Богинь-Праджней и переход ко второму ярусу мандалы:</strong> шлоки 143–146 завершают цикл четырёх Богинь-Праджней мандалы плода проявлением Тары, рождающейся из мантры Ваджрарати (<em>Vajraratī</em>, «Ваджрный восторг»), связывающей её с северным семейством Амогхасиддхи. Её тайное имя не связано непосредственно с клешей и указывает на завершённое состояние практики, в котором преобразование полностью осуществлено и утверждено в природе Ваджры. Подобно другим Богиням-Праджням, Тара исходит из сердца практикующего, совершает свою деятельность и возвращается на предназначенное ей место в мандале. Формула «подчинив своей просветлённой власти всех живых существ» (<em>sarvasattvān vaśīkṛtya</em>) выражает всеохватывающую активность её сострадания; указание на <em>śivasthāna</em> («обитель Шивы») соответствует северо-восточному углу мандалы, традиционно связанному в индийской космографии с Ишаной. Можно отметить отличающийся от Главы семейства порядок атрибутов Богини, что выделяет её из общего ряда. Воцарением Тары завершается цикл четырёх Богинь-Праджней, после чего Нагарджуна переходит ко второму ярусу мандалы (<em>dvitīye tu puṭe</em>), начиная описание Богинь объектов чувств. <a href="#ref-89" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлокам 147–153 -->
        <p class="my-2" id="citation-90"><sup>90</sup> <strong>Второй ярус мандалы — Богини объектов чувств:</strong>
        после описания четырёх Богинь-Праджней Нагарджуна переходит ко второму кругу мандалы (<em>dvitīya-puṭa</em>), где размещаются Богини объектов чувств: Рупаваджра, Шабдаваджра, Гандхаваджра и Расаваджра. Каждая из них помещается в том же угловом секторе, что и соответствующая Богиня-Праджня, сохраняя связь со своим Буддой-покровителем и повторяя её основные иконографические признаки. Расаваджра при этом увенчана образом Дундубхисвары (<em>Dundubhiśvara</em>) — одного из тантрических имён Амогхасиддхи («Владыка барабана»), употреблённого здесь вместо его более распространённого имени. В отличие от предыдущего цикла, связанного с преобразованием первоэлементов, здесь внимание переносится на объекты чувственного восприятия — форму, звук, запах и вкус. Тем самым процесс очищения распространяется не только на самого практикующего, но и на воспринимаемый им мир. Спаршаваджра, завершающая этот ряд, соответствует осязанию и пребывает в центре мандалы, в объятии с Ваджрасаттвой, что указывает на нераздельность всех чувственных объектов в просветлённом сознании. <a href="#ref-90" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлокам 154–159 -->
        <p class="my-2" id="citation-91"><sup>91</sup> <strong>Третий ярус мандалы — восемь великих Бодхисаттв:</strong>
        шлоки 154–159 описывают третий круг мандалы плода, где восемь великих Бодхисаттв располагаются попарно у четырёх ворот дворца, на галереях (<em>paṭṭikā</em>). Предыдущий цикл был посвящён Богиням объектов чувств, здесь же внимание переносится на аятаны (<em>āyatana</em>) — внутренние и внешние основы чувственного восприятия. В буддийской традиции под двенадцатью аятанами понимаются шесть внутренних основ (глаз, ухо, нос, язык, тело и ум) и шесть соответствующих им объектов восприятия (видимое, звук, запах, вкус, осязаемое и дхармы). Их очищение означает преображение всей сферы чувственного опыта практикующего. Все восемь Бодхисаттв сохраняют иконографическое сходство со своими Владыками-Татхагатами: они повторяют их цвет, количество рук и основные атрибуты (<em>svasvādhipatibhiḥ samāḥ</em>). Единственным специально отмеченным отличием является Майтрея, держащий в правой руке цветок нагапушпа (<em>nāgapuṣpa</em>). Завершается цикл тем же ритуальным действием, что и в предыдущих разделах: Бодхисаттвы очищают аятаны живых существ, даруют им божественное зрение и другие сверхобычные способности (<em>divyanetrādidāyakāḥ</em>), после чего возвращаются на свои места у четырёх врат мандалы. Тем самым очищение, последовательно охватившее первоэлементы, затем объекты чувственного восприятия, распространяется и на основы чувственного опыта. <a href="#ref-91" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлокам 160–170 -->
        <p class="my-2" id="citation-92"><sup>92</sup> <strong>Ямантака — первый из десяти Кродхараджей:</strong>
        Ямантака открывает цикл десяти Кродхараджей — гневных Владык, охраняющих внешний периметр мандалы. В отличие от предыдущих кругов божеств, их деятельность направлена на устранение всего, что препятствует осуществлению пути. Поэтому текст подчёркивает их устрашающий облик, гневные атрибуты и способность повергать в ужас препятствующих (<em>vighna</em>). То есть гнев Кродхараджей представляет собой просветлённую деятельность, направленную на пресечение всего, что препятствует Пробуждению. <a href="#ref-92" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-93"><sup>93</sup> <strong>Апараджита («Непобедимый») и деятельность сокрушения препятствий:</strong> имя Апараджита описывает просветлённую деятельность как непреодолимую, сокрушающую любые препятствия. <a href="#ref-93" class="text-blue-500 hover:underline">↩</a></p>
       <div class="not-prose flex justify-center my-4">
            <figure class="rounded-lg shadow-md max-w-[600px] text-center">
                <img src="\images\dharma\tantra\guhyasamaja\Aparajit_yab_yum.webp"
                    alt="Иная форма Апараджита"
                    class="rounded-lg w-full h-auto mx-auto object-contain transition-all duration-300 ease-in-out">
                <figcaption class="mt-2 mb-4 px-4 italic text-gray-800 text-sm">
                    Иная форма Апараджита
                </figcaption>
            </figure>
        </div>
        <p class="my-2" id="citation-94"><sup>94</sup> <strong>Хаягрива и усмирение труднопреодолимых сил:</strong>
        Хаягрива относится к семейству Амитабхи. Его имя традиционно связывается с мощной силой, усмиряющей наиболее трудноукротимые препятствия. В шлоке 169 эпитет <em>sagarva</em> относится к способу удержания топора (<em>paraśu</em>): оружие изображается горделиво воздетым, выражая непреклонную силу просветлённой деятельности. В следующей шлоке тибетский перевод уточняет санскритское <em>vighna</em> («препятствующие»), заменяя его на <em>klu</em> — нагов, что отражает одну из традиций толкования деятельности Хаягривы как усмирителя нагов и вредоносных сил. <a href="#ref-94" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлокам 171–174 -->
        <p class="my-2" id="citation-95"><sup>95</sup> <strong>Амритакундали — завершение четырёх главных Кродхараджей:</strong> Амритакундали завершает четвёрку главных Кродхараджей, охраняющих четыре стороны внешнего круга мандалы. Его увенчание образом Дундубхисвары указывает на принадлежность к семейству Амогхасиддхи, воплощающему беспрепятственное осуществление просветлённой деятельности. В соответствии с этим Амритакундали устраняет препятствия (<em>vighna</em>), запечатывая северные врата мандалы. Обозначение его местопребывания как «стороны Куберы» (<em>kauberyāṃ diśi</em>) соответствует внутренней пространственной системе текста, где север последовательно закреплён за Куберой. <a href="#ref-95" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлокам 175–178 -->
        <p class="my-2" id="citation-96">
        <sup>96</sup> <strong>Ачала — начало второй четвёрки Кродхараджей:</strong>
        Ачала («Неколебимый») открывает вторую четвёрку Кродхараджей, размещённых в промежуточных направлениях мандалы. Его имя указывает на непоколебимость просветлённой деятельности перед любыми препятствиями. В отличие от предыдущих четырёх стражей, охраняющих главные стороны света, Ачала занимает юго-восточный сектор — область Огня (<em>vahnisthāna</em>). Уничтожение препятствий, лихорадок и других недугов (<em>vighnān jvarādikān hatvā</em>) показывает, что гневная деятельность Кродхараджей направлена и на устранение внешних препятствий практике, и всего того, что препятствует её осуществлению на уровне тела и ума.
        <a href="#ref-96" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлокам 179–181 -->
        <p class="my-2" id="citation-97"><sup>97</sup> <strong>Таккираджа — страж юго-западного направления:</strong>
        Таккираджа запечатывает юго-западный угол внешнего охранительного круга мандалы, соответствующий направлению Ниррити (<em>nairṛtyā</em>). Его увенчание образом Ратнасамбхавы указывает на принадлежность к семейству Драгоценности. Особенностью его иконографии является Хумкара-мудра (<em>hūṃkāramudrā</em>): две центральные руки соединяются у сердца, удерживая ваджр и образуя жест, выражающий нераздельность Тела, Речи и Ума Будды. Тибетский перевод в шлоке 180 расходится с санскритом, заменяя упоминание «огромного чрева» (<em>bṛhatkukṣi</em>) описанием трёх глаз и клыков. В отличие от остальных стражей этого круга, Таккираджа стоит непосредственно на солнечном диске (<em>sūryastha</em>), без лотосового престола. <a href="#ref-97" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлокам 193–197 -->
        <p class="my-2" id="citation-98"><sup>98</sup> <strong>Завершение цикла десяти Кродхараджей и защита десяти направлений:</strong> шлоки 160–197 описывают полный круг десяти Кродхараджей — гневных Владык, охраняющих внешний периметр мандалы. Четверо из них запечатывают главные врата дворца, четверо располагаются в промежуточных направлениях, Ушнишачакравартин занимает верхнюю точку пространства (зенит), Сумбхараджа утверждается под поверхностью земли. Тем самым защитный контур охватывает все десять направлений пространства, полностью замыкая мандалу. Несмотря на различие имён, цветов и оружия, все Кродхараджи построены по единой иконографической схеме: они рождаются из соответствующих мантр, увенчаны образами своих Будд-покровителей, обладают тремя ликами, шестью руками и пребывают в позе пратьялидха на солнечном диске, а в большинстве случаев — также на лотосовом престоле. Их гневный облик выражает непреодолимую деятельность пробуждённой мудрости, устраняющей препятствия на пути созерцания. <a href="#ref-98" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлокам 198–203 -->
        <p class="my-2" id="citation-99"><sup>99</sup> <strong>Переход к тонкой йоге и растворение мандалы:</strong>
        шлоки 198–203 указывают переход от развёрнутой мандалы стадии порождения к тонкой йоге (<em>sūkṣmayoga</em>): множество божественных форм, составляющих мандалу, оставляется (<em>utsṛjya</em>), после чего внимание сосредоточивается на едином <em>jñānapada</em> — «состоянии мудрости». В шлоке 198 имеется расхождение между санскритом и тибетским переводом. Санскритское <em>utsṛjya</em> означает «оставив», «отпустив» и допускает в данном контексте понимание растворения мандалы. Тибетское <em>bskyed nas</em> означает «породив», «создав». Мы принимаем в переводе санскритское чтение, поскольку оно задаёт переход от завершённого развёртывания мандалы к <em>sūkṣmayoga</em>. Термин <em>jñānapada</em> здесь переводится как «состояние мудрости», однако такой перевод следует считать условным. В данном контексте речь идёт о взаимосвязанной работе праны и ума, поэтому <em>jñānapada</em> обозначает не столько отдельное пространственное место, сколько состояние созерцания, связанное с сосредоточением на определённом объекте и возникающее благодаря этому сосредоточению. Указание <em>nāsāgre</em> — «на кончике носа» — задаёт место установления созерцаемого объекта в данном варианте практики. При этом, согласно объяснениям Цзонкапы, локализация подобных объектов в практиках тонкой йоги может различаться и связываться также с областью сердца или пупка. Поэтому здесь следует сохранять конкретное указание санскритского текста, не возводя его в универсальное правило для всех вариантов практики. Распространение (<em>sphāraṇa</em>) допускается после достижения устойчивости (<em>sthira</em>) созерцаемого объекта; это является необходимым условием данной практики. Ещё одно требование касается особого способа начитывания (<em>japa</em>): <em>abhinnāṅga</em> подчёркивает сохранение целостности мантры и непрерывность сосредоточения. Формула <em>japoktaṃ paramārthataḥ</em> связывает это начитывание с высшим смыслом (<em>paramārtha</em>). <a href="#ref-99" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлокам 204–209 -->
        <p class="my-2" id="citation-100"><sup>100</sup> <strong>Четыре песни богинь и переход от Таковости к проявлению:</strong> четыре песни богинь имеют прямую параллель в XVII главе «Гухьясамаджа-тантры». Там этот эпизод появляется после раскрытия тайны Трёх Ваджров — Тела, Речи и Ума всех Татхагат — и связан с <em>samayacakra</em>, кругом самаи. После пребывания бодхисаттв в молчании Татхагаты пребывают в лонах женских божеств, связанных с Ваджрами Тела, Речи и Ума. Затем четыре богини последовательно обращаются к Владыке всех Татхагат.<br>Из XVII главы коренной тантры:<br>«После этого все бодхисаттвы пребывали в молчании. Затем Блаженные Татхагаты пребывали в лонах женских божеств, являющих собой Ваджр Тела, Речи и Ума всех Татхагат. Тогда Мамаки, возлюбленная Ума всех Татхагат, преисполненная радости, вознесла Владыке всех Татхагат, Великому Ваджродержцу, хвалу посредством высших словесных слогов почитания Ваджрной Любви и Наслаждения: "Ты — Ваджрный Ум, Владыка мира, Владыка сферы живых существ! Защити меня, о чарующий любовью, великими желанными благами! Возжелай меня, о Родитель, Высший Друг всех живых существ! Если желаешь, чтобы продолжалась жизнь, о Прекрасный Владыка!" Затем Буддхалочана, возлюбленная Тела всех Татхагат, преисполненная счастья, благорасположения и радости, вознесла Владыке всех Татхагат, Великому Ваджродержцу, хвалу посредством высших словесных слогов почитания всей Ваджрной Любви: "Ты — Ваджрное Тело, высшая чакра, любимая множеством существ, взирающий на благо Будд, высшую цель пробуждения и высшее благо! Возжелай меня страстью, согласно обету страсти! Если желаешь, чтобы продолжалась жизнь, о Прекрасный Владыка!" Затем Возлюбленная Локешвары [Пандаравасини], чей взор укоренён в Ваджрном Теле, вознесла Владыке всех Татхагат, Великому Ваджродержцу, хвалу посредством слогов обязательств чувственного наслаждения: "Ты — Ваджрная Речь, сострадательный ко благу всех существ, всегда устремлённый к совершению деяний ради блага мира! Возжелай меня, о Всеблагой, пребывающий в практике йогического союза! Если желаешь, чтобы продолжалась жизнь, о Прекрасный Владыка!" Затем Ваджрная Возлюбленная Тела, Речи, Ума и Самаи всех Татхагат [Тара] вознесла Владыке всех Татхагат, Великому Ваджродержцу, хвалу с этой радостью, счастьем и благорасположением всех Татхагат: "Ты — Ваджрное Тело, высший среди обетов, имеющий своей целью великое благо, украшение рода Совершенно Пробуждённых, равно сострадательный ко всем! Возжелай меня, сокровищницу достоинств, ставшую вместилищем множества драгоценностей! Если желаешь, чтобы продолжалась жизнь, о Прекрасный Владыка!"» Далее в XVII главе говорится, что Ваджрапани входит в самадхи <em>sarvakāmopabhogavajraśrī</em> и, действуя посредством <em>samayacakra</em>, пребывает в молчании. Затем всё пространство наполняется семенем самаи Тела, Речи и Ума всех Татхагат. Существа, соприкоснувшиеся с сиянием Трёх Ваджров, становятся Татхагатами, совершенными Буддами, обладающими знанием Трёх Ваджр. Эта параллель уточняет значение четырёх песен в Piṇḍīkṛta-sādhana. Богини появляются непосредственно после того, как мантрин, завершив Тонкую йогу, вновь вводит себя в Таковость (<em>tathatā</em>). В коренной тантре тот же мотив помещён между пребыванием Татхагат в женских божествах и последующим наполнением пространства семенем Трёх Ваджров. Поэтому песни следует понимать как побуждение к проявлению, соединяющее пребывание в Таковости с последующим проявлением Трёх Ваджров. Четыре богини связаны с четырьмя элементами мандалы. Их связь с Тремя Ваджрами представляет другую систему соотнесения: Тело, Речь и Ум. Эти две структуры здесь взаимодействуют: четверичность элементов получает выражение через четыре женских божества, тогда как их отношение к Владыке определяется системой Трёх Ваджров. Повторяющийся призыв <em>kāmāhi māṃ / kāmayasva</em> — «возжелай меня» — следует понимать в пределах <em>samayacakra</em>. После песен Татхагаты удивляются тому, что посредством слов, связанных с <em>rāga</em>, можно следовать к пробуждению. Ваджрапани отвечает указанием на равностность всех дхарм: среди них не устанавливаются ни <em>rāga</em>, ни <em>dveṣa</em>, ни <em>moha</em>, как не устанавливаются скандхи, элементы и основания чувственного опыта. Поэтому <em>rāga</em> в данном эпизоде включён в практику через самаю и равностность дхарм. В шлоке 207 в издании Сейера читается <em>priyāgracakra</em>, тогда как в параллели XVII главы коренной тантры сохраняется чтение <em>priyāṅkacakra</em>. <em>Aṅka</em> означает «колени», «лоно», «объятия» и может обозначать место пребывания возлюбленного. Поэтому <em>priyāṅkacakra</em> сохраняет более конкретный образ связи чакры с возлюбленной и хорошо соответствует контексту женского божества и <em>samayacakra</em>. В переводе сохраняем чтение Сейера <em>priyāgracakra</em>, но <em>priyāṅkacakra</em> имеем в виду как вариант коренной тантры. Шлоки 204–209 продолжают ту же последовательность, которая в XVII главе «Гухьясамаджи» развёрнута подробнее: вхождение в Таковость → песни четырёх богинь → <em>samayacakra</em> → проявление Трёх Ваджров. Четыре богини обеспечивают здесь переход от растворения к проявлению, причём их четверичность связана с элементами мандалы, а их отношение к Владыке — с Тремя Ваджрами. В садхане, в отличие от развёрнутого повествования тантры, этот эпизод максимально сжат и служит именно переходом от растворения к новому проявлению. <a href="#ref-100" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлокам 210–215 -->
        <p class="my-2" id="citation-101"><sup>101</sup> <strong>Пять гимнов Татхагат и раскрытие Трёх Ваджров:</strong> пять строф этого гимна имеют прямую параллель в XVII главе «Гухьясамаджи». В коренной тантре они образуют единый <em>stotrarāja</em> — «царь гимнов», посредством которого Татхагаты обращаются к Владыке Трёх Ваджров. Данный эпизод продолжает последовательность, начатую четырьмя песнями богинь: после их обращения Владыка пробуждается к проявлению и Татхагаты прославляют его через последовательное раскрытие качеств пяти аспектов Пробуждения. Однако надо отметить, что такой порядок предлагается именно Нагарджуной, в коренной тантре эти гимны расположены в начале главы, а песни богинь почти в завершении. В строфах 211–215 каждый гимн связывает определённый аспект Владыки с системой Ваджр: Акшобхья — с Великой Мудростью и Ваджрной сферой, Вайрочана — с чистотой, Ваджрным Покоем и изначальным Ясным Светом дхарм, Ратнасамбхава — с чистотой собственной природы и Ваджрным пространством, Амогхасиддхи — с исполнением желаний и чистой собственной природой. В строфе 214 называется <em>rāgapāramitā</em> — «совершенство страсти». Это продолжает линию предыдущих строф, в которых язык желания (<em>kāma</em>, <em>rāga</em>) включён в систему самаи и служит средством выражения пути к пробуждению. Между Piṇḍīkṛta-sādhana и XVII главой «Гухьясамаджи» имеются текстологические расхождения. В шлоке 211 садхана имеет <em>bhāṣa guhyaṃ</em>, тогда как параллельная строфа XVII главы читает <em>ghoṣavajra</em>. В шлоке 213 садхана также имеет <em>bhāṣa guhyaṃ</em>, тогда как коренная тантра — <em>kāyavajra</em>. Перевод «Тайная Речь» в этих двух местах следует чтению основного текста садханы. В XVII главе после пяти строф следует шестая строфа, где говорится, что тот, кто восхваляет Ваджр этими умиротворёнными, побуждёнными всеми Буддами словами гимна, становится подобен Ваджру. Затем Ваджрадхара изрекает чистое слово тайны — Ваджрную Речь, после чего раскрывается <em>dharmadhātu</em> как великое тайное слово, изначально светоносное и чистое, подобное пространству. Таким образом, пять строф выполняют функцию перехода от восхваления Владыки к раскрытию природы Ваджрной Речи и Дхармадхату. В Piṇḍīkṛta-sādhana гимн следует непосредственно после песен четырёх богинь и возвращения мантрина в Таковость (<em>tathatā</em>). Последовательность получает следующую структуру: вход в Таковость → побуждение четырьмя богинями → пробуждение Владыки → восхваление Татхагатами → раскрытие Трёх Ваджров. Поэтому гимн следует понимать как продолжение процесса проявления, начатого в шлоках 204–209. <a href="#ref-101" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлокам 216–220 -->
        <p class="my-2" id="citation-102"><sup>102</sup> <strong>Завершение мандалы и практика после самадхи: </strong>шлока 216 завершает последовательность, в которой мандала, прежде созерцаемая как круг божеств, вновь вводится в <em>svakāyacakra</em> — «круг собственного тела», то есть внешне развёрнутый круг мандалы связывается с телом самого практикующего. Результат этого введения обозначен формулой <em>mahāsukhas tiṣṭhati nātha ekaḥ</em> — «Владыка один пребывает в Великом Блаженстве». Шлока 217 переводит это состояние в практику после выхода из самадхи (<em>vyutthāya</em>). Йогин продолжает действовать (<em>vicared</em>) с сохранением достигнутого понимания: мир мыслится имеющим своей сердцевиной / сущностью <span class="font-bold italic text-red-700">HŪṀ</span> и видится как проявление Ваджрасаттвы. Такое созерцательное понимание не ограничивается временем самадхи и становится основанием дальнейшего поведения (<em>yathāvad</em>). В связи с иссыханием тела Нагарджуна предписывает практику <em>pañcāmṛtanipātanam</em> — «нисхождение пяти нектаров». Для этого на макушке следует представить мандалу в пространстве величиной в одну пядь (<em>vitastimātram</em>), а также слог <span class="font-bold italic text-red-700">OṀ</span>. <em>Vitasti</em> — традиционная мера длины, обычно передаваемая как «пядь»; её точное физическое измерение в данной шлоке не уточняется. Завершается последовательность указанием на мгновенное обретение сияния и устойчивого благополучия тела, речи и ума (<em>kāyavākcittasausthitya</em>). <a href="#ref-102" class="text-blue-500 hover:underline">↩</a></p>

        <!-- Блок примечаний к шлокам 221–229 -->
        <p class="my-2" id="citation-103"><sup>103</sup> <strong>Очищение пищи как внутреннее огненное подношение:</strong> этот фрагмент описывает практику очищения пищи (<em>āhāraśodhanā</em>) и раскрывает её как внутреннее огненное подношение (<em>ādhyātmika-homa</em>). Обычное принятие пищи здесь включается в последовательность созерцательных действий, в которой пища подвергается очищению, распознаванию и воспламенению, после чего вводится в тело практикующего. Поэтому формула шлоки 222 — <em>saṃśodhya ... bodhayet ... jvālayet</em> — имеет особое значение для понимания всей процедуры: очищение, «познание» и воспламенение образуют последовательность ритуального обращения с пищей. Использованная в тексте формула «очистив, познав и зажгя» точно сохраняет эту трёхчастную последовательность. Важную параллель даёт ритуальный текст «Сокшод», где тот же ряд действий выражен непосредственно: после помещения пищи в капалу и воздействия трёх слогов она расплавляется и вскипает, а затем говорится: «Очистив, познав и зажгя — Э МА ХО, / Полнота желанного / Стала морем пламенным!» Эта параллель показывает, что <em>āhāraśodhanā</em> представляет собой последовательность ритуально-созерцательных действий над пищей, совершаемых посредством слогов, ветра, огня и воды. Поэтому описанные здесь процессы следует понимать в рамках ритуальной визуализации и соответствующей ей практики, не приписывая тексту буквальное физическое изменение обычной пищи. Шлоки 223–224 подробно устанавливают созерцательные опоры для этой процедуры. В горле (<em>kaṇṭha</em>) представляется раковина (<em>śaṅkha</em>), внутри неё — восьмилепестковый лотос, возникший из <span class="font-bold italic text-red-700">HRĪḤ</span>, а в его сердцевине — <span class="font-bold italic text-red-700">HŪṀ</span>. Из <span class="font-bold italic text-red-700">HŪṀ</span> возникает великий пятиконечный ваджр (<em>mahāvajra</em>), на конце центральной спицы которого помещается <span class="font-bold italic text-red-700">OṀ</span>, обозначенный как средство очищения горла (<em>kaṇṭhaśodhanam</em>). Таким образом, перед непосредственным описанием внутреннего огненного подношения текст устанавливает последовательность образов, связанных с очищением горлового центра. Шлока 225 называет совершаемое действие внутренним огненным подношением (<em>homam ādhyātmikaṃ</em>). Созерцание звука грома (<em>meghanāda</em>) в сердце и распространение трёхпламенного огня (<em>triśikhāgni</em>) задают основу этого действия. В ритуале тот же образ раскрывается через ветер, раздувающий пламя в троеголовом очаге. Поэтому <em>triśikhā</em> здесь мы передаём как «трёхпламенный», сохраняя связь с уже установленным ритуальным образом. В шлоке 226 имеется существенное расхождение между санскритом и тибетским переводом. Санскрит читает <em>yatra sañcarate haviḥ</em> — «где движется жертвенное приношение», тогда как тибетский текст передаёт соответствующее место через <em>me</em> — «огонь». В основном переводе сохраняется санскритское чтение <em>haviḥ</em>. Оно хорошо вписывается в непосредственный контекст внутреннего подношения: далее пища и питьё вводятся в эту же последовательность как <em>aśana</em>, а в ритуале жертвенные яства расплавляются и превращаются в нектар в капале. В шлоках 227–228 описывается дальнейшее движение пищи внутри этой последовательности. Пища и питьё, соотнесённые с <em>vāruṇa</em>, вводятся через лотос рта в лотос сердца, после чего созерцание переносится к лотосу пупка. Здесь интересен термин <em>saṃpuṭīkaraṇayoga</em> — «йога соединения», который обозначает технический способ продолжения практики, однако сама шлока не раскрывает его подробнее. Поэтому конкретное содержание этого соединения оставляем открытым. <em>bhasmāntaṃ</em> — «завершающееся пеплом» — сохраняет огненную логику всего эпизода: жертвенное приношение проходит последовательность очищения, приготовления и внутреннего преобразования. Заключительная шлока связывает эту практику с её результатом: отсутствием старости, болезни, смерти, отравления и преждевременной смерти. Формула <em>sarvopadravanāśanam</em> — «уничтожение всех бедствий» — завершает описание <em>āhāraśodhanā</em>, связывая её с поддержанием благоприятного состояния практикующего. Тем самым этот отрывок продолжает тему шлок 218–220, где уже говорилось об услаждении тела, речи и ума (<em>kāyavākcittaprīṇanam</em>) и об обретении их устойчивого состояния (<em>kāyavākcittasausthitya</em>) через созерцание пятицветного нисходящего нектара. Очищение пищи включено в ту же систему практики, где питание, внутреннее огненное подношение и работа со слогами и элементами подчинены единой созерцательной последовательности. <a href="#ref-103" class="text-blue-500 hover:underline">↩</a></p>










