    <h2 class="text-center text-sky-900 font-bold text-xl my-4">Санскрит</h2>
    <hr class="my-8 border-t-4 border-gray-500">
    <!-- Блок санскрита -->
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <!-- Общие стили -->
        <style>
            .citation-block details > summary { list-style: none; cursor: pointer; }
            .citation-block details > summary::-webkit-details-marker { display: none; }
