        <details class="rounded-xl border border-sky-200/50 overflow-hidden">
                <summary class="flex items-center justify-between px-4 py-2.5 bg-sky-100/60 hover:bg-sky-100 transition-colors">
                    <span class="flex items-center gap-2 text-lg font-semibold text-sky-900">
                        <span class="text-sky-600">॥</span> Санскрит
                    </span>
                    <span class="flex items-center gap-2">
                        <span class="icon-closed text-sky-600 text-lg font-bold">+</span>
                        <span class="icon-open text-sky-600 text-lg font-bold">−</span>
                        <span class="text-closed text-sm text-sky-600">развернуть</span>
                        <span class="text-open text-sm text-sky-600">свернуть</span>
                    </span>
                </summary>
                <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>1. trailokyācāramuktaṁ gaganasamagataṁ sarvabhāvasvabhāvaṁ śuddhaṁ |</li>
            <li>śāntaṁ viviktaṁ paramaśivamayaṁ yoginām eva gamyam ||</li>
            <li>durbodhaṁ durvicāraṁ svaparahitatamaṁ vyāpinaṁ nirnimittaṁ |</li>
            <li>vande kāyaṁ jinānāṁ sukhamasamasamaṁ nirvikalpaikamūrtim || 1 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>2. śrīmatsamājatantrasya ṣaṭkoṭyarthāvabodhata |</li>
            <li>piṇḍīkramam ahaṁ vakṣye sarvasattvahitodayam || 2 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>3. vikalpavāsanādoṣān jagattrayavimohakān |</li>
            <li>samabhivīkṣya tān dhīmān yogatantreṇa śodhayet || 3 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>4. pañca kāmān parityajya tapobhir na ca pīḍayet |</li>
            <li>sukhena dhārayed bodhiṃ yogatantrānusāratoḥ || 4 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>5. teneha saṃvarastho 'sau abhedyaḥ sarvadā vratī |</li>
            <li>kāyavākcittavajrasya sādhanaṃ tu samārabhet || 5 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>6. mahāraṇyapradeśeṣu phalapuṣpādyalaṃkṛte |</li>
            <li>parvate vijane sādhyā sarvasiddhisamuccaye || 6 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>7. mṛdvāsanasamāsīnaḥ sattvaparyaṅkasaṃsthitaḥ |</li>
            <li>dveṣavajrasamādhisthaḥ sthānarakṣāṃ ca cintayet || 7 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>8. daśakrodhān samutsṛjya jvālābhāsurabhīṣaṇān |</li>
            <li>hūṃkārodbhūtabhānusthān pratyālīḍhapade sthitān || 8 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>9. daśadigmaṇḍalāgre tu sañcintyaivaṃ yathākramam |</li>
            <li>sarvavidhnavināśārthaṃ sumbhamājñāya kīlayet || 9 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>oṃ sumbha nisumbha hūṃ gṛhṇa gṛhṇa hūṃ gṛhṇāpaya gṛhṇāpaya hūṃ ānaya ho bhagavan vidyārāja hūṃ phaṭ ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>10. anena krodharūpeṇākṛṣyaivaṃ vināyakān |</li>
            <li>kīlayed vidhivat sarvān prayogeṇa tu buddhimān || 10 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>11. vajrāmṛtamahārājaṃ vajrakīlaṃ vibhāvayet |</li>
            <li>nīlotpaladalaśyāmaṃ jvālāmālākulaprabham || 11 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>12. nābhideśād adhobhāgaṃ śūlākāraṃ vibhāvayet |</li>
            <li>ūrdhvaṃ krodhākṛtiṃ caiva trimukhaṃ ṣaḍbhujaṃ tathā || 12 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>13. adho vighnagaṇān vīkṣya tan mantraṃ samudāharan |</li>
            <li>nikhaned vajrakīlaṃ tu vighnadeheṣu niścalam || 13 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>oṃ gha gha ghātaya ghātaya sarvaduṣṭān phaṭ phaṭ |<br>
            kīlaya kīlaya sarvapāpān phaṭ phaṭ hūṃ hūṃ hūṃ |<br>
            vajrakīla vajradhara ājñāpayati sarvvavighnānāṃ kāyavākcittavajraṃ kīlaya hūṃ hūṃ hūṃ phaṭ ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>14. vajramudgarahastaṃ ca sumbharājaṃ vibhāvayet || 14 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>15. vajravahniṃ samantāc ca vispharantaṃ vicintya vai |</li>
            <li>duṣṭān pralapitāṃś cinted dahyamānān itastataḥ || 15 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>16. daśadik kīlayitvā tvadhordhvam adhiṣṭhya ca |</li>
            <li>bhāvayet paramārthena niḥsvabhāvabhavatrayam || 16 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>17. abhāve bhāvanābhāvo bhāvanā naiva bhāvanā |</li>
            <li>iti bhāvo na bhāvaḥ syād bhāvanā nopalabhyate || 17 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>18. anayā gāthayā śūnyaṃ dhyātvā sthiracarātmaka |</li>
            <li>anena vidhiyogena jñānabhūmir adhiṣṭhyate || 18 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>19. ākāśadhātumadhyasthaṃ bhāvayed vāyumaṇḍalam |</li>
            <li>dvihūṃyāṃbījaniṣpannaṃ vajradvayasamāyutam || 19 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>20. agnimaṇḍalakaṃ cāpi tasyopari vibhāvayet |</li>
            <li>dvihūṃraṃbījaniṣpannaṃ vajradvayasamāṅkitam || 20 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>21. vārimaṇḍalakaṃ cāpi tasyopari vibhāvayet |</li>
            <li>dvihūṃvaṃbījaniṣpannaṃ vajradvayasamāyutam || 21 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>22. pṛthivīmaṇḍalakaṃ cāpi tasyopari vibhāvayet |</li>
            <li>dvihūṃlaṃbījaniṣpannaṃ vajradvayasamanvitam || 22 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>23. caturmaṇḍalasaṃhāre vajrabhūbhāgamaṇḍalam  |</li>
            <li>tatra bhrūṃkāraniṣpannaṃ kūṭāgāraṃ vibhāvayet|| 23 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>24. caturaśraṃ caturdvāraṃ catustoraṇaśobhitam |</li>
            <li>catuḥsūtrasamāyuktaṃ aṣṭastambhopaśobhitam || 24 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>25. hārārdhahāraracitaṃ maṇivajrārdhacandrakam |</li>
            <li>khacitaṃ vajraratnais tu dvāraniryūhasandhiṣu || 25 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>26. kumbhastambhamahāvajraṃ kramaśīrṣastu pakṣiṇī |</li>
            <li>ghaṇṭāpatākasaṃśobhaṃ cāmarādivibhūṣitam || 26 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>27. madhyamaṇḍalake dhyāyād ātmānaṃ mudrayā yutam |</li>
            <li>trimukhaṃ ṣaḍbhujākāram indranīlasamaprabham  || 27 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>28. śrīvairocanaratnau cāmitābhaś ca karmarāṭ |</li>
            <li>pūrvādidikṣu sañcintyās trimukhāḥ ṣaḍbhujāḥ sadā || 28 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>29. moharatyādikā devyas trimukhāḥ ṣaḍbhujās tathā |</li>
            <li>āgneyīṃ diśam ārabhya sanniveśyā yathākramam || 29 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>30. rūpavajrādikās tadvad bāhyakoṇacatuṣkaye |</li>
            <li>sthitā eva sparśavajrā tu vajrasattvasamāyutā || 30 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>31. paṭṭikāyāṃ nyaset pūrve maitreyaṃ kṣitigarbhakam |</li>
            <li>vajrapāṇiṃ khagarbhaṃ ca nyased dakṣiṇato vratī || 31 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>32. lokeśaṃ mañjughoṣaṃ ca paścimāyāṃ nyaset punaḥ |</li>
            <li>sarvanīvaraṇaviṣkambhinaṃ samantabhadram uttare || 32 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>33. yamāntakaṃ ca prāgdvāre dakṣiṇe tv aparājitam |</li>
            <li>paścime tu hayagrīvam uttare 'mṛtakuṇḍalim || 33 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>34. acalaṣ ṭakkirājaś ca nīladaṇḍo mahābalaḥ |</li>
            <li>pūrvādikoṇam ārabhya saṃcintyāḥ syur yathāyatham || 34 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>35. sumbharājamahākrodham adhastāt pravicintayet |</li>
            <li>uṣṇīṣacakravartinaṃ pravicintyas tathopari || 35 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>36. dhyātvaivam adhimuktyā vai māṇḍaleyān yathāvidhi |</li>
            <li>punaḥ saṃpuṭayogena svakāye tān praveśayet || 36 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>37. kāyacakragatān buddhān sañcintyaivaṃ yathāyatham |</li>
            <li>pāramārthikacakreṇa tathatāyāṃ praveśayet || 37 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>38. mārayet tathāgataṃ vyūhaṃ sutarāṃ siddhim āpnuyāt |</li>
            <li>asyārtho vajramālāyāṃ vistṛto visphuṭaṃ yathā || 38 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>39. rūpaskandhagatādarśo bhūdhātur nayanendriyam |</li>
            <li>rūpaṃ ca pañcamaṃ yāti krodhadvayam anuttamam || 39 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>40. vedanāskandhasamatā apdhātuḥ śravaṇendriyam |</li>
            <li>śabdaś ca pañcamaṃ yāti krodhadvayam anuttamam || 40 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>41. saṃjñā ca pratyavekṣā ca hutabhug nāsikendriyam |</li>
            <li>gandhaś ca pañcamaṃ yāti krodhadvayasamanvitam || 41 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>42. saṃskārāḥ kṛtyānuṣṭhānaṃ māruto rasanendriyam |</li>
            <li>rasaś ca pañcamaṃ yāti krodhadvayasamanvitam || 42 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>43. ūrdhvādhaḥ krodhasaṃyuktaṃ prakṛtyābhāsam eva ca |</li>
            <li>vijñānaskandham āyāti vijñānaṃ ca prabhāsvaram || 43 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>44. nirvāṇaṃ sarvaśūnyaṃ ca dharmakāyaś ca gadyate |</li>
            <li>dṛḍhīkaraṇahetutvān mantram etad udāharet || 44 ||</li>
            <li>oṃ śūnyatājñānavajrasvabhāvātmako 'ham ||  ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>45. paramārthamaṇḍalaṃ hy etan nirābhāsam alakṣaṇam |</li>
            <li>paramārthasatyanāmāpi sarvatathāgatālayaḥ || 45 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>46. prabhāsvarapraviṣṭasya vyutthānaṃ ca pradarśyate |</li>
            <li>mantramūrtiprayogeṇa devatālambanaṃ prati || 46 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>47. ākāśadhātumadhyasthaṃ bhāvayet sūryamaṇḍalam |</li>
            <li>tasyopari punaḥ mantrī candrabimbaṃ vibhāvayet || 47 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>48. tatra ca aṣṭadalaṃ padmaṃ raktavarṇaṃ vibhāvayet |</li>
            <li>padmopari mahāmantraṃ tryakṣaraṃ bhāvayet punaḥ || 48 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>49. mantraṃ padmaṃ tathā sūryaṃ praviṣṭaṃ candramaṇḍale |</li>
            <li>candramaṇḍalam āpūrṇaṃ bodhicittaṃ vibhāvayet || 49 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>50. sthāvaraṃ jaṅgamaṃ sarvaṃ tatraiva pravicintayet |</li>
            <li>dṛḍhīkaraṇahetutvān mantram etad udāharet || 50 ||</li>
            <li>oṃ dharmadhātusvabhāvātmako 'ham |</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>51. yogam evaṃ samālambyānuyogaṃ samācaret |</li>
            <li>punaś ca tryakṣaraṃ yogī candramadhye vicintayet || 51 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>52. tatas tryakṣarasambhūtaṃ sitakundendusannibham |</li>
            <li>ādināthaṃ vicintyātha atiyogaṃ samārabhet || 52 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>53. akṣobhyānupraveśena trimukhaṃ ṣaḍbhujojjvalam |</li>
            <li>indranīlaprabhaṃ dīptaṃ vajrasattvaṃ vibhāvayet || 53 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>54. vajraṃ cakraṃ tathā padmaṃ savyahasteṣu bhāvayet |</li>
            <li>ghaṇṭāṃ ratnaṃ tathā khaṅgaṃ vāmahasteṣu bhāvayet || 54 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>55. tato nyāsaṃ prakurvīta skandhādīnāṃ vibhāgavit |</li>
            <li>vairocanādisumbhāntaṃ bījanyāsena tattvataḥ || 55 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>56. vairocanīyabījaṃ tu oṃkāraṃ śuklavarṇakam |</li>
            <li>rūpaskandhasvabhāvena nyaset mūrdhni mantravit || 56 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>57. āḥkāram amitābhasya saṃjñāskandhasvabhāvakam |</li>
            <li>raktavarṇaṃ mukhe dhyātvā vāgaiśvaryam avāpnuyāt || 57 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>58. akṣobhyasya tu hūṃkāraṃ rājāvartaśukaprabham |</li>
            <li>vinyased hṛdaye mantrī vijñānaskandharūpataḥ || 58 ||</li>
        </ul>

        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>59. svākāraṃ ratnanāthasya vedanāskandharūpataḥ |</li>
            <li>pītavarṇaṃ nyasen nābhau vedanāśuddhihetukam || 59 ||</li>
        </ul>

        <!-- 60 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>60. pādadvaye tu hāḥkāraṃ saṃskāraskandhabhāvataḥ |</li>
            <li>haritābhaṃ nyasen mantrī karmanāthasya tattvataḥ || 60 ||</li>
        </ul>

        <!-- 61 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>61. moharatyādikair mantrī pṛthivyādīn praveśayet |</li>
            <li>kharatvaṃ dravatāuṣṇyam īraṇatvaṃ ca taiḥ kramāt || 61 ||</li>
        </ul>

        <!-- 62 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>62. thlīṃkāraṃ cakṣuṣi nyasya kṣitigarbhaṃ vibhāvayet |</li>
            <li>oṃkāraṃ karṇayor nyasya vajrapāṇiṃ vibhāvayet || 62 ||</li>
        </ul>

        <!-- 63 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>64. oṃkāraṃ vinyased ghrāṇe khagarbhaṃ tu vibhāvayet |</li>
            <li>oṃkāraṃ rasane dhyātvā lokeśaṃ ca vikalpayet || 64 ||</li>
        </ul>

        <!-- 64 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>64. hūṃkāraṃ manasi dhyātvā mañjughoṣaṃ prabhāvayet |</li>
            <li>oṃkāraṃ sarvakāye ca dhyātvā viṣkambhiṇaṃ smaret || 64 ||</li>
        </ul>

        <!-- 65 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>65. maiṃkāreṇa śiraḥsaṃsthaṃ maitreyaṃ parikalpayet |</li>
            <li>bhadraṃ saṃ antato dhyātvā sarvasaṃdhiṣu saṃnyaset ||65 ||</li>
        </ul>

        <!-- 66 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>66. yamāntakaḥ savyabhuje apasavye 'parājitaḥ |</li>
            <li>hayagrīvo mukhe bhāvyo vajre cāmṛtakuṇḍaliḥ || 66 ||</li>
        </ul>

        <!-- 67 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>67. acalaṃ dakṣiṇe bhāge vāme ca ṭakkirājakam |</li>
            <li>jānau ca dakṣiṇe cinten nīladaṇḍaṃ mahojjvalam || 67 ||</li>
        </ul>

        <!-- 68 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>68. vāmajānau mahābalaṃ mūrdhni coṣṇīṣacakriṇam |</li>
            <li>pādāntadvayavinyastaṃ sumbharājaṃ vicintayet || 68 ||</li>
        </ul>

        <!-- 69 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>69. nyāsaṃ kṛtvā tato mantrī skandhādīnāṃ yathāvidhi |</li>
            <li>kāyamaṇḍalam āpanno mahāyogaṃ samārabhet || 69 ||</li>
        </ul>

        <!-- 70 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>70. mūrdhni madhyagataṃ cintet sampūrṇaṃ candramaṇḍalam |</li>
            <li>tatroṃkāraṃ śuklābhaṃ prasphuratpañcaraśmikam || 70 ||</li>
        </ul>

        <!-- 71 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>71. tato devīṃ viniścārya ādhipatyaprayogataḥ |</li>
            <li>locanāṃ vividhāṃ cintet sarvavyomni prapūritām || 71 ||</li>
        </ul>

        <!-- 72 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>72. kāyavajraṃ vicintyātha vyomāpūrya vyavasthitam |</li>
            <li>tanmadhye adhipatiṃ cinted ātmanaś ca puraḥsthitam || 72 ||</li>
        </ul>

        <!-- 73 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>73. dvātriṃśallakṣaṇadharaṃ vyañjanāśītibhūṣitam |</li>
            <li>prārthayet tu tato mantrī gāthādvayam udāharan || 73||</li>
        </ul>

        <!-- 74 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>74. buddhakāyadharaḥ śrīmāṃs trivajrābhedyabhāvitaḥ |</li>
            <li>adhiṣṭhānapadaṃ me 'dya karotu kāyavajriṇaḥ || 74 ||</li>
        </ul>

        <!-- 75 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>75. daśadikṣu sthitā buddhās trivajrābhedyabhāvitāḥ |</li>
            <li>adhiṣṭhānapadaṃ me 'dya kurvantu kāyavajriṇaḥ || 75 ||</li>
        </ul>

        <!-- 76 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>76. locanāsahasaṃyuktaṃ vairocanaṃ vibhāvayet |</li>
            <li>tatpraveśyādhitiṣṭheta pañcaskandhaprapūritam || 76 ||</li>
        </ul>

        <!-- 77 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>77. yatkāyaṃ sarvabuddhānāṃ pañcaskandhaprapūritam |</li>
            <li>buddhakāyasvabhāvena mamāpi tādṛśaṃ bhavet || 77 ||</li>
        </ul>

        <!-- мантра после 77 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>oṃ sarvatathāgatakāyavajrasvabhāvātmako 'ham ||</li>
        </ul>

        <!-- 78 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>78. jihvābjamadhyagataṃ cinted āḥkāraṃ raktavarṇakam |</li>
            <li>pāṇḍarākhyaṃ ca sagaṇaṃ saṃsphared vyomapūritam || 78 ||</li>
        </ul>

        <!-- 79 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>79. vāgvajraṃ ca tathā mantrī vyomāpūrya vyavasthitam |</li>
            <li>prārthayet tu tato mantrī gāthādvayam udāharan || 79 ||</li>
        </ul>

        <!-- 80 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>80. dharmo vai vākpathaḥ śrīmāṃs trivajrābhedyabhāvitaḥ |</li>
            <li>adhiṣṭhānapadaṃ me 'dya karotu vāgvajriṇaḥ || 80 ||</li>
        </ul>

        <!-- 81 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>81. daśadikṣu sthitā buddhās trivajrābhedyabhāvitāḥ |</li>
            <li>adhiṣṭhānapadaṃ me 'dya kurvantu vāgvajriṇaḥ || 81 ||</li>
        </ul>

        <!-- 82 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>82. svanāyakena saṃyuktāṃ pāṇḍarāṃ sahasaiva tu |</li>
            <li>jihvāpraviṣṭāṃ sañcintya vāgadhiṣṭhānam ārabhet || 82 ||</li>
        </ul>

        <!-- 83 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>83. yadeva vajradharmasya vācā niruktisampadā |</li>
            <li>mamāpi tādṛśī vācā bhaved dharmadharopamā || 83 ||</li>
        </ul>

        <!-- мантра после 83 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>oṃ sarvatathāgatavāgvajrasvabhāvātmako 'ham ||</li>
        </ul>

        <!-- 84 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>84. vinyasya hṛdaye mantrī śaśibimbaṃ samujjvalam |</li>
            <li>rājāvartanibhaṃ tatra hūṃkāraṃ pañcaraśmikam || 84 ||</li>
        </ul>

        <!-- 85 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>85. tato niścārayed devīṃ māmakīṃ sagaṇāṃ punaḥ |</li>
            <li>cittavajraṃ tathā dhyātvā prārthayeta yathāpuraḥ || 85 ||</li>
        </ul>

        <!-- 86 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>86. cittavajradharaḥ śrīmāṃs trivajrābhedyabhāvitaḥ |</li>
            <li>adhiṣṭhānapadaṃ me 'dya karotu cittavajriṇaḥ || 86 ||</li>
        </ul>

        <!-- 87 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>87. daśadikṣu sthitā buddhās trivajrābhedyabhāvitāḥ |</li>
            <li>adhiṣṭhānapadaṃ me 'dya kurvantu cittavajriṇaḥ || 87 ||</li>
        </ul>

        <!-- 88 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>88. cittavajrasamāyuktaṃ hṛdaye saṃpraveśya ca |</li>
            <li>māmakīvyūham akhilaṃ cittādhiṣṭhānam ārabhet || 88 ||</li>
        </ul>

        <!-- 89 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>89. yaccittaṃ samantabhadrasya guhyakendrasya dhīmataḥ |</li>
            <li>mamāpi tādṛśaṃ cittaṃ bhaved vajradharopamam || 89 ||</li>
        </ul>

        <!-- мантра после 89 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>oṃ sarvatathāgatacittavajrasvabhāvātmako 'ham ||</li>
        </ul>

        <!-- 90 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>90. evaṃ pṛthag adhiṣṭhāya kulatrayavibhāgataḥ |</li>
            <li>punaḥ sarvātmakaṃ kuryān mantreṇānena buddhimān || 90 ||</li>
        </ul>

        <!-- мантра после 90 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>oṃ sarvatathāgatakāyavākcittavajrasvabhāvātmako 'ham ||</li>
        </ul>

        <!-- 91 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>91. adhiṣṭhāyaivam ātmānaṃ śaśimaṇḍalamadhyagam |</li>
            <li>ṣaḍbhiś cihnaiḥ samāyuktaṃ cintet samayasattvakam || 91 ||</li>
        </ul>

        <!-- 92 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>92. hṛnmadhyasaṃsthitaṃ sūkṣmaṃ jñānasattvaṃ vibhāvayet |</li>
            <li>samādhisattvasaṃjñaṃ ca hūṃkāraṃ taddṛḍhaṃ nyaset || 92 ||</li>
        </ul>

        <!-- 93 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>93. niṣpādyaivaṃ mahāyogaṃ trisattvātmakam ātmavān |</li>
            <li>anena vidhiyogena mahāsādhanam ārabhet || 93 ||</li>
        </ul>

        <!-- 94 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>94. prāpya kanyāṃ viśālākṣīṃ rūpayauvanamaṇḍitām |</li>
            <li>nīlotpaladalaśyāmāṃ rajakasya mahātmanaḥ || 94 ||</li>
        </ul>

        <!-- 95 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>95. suśikṣitāṃ samādāya sādhake bhaktivatsalām |</li>
            <li>oṃkāraṃ śirasi dhyātvā āḥkāraṃ vākpathe nyaset || 95 ||</li>
        </ul>

        <!-- 96 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>96. hūṃkāraṃ hṛdaye dhyātvā svā nābhau hā dvipādayoḥ |</li>
            <li>locanāṃ māmakīṃ cāpi tathā pāṇḍaravāsinīm || 96 ||</li>
        </ul>

        <!-- 97 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>97. tārāṃ cāpi tathā mantrī pṛthivyādiṣu sannyaset |</li>
            <li>rūpavajrādikā devīs tasyām eva vibhāvayet || 97 ||</li>
        </ul>

        <!-- 98 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>98. kṣitigarbhādibhis tāṃs tāṃs samāpattiṃ vibhāvayet |</li>
            <li>dakṣiṇe vajravetālīṃ bhuje vāme 'parājitām || 98 ||</li>
        </ul>

        <!-- 99 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>99. bhṛkuṭiṃ ca mukhe tasyā ekajaṭāṃ ca guhyake |</li>
            <li>bhūyo dakṣiṇapārśvasthāṃ viśvavajrīṃ tathāgatīm || 99 ||</li>
        </ul>

        <!-- 100 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>100. viśvaratnāṃ ca vāme tu mudrāyāḥ pravibhāvayet |</li>
            <li>punar dakṣiṇajānusthāṃ viśvapadmāṃ tathāgatīm || 100 ||</li>
        </ul>

        <!-- 101 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>101. viśvakarmāṃ ca vāme tu mūrdhni gaganavajriṇīm |</li>
            <li>pādāntadvayavinyastāṃ dharaṇīndharadevatīm || 101 ||</li>
        </ul>

        <!-- 102 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>102. evaṃ saṃskṛtya tāṃ yogī vajrapadmam athārabhet |</li>
            <li>mantrī hūṃkārajaṃ vajraṃ dhyāyād vai pañcaśūcikam || 102 ||</li>
        </ul>

        <!-- 103 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>103. madhyasūcau tathā tasya praṇavaṃ ca vibhāvayet |</li>
            <li>tathaivāṣṭadalaṃ padmam āḥkāreṇa tu bhāvayet || 103 ||</li>
        </ul>

        <!-- 104 (одна строка) -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>104. pañcaraśmisamākīrṇaṃ tataḥ sādhanam ārabhet || 104 ||</li>
        </ul>

        <!-- мантра после 104 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>oṃ sarvatathāgatanurāgaṇavajrasvabhāvātmako 'ham ||</li>
        </ul>

        <!-- 105 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>105. hūṃkāragītena tu cālayet taṃ samudvahan vajradharasya garvam |</li>
            <li>svabodhicittodayakāla eva phaṭkāramantraṃ samudīrayet saḥ || 105 ||</li>
        </ul>

        <!-- 106 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>106. visargānte punar mantrī bodhicittena pūjayet |</li>
            <li>daśadikṣusthitān buddhān mantram etad udīrayet || 106 ||</li>
        </ul>

        <!-- мантра после 106 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>oṃ sarvatathāgatapūjāvajrasvabhāvātmako 'ham ||</li>
        </ul>

        <!-- 107 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>107. svamantrākṣaraniṣpannaṃ trivajrādhiṣṭhitasvakam |</li>
            <li>padmamadhye tu niṣpādya dveṣavajro bhavet punaḥ || 107 ||</li>
        </ul>

        <!-- 108 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>108. vajradhṛg-mantraniṣpannaṃ paśyed akṣobhyavajriṇam |</li>
            <li>jaṭāmukuṭadharaṃ nātham akṣobhyakṛtaśekharam || 108 ||</li>
        </ul>

        <!-- 109 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>109. rājāvartaśukasaṅkāśaṃ kṛṣṇaraktasitānanam |</li>
            <li>sarvālaṅkārasampūrṇaṃ ṣaḍbhujaṃ tu vibhāvayet || 109 ||</li>
        </ul>

        <!-- 110 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>110. vajraṃ cakraṃ tathā padmaṃ savyahasteṣu dhārayet |</li>
            <li>ghaṇṭāṃ cintāmaṇiṃ khaḍgaṃ tasya vāmeṣu bhāvayet || 110 ||</li>
        </ul>

        <!-- 111 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>111. niṣkramya hṛdayād eṣa vyavalokya diśo daśa |</li>
            <li>buddharddhim akhilāṃ kṛtvā dharmacakraṃ pravartya ca || 111 ||</li>
        </ul>

        <!-- 112 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>112. saṃśodhya nikhilān sattvān dveṣavajrapade sthitān |</li>
            <li>āgatya vajranāthasya purato 'bhiniṣīdati || 112 ||</li>
        </ul>

        <!-- 113 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>113. anupraveśya taṃ mantrī hṛdy ātmānaṃ vibhāvayet |</li>
            <li>pūrvarūpaṃ parāvṛttya dveṣavajrapade sthitaḥ || 113 ||</li>
        </ul>

        <!-- 114 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>114. indranīlaprabhaṃ dīptaṃ sūryamaṇḍalamadhyagam |</li>
            <li>svamudrāliṅgitaṃ vīraṃ sarvālaṅkārabhūṣitam || 114 ||</li>
        </ul>

        <!-- 115 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>115. raudraśāntamahā rāgaṃ mukhatrayavirājitam |</li>
            <li>dveṣavajrasamādhisthaḥ protsṛjet sarvamaṇḍalam || 115 ||</li>
        </ul>

        <!-- 116 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>116. jinajig-mantraniṣpannaṃ sṛjed vairocanaṃ vibhum |</li>
            <li>śaraccandrāṃśusaṅkāśaṃ jaṭāmukuṭamaṇḍitam || 116 ||</li>
        </ul>

        <!-- 117 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>117. sitaraktakṛṣṇavadanaṃ ṣaḍbhujaṃ śāntarūpiṇam |</li>
            <li>cakravajrasitāmbhojaṃ dakṣiṇeṣu vicintayet || 117 ||</li>
        </ul>

        <!-- 118 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>118. ghaṇṭāṃ cintāmaṇiṃ khaḍgaṃ vāmeṣvasya vibhāvayet |</li>
            <li>hṛdayāt tathaiva nirgatya mohacaryāsthitāḥ prajāḥ || 118 ||</li>
        </ul>

        <!-- 119 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>119. saṃśodhya punar āgatya punaścakre niṣīdati |</li>
            <li>ratnadhṛg-mantraniṣpannaṃ ratnaketuṃ sṛjed budhaḥ || 119 ||</li>
        </ul>

        <!-- 120 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>120. jaṭājūṭadharaṃ saumyam akṣobhyakṛtaśekharam |</li>
            <li>pītakṛṣṇasitāsyaṃ ca ṣaḍbhujaṃ cāpi cintayet || 120 ||</li>
        </ul>

        <!-- 121 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>121. tasya cintāmaṇiṃ vajraṃ cakraṃ savyeṣu bhāvayet |</li>
            <li>ghaṇṭāṃ ca pītakamalaṃ khaḍgaṃ vāmeṣu bhāvayet || 121 ||</li>
        </ul>

        <!-- 122 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>122. hṛdayāt tathaiva nirgatya ahaṅkārapade sthitān |</li>
            <li>saṃśodhya dakṣiṇe bhāge ratnamadhye niṣīdati || 122 ||</li>
        </ul>

        <!-- 123 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>123. ārolik-mantraniṣpannaṃ sṛjed amitavajriṇam |</li>
            <li>padmarāgaprabhaṃ saumyam akṣobhyakṛtaśekharam || 123 ||</li>
        </ul>

        <!-- 124 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>124. jaṭāmukuṭadharaṃ nāthaṃ raktakṛṣṇasitānanam |</li>
            <li>śṛṅgārarasasaṃyuktaṃ ṣaḍbhujaṃ tu vibhāvayet || 124 ||</li>
        </ul>

        <!-- 125 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>125. padmanālaṃ gṛhītvā tu vāmena saha ghaṇṭayā |</li>
            <li>hṛtpradeśasthitaṃ padmaṃ dakṣiṇena vikāśayet || 125 ||</li>
        </ul>

        <!-- 126 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>126. savyayoḥ vajracakre tu vāmayoḥ ratnakhaḍgakau |</li>
            <li>pūrvavad rāgiṇaḥ śodhya pṛṣṭhato 'bje niṣīdati || 126 ||</li>
        </ul>

        <!-- 127 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>127. amoghavajriṇaṃ mantrī prajñādhṛg-mantranirmitam |</li>
            <li>haritābhaṃ sṛjen nāthaṃ jaṭāmukuṭamaṇḍitam || 127 ||</li>
        </ul>

        <!-- 128 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>128. haritakṛṣṇasitāsyaṃ ca ṣaḍbhujaṃ raśmibhāsuram |</li>
            <li>khaḍgaṃ ca viśvavajraṃ ca cakraṃ savyeṣu bhāvayet || 128 ||</li>
        </ul>

        <!-- 129 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>129. ghaṇṭāṃ vāmeṣu hasteṣu haritapadmaṃ maṇiṃ tathā |</li>
            <li>īrṣyādosastha-sattvānāṃ viṣodhya punar āgataḥ || 129 ||</li>
        </ul>

        <!-- 130 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>130. uttarasyāṃ diśi tathā viśvavajre niṣīdati |</li>
            <li>dveṣo mohas tathā rāgaś cintāmaṇiḥ samayas tathā || 130 ||</li>
        </ul>

        <!-- 131 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>131. kulā hy ete tu vai pañca kāmamokṣaprasādhakāḥ |</li>
            <li>moharatyādibhir jātāṃ sṛjed devīṃ tu locanām || 131 ||</li>
        </ul>

        <!-- 132 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>132. śvetāṃ śāntarasopetāṃ mūrdhni vairocanāṅkitām |</li>
            <li>sitaraktakṛṣṇavadanāṃ ṣaḍbhujāṃ tu vibhāvayet || 132 ||</li>
        </ul>

        <!-- 133 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>133. savye cakraṃ ca vajraṃ ca tathaiva sitam utpalam |</li>
            <li>vāme ghaṇṭāṃ tathā ratnaṃ khaḍgaṃ cāpi vibhāvayet || 133 ||</li>
        </ul>

        <!-- 134 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>134. hṛdayāt tu vinirgatya vyavalokya diśo daśa |</li>
            <li>grahavyādhyāture loke śāntiṃ kṛtvā mahākṛpāḥ || 134 ||</li>
        </ul>

        <!-- 135 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>135. āgatya cakramadhye tu pūrvakoṇe niṣīdati |</li>
            <li>mantrād dveṣarater jātāṃ sṛjed devīṃ tu māmakīm || 135 ||</li>
        </ul>

        <!-- 136 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>136. nīlotpaladalaśyāmāṃ cāruvaktrāṃ manoramām |</li>
            <li>kṛṣṇaraktasitāsyāṃ ca akṣobhyakṛtaśekharām || 136 ||</li>
        </ul>

        <!-- 137 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>137. savyeṣu vajraṃ cakraṃ ca nīlaraktotpalaṃ tathā |</li>
            <li>ghaṇṭāṃ ratnaṃ ca khaḍgaṃ ca vāmahasteṣu dhārayet || 137 ||</li>
        </ul>

        <!-- 138 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>138. mahāvighnabhayārtānāṃ rakṣāṃ kṛtvā mahākṛpāḥ |</li>
            <li>niṣkramya punar āgatya nairṛtyāṃ sā niṣīdati || 138 ||</li>
        </ul>

        <!-- 139 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>139. mantrād rāgarater jātāṃ sṛjet pāṇḍaravāsinīm |</li>
            <li>raktakṛṣṇasitāsyāṃ vai padmarāgamaṇiprabhām || 139 ||</li>
        </ul>

        <!-- 140 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>140. sāmitābhajaṭājūṭāṃ ṣaḍbhujāṃ tu vibhāvayet |</li>
            <li>gṛhītvotpalanālaṃ tu vāmena saha ghaṇṭayā || 140 ||</li>
        </ul>

        <!-- 141 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>141. utpalaṃ hṛtpradeśasthaṃ raktaṃ savyena bodhayet |</li>
            <li>vajraṃ cakraṃ ca savyābhyāṃ maṇiṃ khaḍgaṃ ca vāmataḥ || 141 ||</li>
        </ul>

        <!-- 142 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>142. dhārayantī vinirgatya śāntiṃ kṛtvā mahāture |</li>
            <li>āgatya padmamadhye ca vāyukoṇe niṣīdati || 142 ||</li>
        </ul>

        <!-- 143 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>143. mantrād vajrarater jātāṃ sṛjet tārāṃ manoramām |</li>
            <li>haritakṛṣṇasitāsyāṃ ca dūrvāpatrasamaprabhām || 143 ||</li>
        </ul>

        <!-- 144 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>144. amoghena kṛtoṣṇīṣāṃ ṣaḍbhujāṃ tu vibhāvayet |</li>
            <li>viśvavajraṃ ca cakraṃ ca savyato 'sitam utpalam || 144 ||</li>
        </ul>

        <!-- 145 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>145. vāmeṣu vinyased ghaṇṭāṃ ratnaṃ khaḍgaṃ tathā vratī |</li>
            <li>sarvasattvān vaśīkṛtya viśvavajrāsanāḥ punaḥ || 145 ||</li>
        </ul>

        <!-- 146 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>146. nirgatā 'sau samāgamya śivasthāne niṣīdati |</li>
            <li>dvitīye tu puṭe yogī rūpavajrādikaṃ sṛjet || 146 ||</li>
        </ul>

        <!-- 147 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>147. agnikoṇe sṛjed devīṃ rūpavajrāṃ manoramām |</li>
            <li>trimukhāṃ ṣaḍbhujāṃ śvetāṃ śrīvairocanamaulikām || 147 ||</li>
        </ul>

        <!-- 148 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>148. gṛhītadarpaṇāṃ dvābhyāṃ śeṣaṃ moharater iva |</li>
            <li>nairṛtyāṃ vinyased devīṃ śabdavajrāṃ tu ṣaḍbhujām || 148 ||</li>
        </ul>

        <!-- 149 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>149. pītavarṇāṃ trivaktrāṃ ca ratnasambhavamaulikām |</li>
            <li>vīṇāvyagradvihastāṃ ca śeṣaṃ māmakīvad bhavet || 149 ||</li>
        </ul>

        <!-- 150 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>150. vāyusthāne nyased devīṃ gandhavajrāṃ tu ṣaḍbhujām |</li>
            <li>raktavarṇāṃ trivaktrāṃ ca amitābhajaṭādharām || 150 ||</li>
        </ul>

        <!-- 151 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>151. śaṅkhavyagradvihastāṃ ca śeṣaiḥ pāṇḍaravāsinīm |</li>
            <li>aiśānyāṃ vinyased devīṃ rasavajrāṃ tu ṣaḍbhujām || 151 ||</li>
        </ul>

        <!-- 152 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>152. trimukhāṃ śyāmavarṇāṃ ca dundubhisvaramaulikām |</li>
            <li>hastastharasabhāṇḍāṃ ca śeṣais tārāsamākṛtim || 152 ||</li>
        </ul>

        <!-- 153 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>153. vajrasattvaṃ samāliṅgya cakramadhye vyavasthitām |</li>
            <li>cintayet sparśavajrāṃ tu patitulyāṃ mukhādibhiḥ || 153 ||</li>
        </ul>

        <!-- 154 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>154. tṛtīye tu puṭe pūrve paṭṭikāyāṃ sṛjed vratī |</li>
            <li>maiṃ-thlīṃ bījaviniṣpannau maitreyakṣitigarbhakau || 154 ||</li>
        </ul>

        <!-- 155 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>155. praṇavena samutpannau vajrapāṇikhagarbhakau |</li>
            <li>paṭṭikāyāṃ sṛjet mantrī dakṣiṇāyāṃ yathākramam || 155 ||</li>
        </ul>

        <!-- 156 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>156. oṃ-hūṃkāraviniṣpannau lokeśaṃ mañjughoṣakam |</li>
            <li>paścimāyāṃ sṛjed etāv uttarasyāṃ punaḥ sṛjet || 156 ||</li>
        </ul>

        <!-- 157 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>157. oṃ-saṃ-bījaviniṣpannau saviṣkambhisamantakam |</li>
            <li>ete svanāthamukuṭā varṇādyais tatsamāḥ punaḥ || 157 ||</li>
        </ul>

        <!-- 158 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>158. bhujaiḥ praharaṇaiś cāpi svasvādhipatibhiḥ samāḥ |</li>
            <li>maitreyaḥ kevalaṃ savye nāgapuṣpaṃ bibharti ca || 158 ||</li>
        </ul>

        <!-- 159 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>159. saṃśodhyāyatanāny ete divyanetrādidāyakāḥ |</li>
            <li>sattvānāṃ punar āgatya niṣīdanty āsaneṣu vai || 159 ||</li>
        </ul>

        <!-- 160 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>160. yamāntakṛnmantrabhavaṃ kṛṣṇaraktasitānanam |</li>
            <li>yamāntakaṃ sṛjet mantrī sphuliṅgagahanākulam || 160 ||</li>
        </ul>

        <!-- 161 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>161. daṇḍaṃ cakraṃ tathā vajraṃ savyahasteṣu dhārayan |</li>
            <li>hṛddeśe tarjanīpāśaṃ ghaṇṭāparaśuṃ ca vāmataḥ || 161 ||</li>
        </ul>

        <!-- 162 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>162. vighnān santrāsayan ghorān indrādīn sagaṇān api |</li>
            <li>padmasūryaṃ samākramya pūrvasyāṃ diśi tiṣṭhati || 162 ||</li>
        </ul>

        <!-- 163 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>163. prajñāntakṛnmantrabhavaṃ ratnasambhavamaulikam |</li>
            <li>aparājitaṃ sṛjet mantrī śvetābhamaṇibhūṣaṇam || 163 ||</li>
        </ul>

        <!-- 164 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>164. sitakṛṣṇaraktavadanaṃ bṛhatkukṣiṃ trilocanam |</li>
            <li>daṃṣṭrākarālavikaṭaṃ sphuliṅgagahanākulam || 164 ||</li>
        </ul>

        <!-- 165 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>165. vajraṃ daṇḍaṃ tathā khaḍgaṃ savyahasteṣu dhārayan |</li>
            <li>hṛddeśe tarjanīpāśaṃ ghaṇṭāṃ paraśuṃ ca vāmataḥ || 165 ||</li>
        </ul>

        <!-- 166 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>166. vighnān santrāsayan ghorān pratyālīḍhapadena tu |</li>
            <li>padmasūryaṃ samākramya yāmyāṃ diśi sa tiṣṭhati || 166 ||</li>
        </ul>

        <!-- 167 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>167. padmāntakṛnmantrabhavaṃ hayagrīvaṃ sṛjed vratī |</li>
            <li>padmarāganibhaṃ tryakṣaṃ raktakṛṣṇasitānanam || 167 ||</li>
        </ul>

        <!-- 168 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>168. karālāsyaṃ bṛhatkukṣim amitābhakirīṭinam |</li>
            <li>pratyālīḍhapadaṃ vīraṃ sphuliṅgagahanākulam || 168 ||</li>
        </ul>

        <!-- 169 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>169. padmaṃ khaḍgaṃ ca musalaṃ savyahasteṣu bhāvayet |</li>
            <li>ghaṇṭāṃ ca garva-paraśuṃ pāśaṃ savyetareṣu ca || 169 ||</li>
        </ul>

        <!-- 170 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>170. padmasūryaṃ samāruhya vyavalokya diśo daśa |</li>
            <li>vighnasantrāsanaṃ kṛtvā vāruṇyāṃ diśi tiṣṭhati || 170 ||</li>
        </ul>

        <!-- 171 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>171. vighnāntakṛnmantrabhavaṃ dundubhisvaramaulikam |</li>
            <li>nīlotpaladalaśyāmaṃ sṛjed amṛtakuṇḍalinam || 171 ||</li>
        </ul>

        <!-- 172 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>172. nīlaraktasitāsyaṃ ca karālamukhavibhramam |</li>
            <li>bṛhatkukṣiṃ trinayanaṃ raktajvālāvibhūṣitam || 172 ||</li>
        </ul>

        <!-- 173 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>173. viśvavajraṃ tathā cakraṃ musalaṃ cāpi savyataḥ |</li>
            <li>dhārayaṃs tarjanīpāśaṃ ghaṇṭāṃ paraśuṃ ca vāmataḥ || 173 ||</li>
        </ul>

        <!-- 174 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>174. vighnasaṃtrāsanaṃ kṛtvā pratyālīḍhapadena tu |</li>
            <li>padmasūryaṃ samāruhya kauberyāṃ diśi tiṣṭhati || 174 ||</li>
        </ul>

        <!-- 175 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>175. svamantrākṣaraniṣpannam acalaṃ ca sṛjet punaḥ |</li>
            <li>indranīlaprabhaṃ tryakṣaṃ śrīvairocanamaulikam || 175 ||</li>
        </ul>

        <!-- 176 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>176. daṃṣṭrākarālavadanaṃ kṛṣṇaraktasitānanam |</li>
            <li>aṭṭahāsaravaṃ ghoraṃ bṛhatkukṣiṃ mahābalam || 176 ||</li>
        </ul>

        <!-- 177 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>177. khaḍgaṃ vajraṃ tathā cakraṃ savyahasteṣu dhārayet |</li>
            <li>tarjanīṃ cāpi paraśuṃ pāśaṃ vāmeṣu pāṇiṣu || 177 ||</li>
        </ul>

        <!-- 178 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>178. vighnān jvarādikān hatvā pratyālīḍhapadena tu |</li>
            <li>padmasūryaṃ samāruhya vahnisthāne sa tiṣṭhati || 178 ||</li>
        </ul>

        <!-- 179 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>179. svamantra-akṣaraniṣpannaṃ ṭakkirājaṃ sṛjed vratī |</li>
            <li>indranīlaprabhaṃ vīraṃ ratnasambhavamaulikam || 179 ||</li>
        </ul>

        <!-- 180 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>180. kṛṣṇaraktasitāsyaḥ ca bṛhatkukṣiṃ bhayānakam |</li>
            <li>dadhānaṃ vajraṃ hūṃkāramudrāṃ pāṇidvayena tu || 180 ||</li>
        </ul>

        <!-- 181 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>181. vajraṃ khaḍgaṃ ca savyābhyāṃ vāmataḥ pāśamaṅkuśam |</li>
            <li>pratyālīḍhena sūryastho nairṛtyāṃ vighnanāśakaḥ || 181 ||</li>
        </ul>

        <!-- 182 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>182. svamantra-akṣaraniṣpannaṃ nīladaṇḍaṃ sṛjed vratī |</li>
            <li>nīlameghanibhaṃ tryakṣam amitābhakirīṭinam || 182 ||</li>
        </ul>

        <!-- 183 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>183. nīlaraktasitāsyaṃ ca bṛhatkukṣiṃ bhayāvaham |</li>
            <li>daṇḍaṃ khaḍgaṃ tathā cakraṃ savyahasteṣu dhārayan || 183 ||</li>
        </ul>

        <!-- 184 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>184. hṛddeśe tarjanīpāśaṃ padmaṃ paraśuṃ ca vāmataḥ |</li>
            <li>hatvopadravabhayaṃ pratyālīḍhapade sthitaḥ || 184 ||</li>
        </ul>

        <!-- 185 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>185. padmasūryaṃ samāruhya vāyavyāṃ diśi tiṣṭhati |</li>
            <li>svamantra-akṣaraniṣpannaṃ dundubhisvaramaulikam || 185 ||</li>
        </ul>

        <!-- 186 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>186. mahābalaṃ sṛjet mantrī nīlotpaladalaprabham |</li>
            <li>kṛṣṇaraktasitāsyaṃ ca tryakṣaṃ bhairavanāditam || 186 ||</li>
        </ul>

        <!-- 187 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>187. nāgabhūṣitasarvāṅgaṃ bṛhatkukṣiṃ bhayānakam |</li>
            <li>daṇḍaṃ khaḍgaṃ tathā cakraṃ savyahasteṣu dhārayan || 187 ||</li>
        </ul>

        <!-- 188 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>188. hṛddeśe tarjanīpāśaṃ padmaṃ paraśuṃ ca vāmataḥ |</li>
            <li>hatvopadravabhayaṃ pratyālīḍhapade sthitaḥ || 188 ||</li>
        </ul>

        <!-- 189 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>189. padmasūryaṃ samāruhya aiśānyāṃ diśi tiṣṭhati |</li>
            <li>svamantra-akṣaraniṣpannaṃ sṛjed uṣṇīṣacakriṇam || 189 ||</li>
        </ul>

        <!-- 190 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>190. ākāśaśyāmakaṃ ghoraṃ akṣobhyakṛtaśekharam |</li>
            <li>kṛṣṇaraktasitāsyaḥ ca tryakṣaṃ lambodaraṃ vibhum || 190 ||</li>
        </ul>

        <!-- 191 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>191. vāmadakṣiṇahastābhyām uṣṇīṣaṃ mūrdhni dhārayan |</li>
            <li>vajrapadmaṃ ca savyābhyāṃ tarjanīkhaḍgam anyataḥ || 191 ||</li>
        </ul>

        <!-- 192 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>192. sarvopadravavidhvaṃsī pratyālīḍhapadodyataḥ |</li>
            <li>padmasūryaṃ samāruhya brahmasthāne sa tiṣṭhati || 192 ||</li>
        </ul>

        <!-- 193 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>193. svamantra-akṣaraniṣpannaṃ sumbharājaṃ sṛjed vratī |</li>
            <li>ākāśasuprabhaṃ tryakṣaṃ kṛṣṇaraktasitānanam || 193 ||</li>
        </ul>

        <!-- 194 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>194. bṛhatkukṣiṃ karālāsyam akṣobhyakṛtaśekharam |</li>
            <li>vajraṃ cakraṃ tathā ratnaṃ savyahasteṣu dhārayan || 194 ||</li>
        </ul>

        <!-- 195 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>195. hṛddeśe tarjanīpāśaṃ padmakhaḍgaṃ ca vāmataḥ |</li>
            <li>kālakūṭādikaṃ sarvaviṣaṃ sthāvarajaṅgamam || 195 ||</li>
        </ul>

        <!-- 196 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>196. hatvā vināyakān sarvān śāntiṃ kṛtvā tu sarvataḥ |</li>
            <li>ājñāṃ sampādya nikhilāṃ pratyālīḍhapade sthitaḥ || 196 ||</li>
        </ul>

        <!-- 197 (одна строка) -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>197. padmasūryaṃ samāruhya bhuvo 'dhastāt sa tiṣṭhati || 197 ||</li>
        </ul>

        <!-- 198 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>198. utsṛjya maṇḍalaṃ sarvaṃ dvātriṃśaddevatāmayam |</li>
            <li>cakramadhyasthito bhūtvā sūkṣmayogam athārabhet || 198 ||</li>
        </ul>

        <!-- 199 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>199. nāsāgre sarṣapaṃ cintet sarṣape sacarācaram |</li>
            <li>bhāvayej jñānapadaṃ ramyaṃ rahasyaṃ mantrakalpitam || 199 ||</li>
        </ul>

        <!-- 200 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>200. pañcavarṇaṃ mahāratnaṃ sarṣapasthūlamātrakam |</li>
            <li>nāsikāgre prayatnena bhāvayed yogataḥ sadā || 200 ||</li>
        </ul>

        <!-- 201 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>201. sthiraṃ tu sphārayed ratnam asthiraṃ naiva sphārayet |</li>
            <li>sphārayet pravarair meghair buddhajvālāsamaprabhaiḥ || 201 ||</li>
        </ul>

        <!-- 202 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>202. bhikṣāśinā na japtavyaṃ na ca bhaikṣārato bhavet |</li>
            <li>japen mantram abhinnāṅgaṃ sarvakāmopabhogakṛt || 202 ||</li>
        </ul>

        <!-- 203 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>203. uccārya saṃsphared vajraṃ samāptaṃ saṃhāram ādiśet |</li>
            <li>idaṃ tat sarvabuddhānāṃ japoktaṃ paramārthataḥ || 203 ||</li>
        </ul>

        <!-- 204 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>204. sūkṣmayogajapaṃ cāpi dvidhā kṛtvā yathāruci |</li>
            <li>ātmānaṃ ca punar mantrī tathatāyāṃ praveśayet || 204 ||</li>
        </ul>

        <!-- 205 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>205. maṇḍalasthāś caturdevyo na paśyantyas tataḥ patim |</li>
            <li>gāthācatuṣṭayenetthaṃ bodhayanti mahāsukham || 205 ||</li>
        </ul>

        <!-- 206 (четыре строки) -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>206. tvaṃ vajrasattva bhuvaneśvara sattvadhāto |</li>
            <li>trāyāhi māṃ ratimanojña mahārthakāmaiḥ |</li>
            <li>kāmāhi māṃ janaka sattvamahāgrabandho |</li>
            <li>yadīcchase jīvatu mahya nātha || 206 ||</li>
        </ul>

        <!-- 207 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>207. tvaṃ vajrakāya bahusattvapriyāgracakra |</li>
            <li>buddhārthabodhiparamārthahitānudarśī |</li>
            <li>rāgeṇa rāgasamayāṃ māṃ kāmayasva |</li>
            <li>yadīcchase jīvatu mahya nātha || 207 ||</li>
        </ul>

        <!-- 208 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>208. tvaṃ vajravāca sakalasya hitānukampī |</li>
            <li>lokārthakāryakaraṇe sadā sampravṛttaḥ |</li>
            <li>kāmāhi māṃ suratacarya samantabhadra |</li>
            <li>yadīcchase jīvatu mahya nātha || 208 ||</li>
        </ul>

        <!-- 209 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>209. tvaṃ vajrakāma samayāgra mahāhitārtha |</li>
            <li>sambuddhavaṃśatilakaḥ samatānukampī |</li>
            <li>kāmāhi māṃ guṇanidhiṃ bahuratnabhūtam |</li>
            <li>yadīcchase jīvatu mahya nātha || 209 ||</li>
        </ul>

        <!-- 210 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>210. evam utthāpito nāthaḥ sadbhūtaguṇakīrtanaiḥ |</li>
            <li>akṣobhyādisvabhāvena saṃstuvanti tathāgatāḥ || 210 ||</li>
        </ul>

        <!-- 211 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>211. akṣobhyavajra mahājñāna vajradhātumahābudha |</li>
            <li>trimaṇḍala trivajrāgra bhāṣa guhyaṃ namo'stu te || 211 ||</li>
        </ul>

        <!-- 212 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>212. vairocana mahāśuddha vajraśānta mahārate |</li>
            <li>prakṛtiprabhāsvarān dharmān deśa vajra namo'stu te || 212 ||</li>
        </ul>

        <!-- 213 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>213. ratnarāja sugāmbhīra khavajrākāśanirmala |</li>
            <li>svabhāvaśuddha nirlepa bhāṣa guhyaṃ namo'stu te || 213 ||</li>
        </ul>

        <!-- 214 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>214. vajrāmitamahārāja nirvikalpa khavajradhṛk |</li>
            <li>rāgapāramitāprāpta bhāṣa vajra namo'stu te || 214 ||</li>
        </ul>

        <!-- 215 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>215. amoghavajra saṃbuddha sarvāśāparipūraka |</li>
            <li>śuddhasvabhāvasambhūta vajrasattva namo'stu te || 215 ||</li>
        </ul>

        <!-- 216 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>216. nutvātha buddhair anurāgya cakraṃ prakāśya guhyaṃ paramaṃ yathāyatham |</li>
            <li>svakāyacakre viniveśya cakraṃ mahāsukhas tiṣṭhati nātha ekaḥ || 216 ||</li>
        </ul>

        <!-- 217 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>217. evaṃ caturyogakaras tu yogī hūṃkāragarbhaṃ pravicintya lokam |</li>
            <li>dṛṣṭvā jagat tadbhavavajrasattvaṃ vyutthāya taddhīr vicared yathāvad || iti || 217 ||</li>
        </ul>

        <!-- 218 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>218. samādhim ālambayan mantrī śuṣkamūrtir yadā bhavet |</li>
            <li>vicintayed imaṃ yogaṃ kāyavākcittaprīṇanam || 218 ||</li>
        </ul>

        <!-- 219 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>219. vitastimātram ākramya mūrdhni maṇḍalakalpanā |</li>
            <li>oṃkāraṃ tatragaṃ dhyātvā pañcāmṛtanipātanam || 219 ||</li>
        </ul>

        <!-- 220 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>220. anena vajrayogena tejasvī bhavati kṣaṇāt |</li>
            <li>kāyavākcittasausthityaṃ labhate nātra saṃśayaḥ || 220 ||</li>
        </ul>

        <!-- 221 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>221. evam abhyāsato mantrī śodhayed bodhayet yathā |</li>
            <li>hṛtkaṇṭhaṃ caiva saṃśodhya prīṇayec ca tathāgatān || 221 ||</li>
        </ul>

        <!-- 222 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>222. hūṃkāreṇa ca saṃśodhya āḥkāreṇa tu bodhayet |</li>
            <li>jvālayet praṇavākrāntam iyam āhāraśodhanā || 222 ||</li>
        </ul>

        <!-- 223 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>223. kaṇṭhe śaṅkhaṃ vicintyādau tasmin hrīṃkārasambhavam |</li>
            <li>padmam aṣṭadalaṃ cinted hūṃkāraṃ karṇikopari || 223 ||</li>
        </ul>

        <!-- 224 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>224. hūṃkārajaṃ mahāvajraṃ pañcaśūcaṃ vibhāvayet |</li>
            <li>madhyaśūcāgre sañcinted oṃkāraṃ kaṇṭhaśodhanam || 224 ||</li>
        </ul>

        <!-- 225 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>225. meghanādaṃ hṛdi dhyātvā triśikhāgniṃ tataḥ spharet |</li>
            <li>tatrāhāraṃ ca juhuyād homam ādhyātmikaṃ tvidam || 225 ||</li>
        </ul>

        <!-- 226 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>226. vāyavyaṃ dīpayati agniṃ vāruṇaṃ pacate tu saḥ |</li>
            <li>māhendramaṇḍalasthānaṃ yatra sañcarate haviḥ || 226 ||</li>
        </ul>

        <!-- 227 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>227. annaṃ pānaṃ ca yat kiñcit tat sarvaṃ vāruṇena tu |</li>
            <li>aśanaṃ mukhapadmena hṛtpadmaṃ sampraveśayet || 227 ||</li>
        </ul>

        <!-- 228 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>228. nābhipadmagataṃ paścāt saṃpuṭīkaraṇayogataḥ |</li>
            <li>gūḍhapadmād vinirgatya bhasmāntaṃ ca vinirdiśet || 228 ||</li>
        </ul>

        <!-- 229 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>229. na jarā nāpi rogaś ca na mṛtyur na viṣādikam |</li>
            <li>nākālamaraṇaṃ tasya sarvopadravanāśanam || iti || 229 ||</li>
        </ul>

        <!-- 230 -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>230. śrīvajramālāvarmanthanena gūḍhaṃ samājāmbunidhiṃ mathitvā |</li>
            <li>yat sādhanāṅgāmṛtam āpi tena lokaḥ samasto 'maratām upaitu || 230 ||</li>
        </ul>

        <!-- заключительные строки без номеров -->
        <ul class="list-none mb-0 pl-2 space-y-2 ml-2">
            <li>|| piṇḍīkṛtasādhanaṃ samāptam ||</li>
            <li>|| kṛtir ācāryaśrīnāgārjunapādānām ||</li>
        </ul>
            </details>
    </div>

@endsection
